INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86361, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "够是不多也不少，正好可以。", "primary_collocate": null, "pronunciation": "gòu", "ipa": "koʊ˥˩", "syllable_count": 1, "sentences": [{"text": "一人一个苹果，正好够。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些衣服够我穿一个星期了。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一碗饭就够我吃了。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜两个人吃刚刚够。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包不用多买，三个就够。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一杯水就够了。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房子够我们一家住了。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你带五百块就够，不要多带。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤放一勺盐就够了。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书够我看一个月了。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夠", "label": "繁体"}, {"form": "够了", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，数量不多不少，正好满足需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86361, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，表示不多不少，正好可以。"}, {"text": "狗", "is_correct": false, "explanation": "gǒu（第三声）与 gòu（第四声）声调不同，意思是狗。"}, {"text": "扣", "is_correct": false, "explanation": "kòu 与 gòu 声母不同（k 与 g），声调相同，意思是扣子、扣除。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 gòu 韵母不同（-ui 与 -ou），声调相同，意思是贵重、价格高。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 gòu 韵母不同（-u 与 -ou），声调相同，意思是缘故、事故。"}], "explanations": {"够": "正确答案：“够”，表示不多不少，正好可以。", "狗": "gǒu（第三声）与 gòu（第四声）声调不同，意思是狗。", "扣": "kòu 与 gòu 声母不同（k 与 g），声调相同，意思是扣子、扣除。", "贵": "guì 与 gòu 韵母不同（-ui 与 -ou），声调相同，意思是贵重、价格高。", "故": "gù 与 gòu 韵母不同（-u 与 -ou），声调相同，意思是缘故、事故。"}, "sentence_index": null, "correct_answer": "够"}, "level_3": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，表示苹果数量恰好满足每人一个。"}, {"text": "缺", "is_correct": false, "explanation": "语义：“缺”表示不足，与“正好”所表示的恰好够用相矛盾。"}, {"text": "剩", "is_correct": false, "explanation": "搭配：“剩”单用不完整，需说“剩下”或“剩余”，句子说不通。"}, {"text": "多", "is_correct": false, "explanation": "语义：“多”表示超出，与“正好”所表示的恰好够用相矛盾。"}], "explanations": {"够": "正确答案：“够”，表示苹果数量恰好满足每人一个。", "缺": "语义：“缺”表示不足，与“正好”所表示的恰好够用相矛盾。", "剩": "搭配：“剩”单用不完整，需说“剩下”或“剩余”，句子说不通。", "多": "语义：“多”表示超出，与“正好”所表示的恰好够用相矛盾。"}, "sentence_index": 0, "correct_answer": "够"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱苹果比那箱够，正好多一倍。", "explanation": "这里应该用〈多〉。“够”表示恰好足够，不用于比较两者的多少，应说“这箱苹果比那箱多一倍”。"}, {"text": "他跑了两圈，刚好够了终点。", "explanation": "这里应该用〈到达〉。“够”不能直接带“终点”作宾语，表示到达要说“到达终点”。"}, {"text": "我们的人正好够，还要再找三个。", "explanation": "这里应该用〈不够〉。“正好够”表示数量恰好，与后面“还要再找三个”矛盾，表示数量不足要用“不够”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86361, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，表示不多不少，正好可以。"}, {"text": "豆", "is_correct": false, "explanation": "dòu 与 gòu 声母不同（d 与 g），声调相同，意思是豆子。"}, {"text": "透", "is_correct": false, "explanation": "tòu 与 gòu 声母不同（t 与 g），声调相同，意思是透明、透过。"}, {"text": "候", "is_correct": false, "explanation": "hòu 与 gòu 声母不同（h 与 g），声调相同，意思是时候、等候。"}, {"text": "过", "is_correct": false, "explanation": "guò 与 gòu 韵母不同（-uo 与 -ou），声调相同，意思是经过。"}, {"text": "勾", "is_correct": false, "explanation": "gōu（第一声）与 gòu（第四声）声调不同，意思是勾画、钩子。"}], "explanations": {"够": "正确答案：“够”，表示不多不少，正好可以。", "豆": "dòu 与 gòu 声母不同（d 与 g），声调相同，意思是豆子。", "透": "tòu 与 gòu 声母不同（t 与 g），声调相同，意思是透明、透过。", "候": "hòu 与 gòu 声母不同（h 与 g），声调相同，意思是时候、等候。", "过": "guò 与 gòu 韵母不同（-uo 与 -ou），声调相同，意思是经过。", "勾": "gōu（第一声）与 gòu（第四声）声调不同，意思是勾画、钩子。"}, "sentence_index": null, "correct_answer": "够"}, "level_3": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，表示房子面积恰好供一家人住。"}, {"text": "愿意", "is_correct": false, "explanation": "搭配：“愿意”要求有意愿的人作主语，房子不能愿意让人住。"}, {"text": "允许", "is_correct": false, "explanation": "搭配：“允许”要求有权力的人作主语，房子不能允许人住。"}, {"text": "打算", "is_correct": false, "explanation": "语义：“打算”表示人计划做某事，房子不能计划。"}], "explanations": {"够": "正确答案：“够”，表示房子面积恰好供一家人住。", "愿意": "搭配：“愿意”要求有意愿的人作主语，房子不能愿意让人住。", "允许": "搭配：“允许”要求有权力的人作主语，房子不能允许人住。", "打算": "语义：“打算”表示人计划做某事，房子不能计划。"}, "sentence_index": 6, "correct_answer": "够"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的速度终于够了要求。", "explanation": "这里应该用〈达到〉。“够”表示恰好满足需要，不能直接带“要求”作宾语。"}, {"text": "这件衣服很够我的身材。", "explanation": "这里应该用〈符合〉。“够”表示数量或程度恰好，不能用来说衣服与身材相配。"}, {"text": "他的个子够了他哥哥。", "explanation": "这里应该用〈赶上〉。“够”表示数量正好满足需要，不能用来比较两个人谁高谁矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点钱正好够了买一支笔。", "corrected_sentence": "这点钱正好够买一支笔。", "error_description": "错误形式：“够了买”。正确形式：“够买”。“了”不能插在“够”和“买”之间，此处应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些书够不我看一个月。", "corrected_sentence": "这些书不够我看一个月。", "error_description": "错误形式：“够不我看”。正确形式：“不够我看”。否定词“不”要放在“够”的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
