INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "达到数量或程度的要求。", "primary_collocate": null, "pronunciation": "gòu", "ipa": "koʊ˥˩", "syllable_count": 1, "sentences": [{"text": "这些钱够买一台新电脑。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的分数够上这所大学了。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的人不够，还要再找三个。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的钱够不够用？", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的人数够了，我们开始吧。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜太少了，不够十个人吃。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的年龄不够，不能参加比赛。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶水够你喝一天。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间够了吗？我还没写完。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车上的位子够五个人坐。", "target_word": "够", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夠", "label": "繁体"}, {"form": "够了", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，数量、条件或程度达到所需要的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86362, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，表示数量或程度达到要求。"}, {"text": "狗", "is_correct": false, "explanation": "gǒu（第三声）与 gòu（第四声）声调不同，意思是狗。"}, {"text": "扣", "is_correct": false, "explanation": "kòu 与 gòu 声母不同（k 与 g），声调相同，意思是扣子、扣除。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 gòu 韵母不同（-ui 与 -ou），声调相同，意思是贵重、价格高。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 gòu 韵母不同（-u 与 -ou），声调相同，意思是缘故、事故。"}], "explanations": {"够": "正确答案：“够”，表示数量或程度达到要求。", "狗": "gǒu（第三声）与 gòu（第四声）声调不同，意思是狗。", "扣": "kòu 与 gòu 声母不同（k 与 g），声调相同，意思是扣子、扣除。", "贵": "guì 与 gòu 韵母不同（-ui 与 -ou），声调相同，意思是贵重、价格高。", "故": "gù 与 gòu 韵母不同（-u 与 -ou），声调相同，意思是缘故、事故。"}, "sentence_index": null, "correct_answer": "够"}, "level_3": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，表示钱的数量达到买一台新电脑所需的标准，符合句意。"}, {"text": "愿意", "is_correct": false, "explanation": "搭配：“愿意”要求有意愿的人作主语，“这些钱”不能愿意买电脑。"}, {"text": "敢", "is_correct": false, "explanation": "搭配：“敢”要求有胆量的人作主语，钱没有胆量，句子不通。"}, {"text": "打算", "is_correct": false, "explanation": "语义：“打算”表示人计划做某事，钱不能计划买电脑。"}], "explanations": {"够": "正确答案：“够”，表示钱的数量达到买一台新电脑所需的标准，符合句意。", "愿意": "搭配：“愿意”要求有意愿的人作主语，“这些钱”不能愿意买电脑。", "敢": "搭配：“敢”要求有胆量的人作主语，钱没有胆量，句子不通。", "打算": "语义：“打算”表示人计划做某事，钱不能计划买电脑。"}, "sentence_index": 0, "correct_answer": "够"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次研究够了预期效果。", "explanation": "这里应该用〈达到〉。“够”表示数量或程度足以满足要求，不能直接带“预期效果”这类结果名词作宾语，应说“达到预期效果”。"}, {"text": "这份报告终于够了学校的规定。", "explanation": "这里应该用〈符合〉。“够”表示达到要求，不能用来说事物与规定相符，应说“符合学校的规定”。"}, {"text": "今年的报名人数够了一倍。", "explanation": "这里应该用〈增加〉。“够”表示达到要求，不表示数量增长，应说“增加了一倍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86362, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，表示数量或程度达到要求。"}, {"text": "豆", "is_correct": false, "explanation": "dòu 与 gòu 声母不同（d 与 g），声调相同，意思是豆子。"}, {"text": "透", "is_correct": false, "explanation": "tòu 与 gòu 声母不同（t 与 g），声调相同，意思是透明、透过。"}, {"text": "候", "is_correct": false, "explanation": "hòu 与 gòu 声母不同（h 与 g），声调相同，意思是时候、等候。"}, {"text": "过", "is_correct": false, "explanation": "guò 与 gòu 韵母不同（-uo 与 -ou），声调相同，意思是经过。"}, {"text": "勾", "is_correct": false, "explanation": "gōu（第一声）与 gòu（第四声）声调不同，意思是勾画、钩子。"}], "explanations": {"够": "正确答案：“够”，表示数量或程度达到要求。", "豆": "dòu 与 gòu 声母不同（d 与 g），声调相同，意思是豆子。", "透": "tòu 与 gòu 声母不同（t 与 g），声调相同，意思是透明、透过。", "候": "hòu 与 gòu 声母不同（h 与 g），声调相同，意思是时候、等候。", "过": "guò 与 gòu 韵母不同（-uo 与 -ou），声调相同，意思是经过。", "勾": "gōu（第一声）与 gòu（第四声）声调不同，意思是勾画、钩子。"}, "sentence_index": null, "correct_answer": "够"}, "level_3": {"options": [{"text": "够", "is_correct": true, "explanation": "正确答案：“够”，句中是“不够”，表示年龄没有达到参赛要求。"}, {"text": "减小", "is_correct": false, "explanation": "语义：人的年龄不会减小，“不减小，不能参加比赛”的因果关系不通。"}, {"text": "缩短", "is_correct": false, "explanation": "搭配：“缩短”多用于时间、距离、路程，不用来说人的年龄。"}, {"text": "降低", "is_correct": false, "explanation": "搭配：“降低”多用于水平、标准、价格，不能指人自己的年龄降低。"}], "explanations": {"够": "正确答案：“够”，句中是“不够”，表示年龄没有达到参赛要求。", "减小": "语义：人的年龄不会减小，“不减小，不能参加比赛”的因果关系不通。", "缩短": "搭配：“缩短”多用于时间、距离、路程，不用来说人的年龄。", "降低": "搭配：“降低”多用于水平、标准、价格，不能指人自己的年龄降低。"}, "sentence_index": 6, "correct_answer": "够"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台新电脑够了那台旧的。", "explanation": "这里应该用〈胜过〉。“够”表示达到要求，不能用来比较两件东西的高低。"}, {"text": "这个方案够了大家的需要。", "explanation": "这里应该用〈满足〉。“够”表示达到需要的数量或程度，不能直接带“需要”作宾语。"}, {"text": "这次的成绩够了上次。", "explanation": "这里应该用〈超过〉。“够”不表示超出，也不用来与以前的情况相比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点钱够不买一张车票。", "corrected_sentence": "这点钱不够买一张车票。", "error_description": "错误形式：“够不买”。正确形式：“不够买”。否定词“不”应放在“够”前面，“够不”只用于“够不着”等固定说法，这里说不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些面包够了三个人吃。", "corrected_sentence": "这些面包够三个人吃。", "error_description": "错误形式：“够了三个人吃”。正确形式：“够三个人吃”。“够”后面直接接“数量＋动词”，中间不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
