INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岛是海里一块被水围着的小地方。", "primary_collocate": null, "pronunciation": "dǎo", "ipa": "taʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "海里有一座岛。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "岛上没有路，只能走着去。", "target_word": "岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛离海边不远。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小船慢慢开向那座岛。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一个人住在岛上。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "岛上的夏天不太热。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想去一次那个岛，看看海。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海中的岛上有几只白鸟。", "target_word": "岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，我们没有上岛。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在岛上玩了一下午。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "島", "label": "繁体"}], "register": "中性", "sense_fingerprint": "岛：海里被水围着的一小块陆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛 dǎo」指海里被水围着的一小块陆地。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是抵达。"}, {"text": "刀", "is_correct": false, "explanation": "dāo（第一声）与 dǎo（第三声）声调不同，意思是刀具。"}, {"text": "讨", "is_correct": false, "explanation": "tǎo 与 dǎo 声母不同（t 与 d），意思是索取或讨论。"}], "explanations": {"岛": "正确：「岛 dǎo」指海里被水围着的一小块陆地。", "到": "dào（第四声）与 dǎo（第三声）声调不同，意思是抵达。", "刀": "dāo（第一声）与 dǎo（第三声）声调不同，意思是刀具。", "讨": "tǎo 与 dǎo 声母不同（t 与 d），意思是索取或讨论。"}, "sentence_index": null, "correct_answer": "岛"}, "level_3": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛」指海里被水围着的陆地，与句意相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：「沙漠」是干燥的陆地，海里不会有沙漠，与句意不符。"}, {"text": "森林", "is_correct": false, "explanation": "语义：「森林」是陆地上的树林，海里不会有森林，与句意不符。"}, {"text": "沙滩", "is_correct": false, "explanation": "搭配：「沙滩」是岸边的沙地，前面用「片」而不用「座」，且不在海里。"}], "explanations": {"岛": "正确：「岛」指海里被水围着的陆地，与句意相符。", "沙漠": "语义：「沙漠」是干燥的陆地，海里不会有沙漠，与句意不符。", "森林": "语义：「森林」是陆地上的树林，海里不会有森林，与句意不符。", "沙滩": "搭配：「沙滩」是岸边的沙地，前面用「片」而不用「座」，且不在海里。"}, "sentence_index": 0, "correct_answer": "岛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在湖里划船，看到一棵岛。", "explanation": "这里应该用〈座〉。量词「棵」用于树木，岛要用「座」或「个」。"}, {"text": "这个岛三面是海，只有一面连着陆地。", "explanation": "这里应该用〈半岛〉。「岛」四面都被水环绕，不与陆地相连；只有一面连着陆地的应是半岛。"}, {"text": "草原上有一座岛，岛边有很多牛羊。", "explanation": "这里应该用〈湖〉。「岛」必须被水环绕，草原上的陆地不能叫岛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86365, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛 dǎo」指海里被水围着的一小块陆地。"}, {"text": "道", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是道路。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 dǎo 声母不同（n 与 d），意思是大脑。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng 与 dǎo 韵母不同（ang 与 ao），意思是遮挡。"}], "explanations": {"岛": "正确：「岛 dǎo」指海里被水围着的一小块陆地。", "道": "dào（第四声）与 dǎo（第三声）声调不同，意思是道路。", "脑": "nǎo 与 dǎo 声母不同（n 与 d），意思是大脑。", "挡": "dǎng 与 dǎo 韵母不同（ang 与 ao），意思是遮挡。"}, "sentence_index": null, "correct_answer": "岛"}, "level_3": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛」指海里被水围着的陆地，与“看看海”的地点相符。"}, {"text": "湖", "is_correct": false, "explanation": "语义：「湖」不靠海，与“看看海”的目的不符。"}, {"text": "草原", "is_correct": false, "explanation": "语义：「草原」是陆地上的大片草地，没有海，与“看看海”的目的不符。"}, {"text": "山谷", "is_correct": false, "explanation": "语义：「山谷」在山间，没有海，与“看看海”的目的不符。"}], "explanations": {"岛": "正确：「岛」指海里被水围着的陆地，与“看看海”的地点相符。", "湖": "语义：「湖」不靠海，与“看看海”的目的不符。", "草原": "语义：「草原」是陆地上的大片草地，没有海，与“看看海”的目的不符。", "山谷": "语义：「山谷」在山间，没有海，与“看看海”的目的不符。"}, "sentence_index": 6, "correct_answer": "岛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在沙漠里发现了一座岛。", "explanation": "这里应该用〈绿洲〉。「岛」必须被水环绕，沙漠里没有这样的水域环境。"}, {"text": "我家门口的马路中间有一座岛。", "explanation": "这里应该用〈花坛〉。「岛」必须被水环绕，马路中间没有水，不能叫岛。"}, {"text": "这座岛在大山里，四周都是石头，没有水。", "explanation": "这里应该用〈山〉。「岛」四面都被水环绕，四周没有水的地方不能叫岛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖里有一条岛，岛上有一个小房子。", "corrected_sentence": "湖里有一座岛，岛上有一个小房子。", "error_description": "错误形式：「一条岛」；正确形式：「一座岛」。量词「条」多用于河流、道路等长条形的东西，岛要用「座」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在上岛住了两天。", "corrected_sentence": "我们在岛上住了两天。", "error_description": "错误形式：「在上岛住了两天」；正确形式：「在岛上住了两天」。方位词「上」要放在名词「岛」的后面，不能放在「岛」的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
