INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "江河湖海中被水环绕的陆地。", "primary_collocate": null, "pronunciation": "dǎo", "ipa": "taʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "湖中间有一座岛。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个岛很小，只有几户人家。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们坐船去了那座岛。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "岛上有很多树和鸟。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海里有一个岛，岛上没有人住。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，岛上的风很凉快。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座岛四面都是水。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "船开了一个小时，才到这座岛。", "target_word": "岛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "岛周围的海水特别蓝。", "target_word": "岛", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "去年夏天我在一座岛上住过三天。", "target_word": "岛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "島", "label": "繁体"}], "register": "中性", "sense_fingerprint": "岛：江河湖海中四面被水环绕的陆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd9494de-5348-4735-8c04-847b659ff0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛 dǎo」指江河湖海中被水环绕的陆地。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是抵达。"}, {"text": "刀", "is_correct": false, "explanation": "dāo（第一声）与 dǎo（第三声）声调不同，意思是刀具。"}, {"text": "讨", "is_correct": false, "explanation": "tǎo 与 dǎo 声母不同（t 与 d），意思是索取或讨论。"}, {"text": "挡", "is_correct": false, "explanation": "dǎng 与 dǎo 韵母不同（ang 与 ao），意思是遮挡。"}], "explanations": {"岛": "正确：「岛 dǎo」指江河湖海中被水环绕的陆地。", "到": "dào（第四声）与 dǎo（第三声）声调不同，意思是抵达。", "刀": "dāo（第一声）与 dǎo（第三声）声调不同，意思是刀具。", "讨": "tǎo 与 dǎo 声母不同（t 与 d），意思是索取或讨论。", "挡": "dǎng 与 dǎo 韵母不同（ang 与 ao），意思是遮挡。"}, "sentence_index": null, "correct_answer": "岛"}, "level_3": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛」指被水环绕的陆地，与“湖中间”的位置相符。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：「沙漠」是干燥的陆地，湖中间不会有沙漠，与句意不符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：「大海」远大于湖，不能说成湖中间的一座，与句意不符。"}, {"text": "陆地", "is_correct": false, "explanation": "搭配：「陆地」指大片土地，前面不能用量词「座」。"}], "explanations": {"岛": "正确：「岛」指被水环绕的陆地，与“湖中间”的位置相符。", "沙漠": "语义：「沙漠」是干燥的陆地，湖中间不会有沙漠，与句意不符。", "大海": "语义：「大海」远大于湖，不能说成湖中间的一座，与句意不符。", "陆地": "搭配：「陆地」指大片土地，前面不能用量词「座」。"}, "sentence_index": 0, "correct_answer": "岛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在湖上看到一只岛。", "explanation": "这里应该用〈座〉。量词「只」多用于动物，岛要用「座」或「个」。"}, {"text": "这里是一个岛，三面都是海，一面连着陆地。", "explanation": "这里应该用〈半岛〉。「岛」四面都被水环绕，不与陆地相连；三面环海、一面连着陆地的应是半岛。"}, {"text": "我们在草原上看到一座岛。", "explanation": "这里应该用〈湖〉。「岛」必须被水环绕，草原上没有水域，不能说这里有岛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86366, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛 dǎo」指江河湖海中被水环绕的陆地。"}, {"text": "道", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，意思是道路。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 dǎo 声母不同（n 与 d），意思是大脑。"}, {"text": "党", "is_correct": false, "explanation": "dǎng 与 dǎo 韵母不同（ang 与 ao），意思是政党。"}], "explanations": {"岛": "正确：「岛 dǎo」指江河湖海中被水环绕的陆地。", "道": "dào（第四声）与 dǎo（第三声）声调不同，意思是道路。", "脑": "nǎo 与 dǎo 声母不同（n 与 d），意思是大脑。", "党": "dǎng 与 dǎo 韵母不同（ang 与 ao），意思是政党。"}, "sentence_index": null, "correct_answer": "岛"}, "level_3": {"options": [{"text": "岛", "is_correct": true, "explanation": "正确：「岛」指被水环绕的陆地，与“四面都是水”相符。"}, {"text": "森林", "is_correct": false, "explanation": "语义：「森林」是陆地上的树林，四面并不是水，与句意矛盾。"}, {"text": "草原", "is_correct": false, "explanation": "语义：「草原」是陆地上的大片草地，四面并不是水，与句意矛盾。"}, {"text": "地方", "is_correct": false, "explanation": "搭配：「地方」前一般用量词「个」或「片」，不用「座」。"}], "explanations": {"岛": "正确：「岛」指被水环绕的陆地，与“四面都是水”相符。", "森林": "语义：「森林」是陆地上的树林，四面并不是水，与句意矛盾。", "草原": "语义：「草原」是陆地上的大片草地，四面并不是水，与句意矛盾。", "地方": "搭配：「地方」前一般用量词「个」或「片」，不用「座」。"}, "sentence_index": 6, "correct_answer": "岛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在沙漠里发现了一座岛。", "explanation": "这里应该用〈绿洲〉。「岛」必须被水环绕，沙漠里没有这样的水域环境。"}, {"text": "公园的草地中间有一座岛，孩子们在上面跑。", "explanation": "这里应该用〈小山坡〉。「岛」必须被水环绕，草地中间没有水，不能叫岛。"}, {"text": "那座岛在沙漠中间，四周都是沙子。", "explanation": "这里应该用〈沙丘〉。「岛」四面都被水环绕，四周都是沙子的地方不能叫岛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖中有一只岛，岛上长着几棵树。", "corrected_sentence": "湖中有一座岛，岛上长着几棵树。", "error_description": "错误形式：「一只岛」；正确形式：「一座岛」。「只」用于动物，岛要用量词「座」（或「个」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我父亲在上岛工作了五年。", "corrected_sentence": "我父亲在岛上工作了五年。", "error_description": "错误形式：「在上岛工作」；正确形式：「在岛上工作」。方位词「上」要放在名词「岛」的后面，不能放在「岛」的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19320473-f702-4af6-a5de-25b04a85d8a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86367, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以下", "is_correct": true, "explanation": "“以下”与“以上”构成反义，指在某个标准之下或之后。"}, {"text": "中间", "is_correct": false, "explanation": "“中间”指两端之间，与“以上”没有反义关系。"}, {"text": "旁边", "is_correct": false, "explanation": "“旁边”指紧挨着的位置，与“以上”没有反义关系。"}, {"text": "外面", "is_correct": false, "explanation": "“外面”指某一范围的外侧，与“以上”没有反义关系。"}], "correct_answer": "以下", "explanations": {"以下": "“以下”与“以上”构成反义，指在某个标准之下或之后。", "中间": "“中间”指两端之间，与“以上”没有反义关系。", "旁边": "“旁边”指紧挨着的位置，与“以上”没有反义关系。", "外面": "“外面”指某一范围的外侧，与“以上”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86367, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以下", "is_correct": true, "explanation": "“以下”与“以上”构成反义，指在某个标准之下或之后。"}, {"text": "中心", "is_correct": false, "explanation": "“中心”指中间的位置，与“以上”没有反义关系。"}, {"text": "附近", "is_correct": false, "explanation": "“附近”指靠近某处，与“以上”没有反义关系。"}, {"text": "后方", "is_correct": false, "explanation": "“后方”指后面的方向，与“以上”没有反义关系。"}], "correct_answer": "以下", "explanations": {"以下": "“以下”与“以上”构成反义，指在某个标准之下或之后。", "中心": "“中心”指中间的位置，与“以上”没有反义关系。", "附近": "“附近”指靠近某处，与“以上”没有反义关系。", "后方": "“后方”指后面的方向，与“以上”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86367, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“以上”是说在这个位置或数目的上面。", "primary_collocate": null, "pronunciation": "yǐ shàng", "ipa": "i˨˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "一米二以上的孩子可以玩这个。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的考试成绩在九十分以上。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六十岁以上的老人坐车不用买票。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海拔两千米以上的地方很冷。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面以上的部分只有一小块。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店一百元以上就送礼物。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡八个小时以上。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上两米以上的地方要用梯子。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十个以上的人来了，就可以开会。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池水深一米五以上，小孩不能下去。", "target_word": "以上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在某个位置或数目的上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 六十 (Zipf 3.85), 坐车 (Zipf 3.44), 买票 (Zipf 3.6)','sentence 9 above tier T1: 3 words above tier T1 (max 2): 游泳池 (Zipf 3.9), 水深 (Zipf 3.73), 一米 (Zipf 3.31)']::text[], 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86367, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以上", "is_correct": true, "explanation": "正确：“以上”表示数量或位置在某标准之上，与“一米二”相符。"}, {"text": "中央", "is_correct": false, "explanation": "语义：“中央”是位置，不能表示身高高于“一米二”。"}, {"text": "里面", "is_correct": false, "explanation": "语义：“里面”指内部，不能表示身高在一米二之上。"}, {"text": "对面", "is_correct": false, "explanation": "搭配：“对面”不能修饰身高数量“一米二”。"}], "explanations": {"以上": "正确：“以上”表示数量或位置在某标准之上，与“一米二”相符。", "中央": "语义：“中央”是位置，不能表示身高高于“一米二”。", "里面": "语义：“里面”指内部，不能表示身高在一米二之上。", "对面": "搭配：“对面”不能修饰身高数量“一米二”。"}, "sentence_index": 0, "correct_answer": "以上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "五岁以上的小孩太小，不能自己坐车。", "explanation": "这里应该用〈以下〉。说孩子太小，应指数目在五岁下面，“以上”表示在上面。"}, {"text": "这个班级以上的同学不能参加。", "explanation": "这里应该用〈以外〉。“以上”表示在某个标准之上，不表示在范围之外。"}, {"text": "这件衣服以上的款式都卖完了。", "explanation": "这里应该用〈以外〉。“以上”表示位置或数目的上面，不表示“这件衣服之外的款式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以上", "is_correct": true, "explanation": "正确：“以上”表示时长超过八个小时，与句意相符。"}, {"text": "左边", "is_correct": false, "explanation": "语义：“左边”是方位，不能表示睡眠的时长。"}, {"text": "北边", "is_correct": false, "explanation": "搭配：“北边”是方位名词，不能用来修饰“八个小时”。"}, {"text": "东边", "is_correct": false, "explanation": "语义：“东边”不能表示时间的长度。"}], "explanations": {"以上": "正确：“以上”表示时长超过八个小时，与句意相符。", "左边": "语义：“左边”是方位，不能表示睡眠的时长。", "北边": "搭配：“北边”是方位名词，不能用来修饰“八个小时”。", "东边": "语义：“东边”不能表示时间的长度。"}, "sentence_index": 6, "correct_answer": "以上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动以上的人都回家了。", "explanation": "这里应该用〈以外〉。“以上”表示超过某个标准，不表示“这次活动之外的人”。"}, {"text": "这个班以上的同学都没来。", "explanation": "这里应该用〈以外〉。“以上”表示在某个标准之上，不表示“这个班之外的同学”。"}, {"text": "水深一米以上，很浅，小孩可以下去。", "explanation": "这里应该用〈以下〉。水很浅说明深度在一米下面，“以上”表示超过一米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一米五以上人可以坐这个。", "corrected_sentence": "一米五以上的人可以坐这个。", "error_description": "错误：“以上”修饰名词“人”时要加结构助词“的”，应写成“一米五以上的人”，不能省去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两米以上得地方要注意安全。", "corrected_sentence": "两米以上的地方要注意安全。", "error_description": "错误：“以上”修饰名词“地方”时应用结构助词“的”，这里误写成“得”。“得”不能放在修饰语和中心语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
