INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86371, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“以来”是说从过去的一个时间到现在这一段时间。", "primary_collocate": null, "pronunciation": "yǐ lái", "ipa": "i˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "今年以来，天气一直很好。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从上班以来，我每天都很忙。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到这里以来，我认识了很多朋友。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开学以来，他一次也没迟到。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一年以来，她的汉语进步很大。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天以来，这里只下了两场雨。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个月以来，我每天都跑步。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从毕业以来，我们没见过面。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入冬以来，天气越来越冷。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这周以来，公司的客人特别多。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从过去某个时间点到现在这段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86371, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以来", "is_correct": true, "explanation": "以来：指从过去某个时间到现在的这段时间。"}, {"text": "一来", "is_correct": false, "explanation": "yī lái（第一声）与 yǐ lái（第三声）声调不同，意思是“一方面”，常用于“一来……二来……”。"}, {"text": "移来", "is_correct": false, "explanation": "yí lái（第二声）与 yǐ lái（第三声）声调不同，意思是“搬来”。"}, {"text": "依赖", "is_correct": false, "explanation": "yī lài（第一声）与 yǐ lái 声调不同，意思是“靠别人或别的东西”。"}], "explanations": {"以来": "以来：指从过去某个时间到现在的这段时间。", "一来": "yī lái（第一声）与 yǐ lái（第三声）声调不同，意思是“一方面”，常用于“一来……二来……”。", "移来": "yí lái（第二声）与 yǐ lái（第三声）声调不同，意思是“搬来”。", "依赖": "yī lài（第一声）与 yǐ lái 声调不同，意思是“靠别人或别的东西”。"}, "sentence_index": null, "correct_answer": "以来"}, "level_3": {"options": [{"text": "以来", "is_correct": true, "explanation": "以来：指从过去到现在的一段时间，与“今年”搭配，符合句意。"}, {"text": "以北", "is_correct": false, "explanation": "语义：“以北”表示方位，不能表示时间段，句意不通。"}, {"text": "以上", "is_correct": false, "explanation": "语义：“以上”表示范围，不能与“今年”组成时间段，句意不通。"}, {"text": "以下", "is_correct": false, "explanation": "搭配：“今年以下”没有表示到现在的时间段的意思，不能与“天气一直很好”搭配。"}], "explanations": {"以来": "以来：指从过去到现在的一段时间，与“今年”搭配，符合句意。", "以北": "语义：“以北”表示方位，不能表示时间段，句意不通。", "以上": "语义：“以上”表示范围，不能与“今年”组成时间段，句意不通。", "以下": "搭配：“今年以下”没有表示到现在的时间段的意思，不能与“天气一直很好”搭配。"}, "sentence_index": 0, "correct_answer": "以来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃完饭以来，我们去散步。", "explanation": "这里应该用〈以后〉。“以来”指从过去某时到现在的一段时间，不能表示吃完饭之后发生的一次性动作。"}, {"text": "三天以来，我会回来。", "explanation": "这里应该用〈以内〉。“以来”不能表示将来的时间范围，“三天以内”才指将来的期限。"}, {"text": "从北京以来，他一直很忙。", "explanation": "这里不该用“以来”。“以来”前面要接时间，不能接地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以来", "is_correct": true, "explanation": "以来：表示从过去某时到现在的时间段，与“三个月”搭配，符合句意。"}, {"text": "以东", "is_correct": false, "explanation": "语义：“以东”表示方位，不能表示时间段，句意不通。"}, {"text": "以外", "is_correct": false, "explanation": "语义：“以外”表示范围之外，与“三个月”组合后句意不通。"}, {"text": "之下", "is_correct": false, "explanation": "搭配：“三个月之下”不能与“我每天都跑步”形成正常的时间关系。"}], "explanations": {"以来": "以来：表示从过去某时到现在的时间段，与“三个月”搭配，符合句意。", "以东": "语义：“以东”表示方位，不能表示时间段，句意不通。", "以外": "语义：“以外”表示范围之外，与“三个月”组合后句意不通。", "之下": "搭配：“三个月之下”不能与“我每天都跑步”形成正常的时间关系。"}, "sentence_index": 6, "correct_answer": "以来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下周以来，公司的客人会特别多。", "explanation": "这里应该用〈以后〉。“以来”指从过去到现在，不能用于将来。"}, {"text": "两个人以来，公司的客人特别多。", "explanation": "这里不该用“以来”。“以来”接的是一段时间，不能接“两个人”这样的人数。"}, {"text": "我以来，公司的客人特别多。", "explanation": "这里不该用“以来”。“以来”接的是一段时间，不能接“我”这样的人称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年以以来，我一直在学习汉语。", "corrected_sentence": "去年以来，我一直在学习汉语。", "error_description": "错误在于多出的“以”。“以来”是一个词，不能重复或拆开，应说“去年以来”，不说“去年以以来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年的以来，公司变化很大。", "corrected_sentence": "这几年以来，公司变化很大。", "error_description": "“以来”前面不能加“的”。应说“这几年以来”，不说“这几年的以来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
