INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指从过去某一时间起到现在的这段时间。", "primary_collocate": null, "pronunciation": "yǐ lái", "ipa": "i˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "长期以来，他一直住在小城里。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自古以来，人们都喜欢月亮。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年以来，我们总在这家店吃饭。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直以来，谢谢你照顾我。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半年以来，这家店的生意很好。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年以来，这里变化很大。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近两年以来，我没有生过病。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自从认识你以来，我就很开心。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年以来，他每天早起。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长久以来，大家都叫他老王。", "target_word": "以来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从过去某一时间起到现在的这段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
