INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以来", "is_correct": true, "explanation": "以来：表示从过去到现在的一段时间，与“近两年”搭配，符合句意。"}, {"text": "以下", "is_correct": false, "explanation": "搭配：“近两年以下”不能表示到现在的时间段，句意不通。"}, {"text": "以东", "is_correct": false, "explanation": "语义：“以东”指方位，不能表示时间。"}, {"text": "之下", "is_correct": false, "explanation": "语义：“之下”表示范围，不能与“近两年”形成时间段，句意不通。"}], "explanations": {"以来": "以来：表示从过去到现在的一段时间，与“近两年”搭配，符合句意。", "以下": "搭配：“近两年以下”不能表示到现在的时间段，句意不通。", "以东": "语义：“以东”指方位，不能表示时间。", "之下": "语义：“之下”表示范围，不能与“近两年”形成时间段，句意不通。"}, "sentence_index": 6, "correct_answer": "以来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他以来，大家都叫他老王。", "explanation": "这里不该用“以来”。“以来”接的是一段时间，不能接“他”这样的人称。"}, {"text": "学校以来，大家都叫他老王。", "explanation": "这里不该用“以来”。“以来”接的是一段时间，不能接“学校”这样的地点。"}, {"text": "下个月以来，大家都叫他老王。", "explanation": "这里应该用〈以后〉。“以来”指从过去到现在，不能用于将来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长久的以来，我们都很想念他。", "corrected_sentence": "长久以来，我们都很想念他。", "error_description": "“以来”前面不能加“的”。应说“长久以来”，不说“长久的以来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
