INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86373, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年龄是一个人活了多少年。", "primary_collocate": null, "pronunciation": "nián líng", "ipa": "njɛn˧˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他的年龄是二十五岁。", "target_word": "年龄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈很年轻，看不出她的真实年龄。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和哥哥的年龄差五岁。", "target_word": "年龄", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "报名参加比赛的人，年龄要在十八岁以上。", "target_word": "年龄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司对员工的年龄有要求，最好不超过三十五岁。", "target_word": "年龄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一个二十岁，一个五十岁，年龄差很大。", "target_word": "年龄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着年龄变大，爷爷的记忆力越来越差。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子到了上学的年龄，就要去学校了。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国法律规定的结婚年龄，男女不一样。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，这种病和年龄有关，老人更容易得。", "target_word": "年龄", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "年龄段", "label": "复合"}, {"form": "年龄层", "label": "复合"}, {"form": "年齡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "年龄：人活了多少年，人的岁数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eb6a069-3cc9-4bff-bb63-1f24166f25c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86373, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": true, "explanation": "年龄指人活了多少年，与“二十五岁”搭配，句意正确。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高不用“岁”计量，应说“厘米”，不能说“身高是二十五岁”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重表示重量，不表示活了多少年，句意不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是数量，不能用“二十五岁”来说明。"}], "explanations": {"年龄": "年龄指人活了多少年，与“二十五岁”搭配，句意正确。", "身高": "搭配：身高不用“岁”计量，应说“厘米”，不能说“身高是二十五岁”。", "体重": "语义：体重表示重量，不表示活了多少年，句意不通。", "名字": "语义：名字不是数量，不能用“二十五岁”来说明。"}, "sentence_index": 0, "correct_answer": "年龄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这家公司的年龄有十年了。", "explanation": "这里应该用〈工龄〉。年龄指人从出生到现在活了多少年，在一家公司工作了多少年要用工龄。"}, {"text": "这份合同的年龄是三年。", "explanation": "这里应该用〈年限〉。合同的有效期限要用年限，年龄只用于说人的岁数。"}, {"text": "他的年龄是1990年。", "explanation": "这句把年龄理解成了出生的年份。年龄表示活了多少年，不是哪一年出生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86373, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": true, "explanation": "年龄表示岁数，随着岁数增长而“变大”，与爷爷变老的语境相符。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不会随着人变老而变大，与爷爷的语境矛盾。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印不会随着人变老而变大，句意不通。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“变大”不能用来修饰性格，性格通常说“变化”。"}], "explanations": {"年龄": "年龄表示岁数，随着岁数增长而“变大”，与爷爷变老的语境相符。", "房间": "语义：房间不会随着人变老而变大，与爷爷的语境矛盾。", "脚印": "语义：脚印不会随着人变老而变大，句意不通。", "性格": "搭配：“变大”不能用来修饰性格，性格通常说“变化”。"}, "sentence_index": 6, "correct_answer": "年龄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场考试的年龄是九十分钟。", "explanation": "这里应该用〈时长〉。考试持续的时间要用时长，年龄只用于人。"}, {"text": "这部电影的年龄是两个小时。", "explanation": "这里应该用〈片长〉。影片播放的时间要用片长，年龄只用于人。"}, {"text": "这张桌子的年龄有一米。", "explanation": "这里应该用〈高度〉。年龄指人活了多少年，桌子有多高要用〈高度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86373, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的年龄是三十个。", "corrected_sentence": "他的年龄是三十岁。", "error_description": "量词错误：说年龄要用“岁”，不能用“个”。正确说法是“他的年龄是三十岁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86373, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和妹妹的年龄差三个。", "corrected_sentence": "我和妹妹的年龄差三岁。", "error_description": "量词错误：说年龄差要用“岁”，不能用“个”。正确说法是“我和妹妹的年龄差三岁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f0c2dc0-701e-4d12-98e2-361ee568df0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
