INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86375, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图片是画出来或拍出来的画面。", "primary_collocate": null, "pronunciation": "tú piàn", "ipa": "tʰu˧˥ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "墙上挂着一张旧图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片是我在海边拍的。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图片上有一只白色的小猫。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机拍了几张图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把一张可爱的图片发给了妈妈。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图片里的山很高，水很蓝。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片的颜色非常好看。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看图片，说说你看到了什么。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图片中的人正在笑着。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这张图片印出来。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "圖片", "label": "繁体"}], "register": "中性", "sense_fingerprint": "图片：画出来或拍出来的画面，可描述其中的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0962041-b86f-4f5b-b465-232c20626925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图片", "is_correct": true, "explanation": "正确：墙上挂着的平面画面称图片，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能挂在墙上。"}, {"text": "床", "is_correct": false, "explanation": "搭配：“挂”通常搭配画、衣服等，床不能挂在墙上。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不会被挂在墙上，句意不通。"}], "explanations": {"图片": "正确：墙上挂着的平面画面称图片，符合句意。", "桌子": "语义：桌子是家具，不能挂在墙上。", "床": "搭配：“挂”通常搭配画、衣服等，床不能挂在墙上。", "课本": "语义：课本是书，不会被挂在墙上，句意不通。"}, "sentence_index": 0, "correct_answer": "图片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她买了一条图片。", "explanation": "这里应该用〈张〉。图片是平面的，量词应用〈张〉；〈条〉用于长条形的东西，不能用于图片。"}, {"text": "这篇图片是她的作品。", "explanation": "这里应该用〈张〉。〈篇〉用于文章，图片的量词是〈张〉。"}, {"text": "她用耳机听了几张图片。", "explanation": "这里应该用〈唱片〉。〈听〉搭配唱片、录音等声音，图片是看的，不能听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图片", "is_correct": true, "explanation": "正确：图片是画面，可以说“颜色非常好看”，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有可以被称为“好看”的颜色，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“颜色非常好看”不搭配“味道”，味道应说“好”或“香”。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是声响，没有可以“好看”的颜色，句意不通。"}], "explanations": {"图片": "正确：图片是画面，可以说“颜色非常好看”，符合句意。", "声音": "语义：声音没有可以被称为“好看”的颜色，句意不通。", "味道": "搭配：“颜色非常好看”不搭配“味道”，味道应说“好”或“香”。", "噪音": "语义：噪音是声响，没有可以“好看”的颜色，句意不通。"}, "sentence_index": 6, "correct_answer": "图片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想把这首图片印出来。", "explanation": "这里应该用〈张〉。〈首〉用于歌曲、诗词，图片的量词是〈张〉。"}, {"text": "我想把这张图片听一听。", "explanation": "这里应该用〈录音〉。图片是看的，不能听；能听的是录音。"}, {"text": "我想把这张图片吃掉。", "explanation": "这里应该用〈饼〉。图片是画面，不能吃；“一张饼”才能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在桌上放着一只旧图片。", "corrected_sentence": "我在桌上放着一张旧图片。", "error_description": "错误：量词“只”。“图片”是平面的，量词应用“张”；“只”用于动物等。正确说法是“一张旧图片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一张彩色图片们。", "corrected_sentence": "我买了一张彩色图片。", "error_description": "错误：数量短语“一张彩色图片”后多加了复数标记“们”。数量短语修饰的名词不能再加“们”，去掉“们”即为正确说法“一张彩色图片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
