INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指画、照片等平面的图像。", "primary_collocate": null, "pronunciation": "tú piàn", "ipa": "tʰu˧˥ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "书里有很多漂亮的图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张图片发给我。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上找了一张图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图片是谁画的？", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机里有很多图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一些图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片太小，看不清楚。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢看有图片的书。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一张大图片。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把图片放在文章里。", "target_word": "图片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "圖片", "label": "繁体"}], "register": "中性", "sense_fingerprint": "图片：画、照片等平面的图像，可发送、查找、放进文章", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0962041-b86f-4f5b-b465-232c20626925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图片", "is_correct": true, "explanation": "正确：图片是平面图像，可以用“漂亮的”修饰，符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“漂亮”形容可看的对象，声音不能用“漂亮”形容。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“漂亮的”不搭配“味道”，味道应说“好”或“香”。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是刺耳的声响，不能用“漂亮”修饰，书里也不会有。"}], "explanations": {"图片": "正确：图片是平面图像，可以用“漂亮的”修饰，符合句意。", "声音": "语义：“漂亮”形容可看的对象，声音不能用“漂亮”形容。", "味道": "搭配：“漂亮的”不搭配“味道”，味道应说“好”或“香”。", "噪音": "语义：噪音是刺耳的声响，不能用“漂亮”修饰，书里也不会有。"}, "sentence_index": 0, "correct_answer": "图片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在墙上挂了一根图片。", "explanation": "这里应该用〈张〉。图片是平面的，量词应用〈张〉；〈根〉用于细长的东西，不能用于图片。"}, {"text": "这篇图片的作者是李老师。", "explanation": "这里应该用〈张〉。〈篇〉用于文章，图片的量词是〈张〉。"}, {"text": "我买了一只图片。", "explanation": "这里应该用〈张〉。图片是平面的，量词应用〈张〉；〈只〉用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图片", "is_correct": true, "explanation": "正确：图片可以被看，也可以用“太小”描述，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是实物，说它太小而“看不清楚”不合逻辑。"}, {"text": "床", "is_correct": false, "explanation": "搭配：“看不清楚”通常说文字或画面，“床”不是可被看清的对象。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：说地毯太小而“看不清楚”不合常理，句意不通。"}], "explanations": {"图片": "正确：图片可以被看，也可以用“太小”描述，符合句意。", "桌子": "语义：桌子是实物，说它太小而“看不清楚”不合逻辑。", "床": "搭配：“看不清楚”通常说文字或画面，“床”不是可被看清的对象。", "地毯": "语义：说地毯太小而“看不清楚”不合常理，句意不通。"}, "sentence_index": 6, "correct_answer": "图片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我听了一张图片。", "explanation": "这里应该用〈唱片〉。〈听〉搭配唱片、录音等声音，图片是看的，不能听。"}, {"text": "这首图片很好看。", "explanation": "这里应该用〈张〉。〈首〉用于歌曲、诗词，图片的量词是〈张〉。"}, {"text": "我吃了一张图片。", "explanation": "这里应该用〈饼〉。图片是看的，不能吃；“一张饼”才能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把那只图片保存下来了。", "corrected_sentence": "我已经把那张图片保存下来了。", "error_description": "错误：量词“只”。“图片”是平面的，量词应用“张”；“只”用于动物等，不能用于图片。正确说法是“那张图片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他发来一张大图片们。", "corrected_sentence": "他发来一张大图片。", "error_description": "错误：数量短语“一张大图片”后多加了复数标记“们”。数量短语修饰的名词不能再加“们”，去掉“们”即为正确说法“一张大图片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
