INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“年代”是说很长一段时间，比如过去的某一段日子。", "primary_collocate": null, "pronunciation": "nián dài", "ipa": "njɛn˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "在那个年代，很多人家里没有电视。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说起他年轻时那个年代的事。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个年代的孩子都喜欢在外面玩。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个年代的人，生活方便多了。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在一个很穷的年代。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是一个人们靠写信联系的年代。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在父母的年代，坐火车要很长时间。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个年代，手机已经是生活的一部分。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争的年代里，人们过得很苦。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶讲了很多她那个年代的故事。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那个年代", "label": "复合"}], "register": "中性", "sense_fingerprint": "年代：过去的一段较长时间，指某个时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正确：“年代”指一段较长的时期，与“在那个年代”的时间语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色调，不指一段时期，“在那个颜色”无法作时间状语。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”指人的性情，不能与“在那个……，很多人家里没有电视”构成时间框架。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的外形特征，说的是人的高矮，与时期无关。"}], "explanations": {"年代": "正确：“年代”指一段较长的时期，与“在那个年代”的时间语境相符。", "颜色": "语义：“颜色”指事物的色调，不指一段时期，“在那个颜色”无法作时间状语。", "性格": "搭配：“性格”指人的性情，不能与“在那个……，很多人家里没有电视”构成时间框架。", "身高": "体貌：“身高”指人的外形特征，说的是人的高矮，与时期无关。"}, "sentence_index": 0, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开学的年代是九月一号。", "explanation": "这里应该用〈日期〉。“日期”指具体的某一天，年代指较长的历史时期，不能用来说开学的具体日子。"}, {"text": "一个年代有二十周。", "explanation": "这里应该用〈学期〉。“学期”指学校一段有固定周数的教学时间；年代指较长的历史时期，不能用来计算教学的周数。"}, {"text": "他的年代不小了。", "explanation": "这里应该用〈年龄〉。年代指一段时期，不用来说人的岁数；“他的年龄不小了”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正确：“年代”指较长的一段时期，“在父母的年代”指父母生活的那段时期，语义通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气的状况，不指时期，“在父母的天气”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是人的身体特征，不能作时间框架的修饰语。"}, {"text": "芳龄", "is_correct": false, "explanation": "语域：“芳龄”是敬辞，专指年轻女子的年龄，不能用于父母，与口语叙述不合。"}], "explanations": {"年代": "正确：“年代”指较长的一段时期，“在父母的年代”指父母生活的那段时期，语义通顺。", "天气": "语义：“天气”指大气的状况，不指时期，“在父母的天气”不成立。", "体重": "体貌：“体重”是人的身体特征，不能作时间框架的修饰语。", "芳龄": "语域：“芳龄”是敬辞，专指年轻女子的年龄，不能用于父母，与口语叙述不合。"}, "sentence_index": 6, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家族年代都是农民。", "explanation": "这里应该用〈世代〉。“世代”指一代代的人，年代指一段时期，不用来说家族的世代。"}, {"text": "电影的年代是两个小时。", "explanation": "这里应该用〈时长〉。“时长”指作品持续的时间，电影的时长以小时计；年代指较长的历史时期，不能用来计算作品的时长。"}, {"text": "我在那里住了一段年代。", "explanation": "这里应该用〈时间〉。“住了一段时间”指停留的时长；年代指较长的历史时期，不能用来说停留的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那是一个大家都骑自行车上班年代。", "corrected_sentence": "那是一个大家都骑自行车上班的年代。", "error_description": "错误：修饰“年代”的小句“大家都骑自行车上班”后面漏掉了“的”。应说“大家都骑自行车上班的年代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们经历了两年代的变化。", "corrected_sentence": "我们经历了两个年代的变化。", "error_description": "错误：数词“两”与“年代”之间漏了量词“个”。应说“两个年代”，不能说“两年代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
