INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86378, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指每十年的一段时间，如“八十年代”。", "primary_collocate": null, "pronunciation": "nián dài", "ipa": "njɛn˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "八十年代，很多家庭买了电视。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是九十年代最流行的。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生在七十年代。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十世纪三十年代，这座城市很繁华。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸六十年代在农村长大。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九十年代的电影我最喜欢。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店是五十年代开业的。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八十年代以后，这里变化很大。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是七十年代的大学生。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书写的是八十年代的生活。", "target_word": "年代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "八十年代", "label": "复合"}], "register": "中性", "sense_fingerprint": "年代：每十年的一段时间，如八十年代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正确：“年代”指某个十年，“八十年代”说的是八十年代这十年，语义通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色调，不指十年的时段，“八十颜色”不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的外形特征，不能用数字加名词表示一个时段。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”指人的性情，不能与“八十”构成表示时段的时间词。"}], "explanations": {"年代": "正确：“年代”指某个十年，“八十年代”说的是八十年代这十年，语义通顺。", "颜色": "语义：“颜色”指事物的色调，不指十年的时段，“八十颜色”不成立。", "身高": "体貌：“身高”指人的外形特征，不能用数字加名词表示一个时段。", "性格": "搭配：“性格”指人的性情，不能与“八十”构成表示时段的时间词。"}, "sentence_index": 0, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这个工厂干了十年代。", "explanation": "这里应该用〈时长〉。“干了十年”说的是持续的时长；年代指某个十年（如八十年代）或一段历史时期，不能用来计算工作的时长。"}, {"text": "这次会议的年代是十月一号。", "explanation": "这里应该用〈日期〉。“日期”指具体的某一天，年代指某个十年或一段历史时期，不能用来说会议的具体日子。"}, {"text": "这个年代很凉快。", "explanation": "这里应该用〈季节〉。“季节”指一年中的某一段时期，可以说冷热；年代指某个十年或一段历史时期，不能用来说天气的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年代", "is_correct": true, "explanation": "正确：“五十年代”指五十年代这一个十年，“开业”的时间语境与之相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气状况，不指十年的时段，“五十天气”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是人或物的重量特征，不能与“五十”构成时段。"}, {"text": "风格", "is_correct": false, "explanation": "搭配：“风格”指作风，不能用数字修饰表示时段，“五十风格”搭配不当。"}], "explanations": {"年代": "正确：“五十年代”指五十年代这一个十年，“开业”的时间语境与之相符。", "天气": "语义：“天气”指大气状况，不指十年的时段，“五十天气”不成立。", "体重": "体貌：“体重”是人或物的重量特征，不能与“五十”构成时段。", "风格": "搭配：“风格”指作风，不能用数字修饰表示时段，“五十风格”搭配不当。"}, "sentence_index": 6, "correct_answer": "年代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的年代比我大五岁。", "explanation": "这里应该用〈年龄〉。年代指某个十年，不能用来比较人的岁数。"}, {"text": "他在这家公司工作了一段年代。", "explanation": "这里应该用〈时间〉。“工作了一段时间”指任意时长；年代特指某个十年，不能表示工作的时长。"}, {"text": "他的年代有八十公斤。", "explanation": "这里应该用〈体重〉。“体重”指人的重量，可以说“有八十公斤”；年代指某个十年或一段历史时期，不能用来说人的重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影讲了三条年代的故事。", "corrected_sentence": "这部电影讲了三个年代的故事。", "error_description": "错误：量词用错了。“年代”的量词是“个”，不能用“条”。应说“三个年代”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书讲了两年代的事。", "corrected_sentence": "这本书讲了两个年代的事。", "error_description": "错误：数词“两”与“年代”之间漏了量词“个”。应说“两个年代”，不能说“两年代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
