INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86379, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "应当是说这样做才对。", "primary_collocate": null, "pronunciation": "yīng dāng", "ipa": "iŋ˥ taŋ˥", "syllable_count": 2, "sentences": [{"text": "做错了事，应当向别人道歉。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对朋友应当诚实，不应当说谎。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学生应当尊敬老人。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西应当先看价格再决定。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应当用自己的钱买礼物。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司应当给员工好的工作环境。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在图书馆里应当小声说话。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题应当马上告诉医生。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的人应当遵守交通规则。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭以前应当先洗手。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "情态动词，表示从道德、规则上看这样做才对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86379, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应当", "is_correct": true, "explanation": "正确：“应当”表示从道德上看这样做才对，符合句意。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量，这句说的是做错事后应该道歉，不涉及敢不敢。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，不能直接放在“向别人道歉”前面。"}, {"text": "可能", "is_correct": false, "explanation": "语义：“可能”表示推测，这句讲的是从道德上该怎么做，不是推测。"}], "explanations": {"应当": "正确：“应当”表示从道德上看这样做才对，符合句意。", "敢": "语义：“敢”表示有胆量，这句说的是做错事后应该道歉，不涉及敢不敢。", "把": "语法：“把”是介词，不能直接放在“向别人道歉”前面。", "可能": "语义：“可能”表示推测，这句讲的是从道德上该怎么做，不是推测。"}, "sentence_index": 0, "correct_answer": "应当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地球应当绕着太阳转。", "explanation": "这里不宜用〈应当〉。“应当”表示说这样做才对，用于人的行为；陈述自然规律时直接说“地球绕着太阳转”。"}, {"text": "水应当往低处流。", "explanation": "这里不宜用〈应当〉。“应当”表示说这样做才对，不用来陈述水往低处流这类自然规律，应直接说“水往低处流”。"}, {"text": "一年应当有十二个月。", "explanation": "这里不宜用〈应当〉。“应当”表示这样做才对，用于人的行为；陈述既定事实时应直接说“一年有十二个月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应当", "is_correct": true, "explanation": "正确：“应当”表示规则上应该这样做，符合句意。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表示被动，不能直接放在“小声说话”前面。"}, {"text": "肯", "is_correct": false, "explanation": "语义：“肯”表示愿意，这句说的是规则上该不该这样做，不是愿不愿意。"}, {"text": "想", "is_correct": false, "explanation": "语义：“想”表示希望，这句讲的是规则上应当如何，不是想不想。"}], "explanations": {"应当": "正确：“应当”表示规则上应该这样做，符合句意。", "被": "语法：“被”表示被动，不能直接放在“小声说话”前面。", "肯": "语义：“肯”表示愿意，这句说的是规则上该不该这样做，不是愿不愿意。", "想": "语义：“想”表示希望，这句讲的是规则上应当如何，不是想不想。"}, "sentence_index": 6, "correct_answer": "应当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮应当绕着地球转。", "explanation": "这里不宜用〈应当〉。“应当”表示说这样做才对，不用来陈述天体运行的规律，应直接说“月亮绕着地球转”。"}, {"text": "河水应当向北流。", "explanation": "这里不宜用〈应当〉。“应当”表示说这样做才对，河水的流向是既定事实，应直接说“这条河向北流”。"}, {"text": "一个星期应当有七天。", "explanation": "这里不宜用〈应当〉。“应当”表示这样做才对，不用来说明既定事实，应直接说“一个星期有七天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机很应当注意安全。", "corrected_sentence": "司机应当注意安全。", "error_description": "“很”不能修饰情态动词“应当”。应改为：“司机应当注意安全。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应当了遵守规则。", "corrected_sentence": "我们应当遵守规则。", "error_description": "“了”不能放在情态动词“应当”后面、动词前面。错误写法是“应当了遵守”，正确写法是“应当遵守”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
