INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86380, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "应该；理应。", "primary_collocate": null, "pronunciation": "yīng dāng", "ipa": "iŋ˥ taŋ˥", "syllable_count": 2, "sentences": [{"text": "学生应当按时完成作业。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应当爱护公共环境。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你生病了，应当好好休息。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子应当多吃蔬菜和水果。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老人上车，年轻人应当让座。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借了别人的东西，应当按时还。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮过我很多次，我应当谢谢他。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家应当关掉手机。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你应当先问问爸爸。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时，行人应当看红绿灯。", "target_word": "应当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "情态动词，表示按道理或情理理应如此，后接动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应当", "is_correct": true, "explanation": "正确：“应当”表示按道理理应如此，符合句意。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量去做，这句只是说学生理应按时完成作业，没有敢不敢的意思。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，不能直接放在“按时完成作业”前面。"}, {"text": "可能", "is_correct": false, "explanation": "语义：“可能”表示推测，这句说的是理应如此，而不是推测会怎样。"}], "explanations": {"应当": "正确：“应当”表示按道理理应如此，符合句意。", "敢": "语义：“敢”表示有胆量去做，这句只是说学生理应按时完成作业，没有敢不敢的意思。", "把": "语法：“把”是介词，不能直接放在“按时完成作业”前面。", "可能": "语义：“可能”表示推测，这句说的是理应如此，而不是推测会怎样。"}, "sentence_index": 0, "correct_answer": "应当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地球应当绕着太阳转。", "explanation": "这里不宜用〈应当〉。“应当”表示理应或按道理推断，用于人的行为或可推测的情况；陈述自然规律时直接说“地球绕着太阳转”。"}, {"text": "一年应当有十二个月。", "explanation": "这里不宜用〈应当〉。“应当”表示理应，用于人的行为；陈述既定事实时应直接说“一年有十二个月”。"}, {"text": "水应当往低处流。", "explanation": "这里不宜用〈应当〉。“应当”表示理应，不用来陈述水往低处流这类自然规律，应直接说“水往低处流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应当", "is_correct": true, "explanation": "正确：“应当”表示情理上应该感谢，符合句意。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”表示被动，不能直接放在“谢谢他”前面。"}, {"text": "肯", "is_correct": false, "explanation": "语义：“肯”表示愿意，这句说的是情理上该感谢，不是愿不愿意。"}, {"text": "能", "is_correct": false, "explanation": "语义：“能”表示能力或许可，这句强调情理上应当感谢，不是能不能。"}], "explanations": {"应当": "正确：“应当”表示情理上应该感谢，符合句意。", "被": "语法：“被”表示被动，不能直接放在“谢谢他”前面。", "肯": "语义：“肯”表示愿意，这句说的是情理上该感谢，不是愿不愿意。", "能": "语义：“能”表示能力或许可，这句强调情理上应当感谢，不是能不能。"}, "sentence_index": 6, "correct_answer": "应当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮应当绕着地球转。", "explanation": "这里不宜用〈应当〉。“应当”不用来陈述天体运行的规律，这类既定事实应直接说“月亮绕着地球转”。"}, {"text": "河水应当向北流。", "explanation": "这里不宜用〈应当〉。“应当”表示理应或推断，河水的流向是既定事实，应直接说“这条河向北流”。"}, {"text": "一个星期应当有七天。", "explanation": "这里不宜用〈应当〉。既定事实不用“应当”来说明，应直接说“一个星期有七天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很应当爱护树木。", "corrected_sentence": "我们应当爱护树木。", "error_description": "“很”不能修饰情态动词“应当”。应改为：“我们应当爱护树木。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应当应该节约用水。", "corrected_sentence": "我们应当节约用水。", "error_description": "“应当”和“应该”都是情态动词，不能叠用。应删去“应该”，改为：“我们应当节约用水。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
