INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86381, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“几个”是说不太多的几个，数一数就知道。", "primary_collocate": null, "pronunciation": "jǐ gè", "ipa": "tɕi˨˩ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上有几个苹果。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只认识他的几个朋友。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里只剩下几个学生。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了几个面包，你吃吧。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天只写了几个字。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有几个孩子在玩儿。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有几个鸡蛋。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天来了几个客人。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有几个问题想问老师。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店里只有几个人。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不多的几个，能数清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86381, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几个", "is_correct": true, "explanation": "几个：不多的几个，能数清，即本词。"}, {"text": "几刻", "is_correct": false, "explanation": "声母不同：gè 与 kè 的 g（不送气）与 k（送气）相对，几刻指几个一刻钟，意思不同。"}, {"text": "几课", "is_correct": false, "explanation": "声母不同：gè 与 kè 的 g 与 k 相对，几课指几节课，意思不同。"}, {"text": "几格", "is_correct": false, "explanation": "声调不同：gè（第四声）与 gé（第二声），几格指几个方格，意思不同。"}, {"text": "几克", "is_correct": false, "explanation": "声母不同：gè 与 kè 的 g 与 k 相对，几克指重量，意思不同。"}], "explanations": {"几个": "几个：不多的几个，能数清，即本词。", "几刻": "声母不同：gè 与 kè 的 g（不送气）与 k（送气）相对，几刻指几个一刻钟，意思不同。", "几课": "声母不同：gè 与 kè 的 g 与 k 相对，几课指几节课，意思不同。", "几格": "声调不同：gè（第四声）与 gé（第二声），几格指几个方格，意思不同。", "几克": "声母不同：gè 与 kè 的 g 与 k 相对，几克指重量，意思不同。"}, "sentence_index": null, "correct_answer": "几个"}, "level_3": {"options": [{"text": "每个", "is_correct": false, "explanation": "搭配：“有”后面不接“每个”这类指逐一的全称词，说「桌子上有每个苹果」不通。"}, {"text": "几个", "is_correct": true, "explanation": "正确。几个表示不多、能数清的少数数目，与“桌子上有”搭配自然。"}, {"text": "几只", "is_correct": false, "explanation": "量词：苹果用〈个〉，〈只〉多用于动物，几只苹果不通。"}, {"text": "全部", "is_correct": false, "explanation": "语义：全部指整体的全数，与表示不多数目的语境相反。"}], "explanations": {"每个": "搭配：“有”后面不接“每个”这类指逐一的全称词，说「桌子上有每个苹果」不通。", "几个": "正确。几个表示不多、能数清的少数数目，与“桌子上有”搭配自然。", "几只": "量词：苹果用〈个〉，〈只〉多用于动物，几只苹果不通。", "全部": "语义：全部指整体的全数，与表示不多数目的语境相反。"}, "sentence_index": 0, "correct_answer": "几个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去过几个北京。", "explanation": "这里应该用〈几次〉。几个用于计数可数的事物，说去过几次要用几次；北京是地点，不能用几个计数。"}, {"text": "我喝了几个水。", "explanation": "这里应该用〈几杯〉。个用于计量可数的个体，液体要用杯、瓶等量词，几个不能计量水。"}, {"text": "我们等了几个分钟。", "explanation": "这里应该用〈几〉。“分钟”本身是计量单位，前面不再加“个”，应说“几分钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86381, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "几个", "is_correct": true, "explanation": "几个：不多的几个，能数清，即本词。"}, {"text": "几歌", "is_correct": false, "explanation": "声调不同：gē（第一声）与 gè（第四声）。几歌指几首歌，意思不同。"}, {"text": "几颗", "is_correct": false, "explanation": "声母和声调都不同：kē 与 gè，k 送气，g 不送气。几颗用于小而圆的东西，意思不同。"}, {"text": "几根", "is_correct": false, "explanation": "韵母和声调不同：gēn 与 gè。几根用于细长的东西，意思不同。"}, {"text": "几盒", "is_correct": false, "explanation": "声母和声调不同：hé 与 gè。几盒指几个盒子装的量，意思不同。"}], "explanations": {"几个": "几个：不多的几个，能数清，即本词。", "几歌": "声调不同：gē（第一声）与 gè（第四声）。几歌指几首歌，意思不同。", "几颗": "声母和声调都不同：kē 与 gè，k 送气，g 不送气。几颗用于小而圆的东西，意思不同。", "几根": "韵母和声调不同：gēn 与 gè。几根用于细长的东西，意思不同。", "几盒": "声母和声调不同：hé 与 gè。几盒指几个盒子装的量，意思不同。"}, "sentence_index": null, "correct_answer": "几个"}, "level_3": {"options": [{"text": "哪个", "is_correct": false, "explanation": "语义：哪个用于询问哪一个，单数，与“还有”后面的少量陈述不合。"}, {"text": "几个", "is_correct": true, "explanation": "正确。几个表示不多、能数清的少数，与“冰箱里还有”搭配自然。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：哪些用于疑问，句子是陈述，不能用于陈述句。"}, {"text": "各个", "is_correct": false, "explanation": "搭配：各个指每一个，“还有各个鸡蛋”与表示少量的语境不搭。"}], "explanations": {"哪个": "语义：哪个用于询问哪一个，单数，与“还有”后面的少量陈述不合。", "几个": "正确。几个表示不多、能数清的少数，与“冰箱里还有”搭配自然。", "哪些": "语义：哪些用于疑问，句子是陈述，不能用于陈述句。", "各个": "搭配：各个指每一个，“还有各个鸡蛋”与表示少量的语境不搭。"}, "sentence_index": 6, "correct_answer": "几个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今年几个岁。", "explanation": "这里应该用〈几岁〉。年龄直接用岁计量，不能用〈个〉。"}, {"text": "我选了几个课。", "explanation": "这里应该用〈几门〉。课程用门计量，几个不能用来计数课程。"}, {"text": "我们有几个时间去玩。", "explanation": "这里应该用〈一点〉。时间是不可数的抽象名词，不能用“几个”计数，应说“一点时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EX