INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有几个个同学会游泳。", "corrected_sentence": "我们班有几个同学会游泳。", "error_description": "「几个个同学」错。几个的量词「个」后面重复了一个「个」，应删去多余的「个」，改为「几个同学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
