INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86382, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "数量词，表示不确定的较少的数目。", "primary_collocate": null, "pronunciation": "jǐ gè", "ipa": "tɕi˨˩ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这本书我只看了几个故事。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了几个办法，都很好。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上有几个人唱了歌。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边有几个小摊。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了几个同学，他们都不知道。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上挂着几个红灯笼。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上只剩下几个梨。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这里住过几个晚上。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上有几个老师发了言。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从包里拿出几个小礼物。", "target_word": "几个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不确定的较少的数目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86382, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "几个", "is_correct": true, "explanation": "几个：不确定的较少数目，即本词。"}, {"text": "几克", "is_correct": false, "explanation": "声母不同：gè 与 kè 的 g 与 k 相对，几克指几克的重量，意思不同。"}, {"text": "几格", "is_correct": false, "explanation": "声调不同：gè（第四声）与 gé（第二声），几格指几个方格，意思不同。"}, {"text": "寄个", "is_correct": false, "explanation": "声调不同：jǐ（第三声）与 jì（第四声），寄个指寄一下，意思不同。"}, {"text": "举个", "is_correct": false, "explanation": "韵母不同：jǐ 与 jǔ 的 i 与 u 相对，举个指举一个例子，意思不同。"}], "explanations": {"几个": "几个：不确定的较少数目，即本词。", "几克": "声母不同：gè 与 kè 的 g 与 k 相对，几克指几克的重量，意思不同。", "几格": "声调不同：gè（第四声）与 gé（第二声），几格指几个方格，意思不同。", "寄个": "声调不同：jǐ（第三声）与 jì（第四声），寄个指寄一下，意思不同。", "举个": "韵母不同：jǐ 与 jǔ 的 i 与 u 相对，举个指举一个例子，意思不同。"}, "sentence_index": null, "correct_answer": "几个"}, "level_3": {"options": [{"text": "每个", "is_correct": false, "explanation": "语义：每个指逐一的全部，与“只看了”表示有限的意思矛盾。"}, {"text": "全部", "is_correct": false, "explanation": "语义：全部指全体，与“只”表示少量的意思相反。"}, {"text": "几个", "is_correct": true, "explanation": "正确。几个表示不确定的较少数目，与“只看了”搭配自然。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：哪个用于询问一个特定对象，句子是陈述，与“只看了”不合。"}], "explanations": {"每个": "语义：每个指逐一的全部，与“只看了”表示有限的意思矛盾。", "全部": "语义：全部指全体，与“只”表示少量的意思相反。", "几个": "正确。几个表示不确定的较少数目，与“只看了”搭配自然。", "哪个": "语义：哪个用于询问一个特定对象，句子是陈述，与“只看了”不合。"}, "sentence_index": 0, "correct_answer": "几个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喝了几个茶。", "explanation": "这里应该用〈几杯〉。茶是液体，要用杯、壶等量词计量，几个不能计量茶。"}, {"text": "他寄了几个信。", "explanation": "这里应该用〈几封〉。寄信的量词是封，应说寄了几封信，几个不这么用。"}, {"text": "他这周读了几个诗。", "explanation": "这里应该用〈几首〉。诗用首计量，几个不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86382, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "几个", "is_correct": true, "explanation": "几个：不确定的较少数目，即本词。"}, {"text": "几刻", "is_correct": false, "explanation": "声母不同：gè 与 kè 的 g 与 k 相对，几刻指几个一刻钟，意思不同。"}, {"text": "几课", "is_correct": false, "explanation": "声母不同：gè 与 kè 的 g 与 k 相对，几课指几节课，意思不同。"}, {"text": "起个", "is_correct": false, "explanation": "声母不同：jǐ 与 qǐ 的 j 与 q 相对，起个指起一个名字等，意思不同。"}, {"text": "洗个", "is_correct": false, "explanation": "声母不同：jǐ 与 xǐ 的 j 与 x 相对，洗个是洗一下的意思。"}], "explanations": {"几个": "几个：不确定的较少数目，即本词。", "几刻": "声母不同：gè 与 kè 的 g 与 k 相对，几刻指几个一刻钟，意思不同。", "几课": "声母不同：gè 与 kè 的 g 与 k 相对，几课指几节课，意思不同。", "起个": "声母不同：jǐ 与 qǐ 的 j 与 q 相对，起个指起一个名字等，意思不同。", "洗个": "声母不同：jǐ 与 xǐ 的 j 与 x 相对，洗个是洗一下的意思。"}, "sentence_index": null, "correct_answer": "几个"}, "level_3": {"options": [{"text": "哪些", "is_correct": false, "explanation": "语义：哪些用于疑问，句子是陈述，不能用于陈述句。"}, {"text": "几个", "is_correct": true, "explanation": "正确。几个表示不确定的较少数目，与“树上只剩下”搭配自然。"}, {"text": "各个", "is_correct": false, "explanation": "语义：各个指每一个，与“只剩下”表示少量的意思矛盾。"}, {"text": "所有", "is_correct": false, "explanation": "语义：所有指全部，与“只剩下”的少量语境矛盾。"}], "explanations": {"哪些": "语义：哪些用于疑问，句子是陈述，不能用于陈述句。", "几个": "正确。几个表示不确定的较少数目，与“树上只剩下”搭配自然。", "各个": "语义：各个指每一个，与“只剩下”表示少量的意思矛盾。", "所有": "语义：所有指全部，与“只剩下”的少量语境矛盾。"}, "sentence_index": 6, "correct_answer": "几个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着几个纸。", "explanation": "这里应该用〈几张〉。纸用张计量，几个不这么用。"}, {"text": "她买了几个裤子。", "explanation": "这里应该用〈几条〉。裤子用条计量，几个不这么用。"}, {"text": "她买了几个衣服。", "explanation": "这里应该用〈几件〉。衣服用件、套计量，几个不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EX