INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "饭桌上有很几个盘子。", "corrected_sentence": "饭桌上有几个盘子。", "error_description": "「很几个盘子」错。几个是数量词，不能被“很”修饰，应删去「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的书架上有几个书。", "corrected_sentence": "我的书架上有几本书。", "error_description": "「几个书」错。书的量词是〈本〉，几个用于其他可数事物，应改为「几本书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
