INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86383, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "心是在我们身体里面、会一跳一跳的器官。", "primary_collocate": null, "pronunciation": "xīn", "ipa": "ɕin⁵⁵", "syllable_count": 1, "sentences": [{"text": "我的心一跳一跳的。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手放在胸口，感到心在跳。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我紧张得心都快跳出来了。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的心有点问题。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，我的心还在一跳一跳的。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的心猛地一跳。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用听诊器听了听我的心。", "target_word": "心", "complexity_tier": "T3", "furigana": "xīn", "sentence_source": "generated"}, {"text": "小鸟的心很小，一跳一跳的。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗的心也会一跳一跳的。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完检查，医生说我的心没有问题。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开心", "label": "复合"}, {"form": "小心", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体里会跳动的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86383, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "心", "is_correct": true, "explanation": "心（xīn，第一声）：指身体里会跳动的器官，正是这里要听的词。"}, {"text": "信", "is_correct": false, "explanation": "xìn（第四声）与 xīn（第一声）声调不同，意思是信件。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 xīn 声母不同（j 与 x），意思是金子。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是星星。"}], "explanations": {"心": "心（xīn，第一声）：指身体里会跳动的器官，正是这里要听的词。", "信": "xìn（第四声）与 xīn（第一声）声调不同，意思是信件。", "金": "jīn 与 xīn 声母不同（j 与 x），意思是金子。", "星": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是星星。"}, "sentence_index": null, "correct_answer": "心"}, "level_3": {"options": [{"text": "书", "is_correct": false, "explanation": "语义：书不会一跳一跳地动，「我的书一跳一跳的」句意不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会跳动，与「一跳一跳的」不搭。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「一跳一跳的」只能描述器官或动物等能跳动的事物，不能说「窗户」。"}, {"text": "心", "is_correct": true, "explanation": "心：指身体里跳动的器官，「我的心一跳一跳的」描述心脏跳动，正合句意。"}], "explanations": {"书": "语义：书不会一跳一跳地动，「我的书一跳一跳的」句意不通。", "房子": "语义：房子不会跳动，与「一跳一跳的」不搭。", "窗户": "搭配：「一跳一跳的」只能描述器官或动物等能跳动的事物，不能说「窗户」。", "心": "心：指身体里跳动的器官，「我的心一跳一跳的」描述心脏跳动，正合句意。"}, "sentence_index": 0, "correct_answer": "心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心很细，做事很认真。", "explanation": "这里说的〈心〉指性格或思想，不指身体器官，与“医生说他的心有问题”的器官义不同。"}, {"text": "他的一只心有点问题。", "explanation": "这里不该用〈只〉。〈心〉作量词用〈颗〉，〈只〉用于动物或成对的东西。"}, {"text": "这座城市的心是一条热闹的商业街。", "explanation": "这里的〈心〉指中心，不指身体器官；这是另一个义项，不能用来说人的器官有问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86383, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "心", "is_correct": true, "explanation": "心（xīn，第一声）：指身体里会跳动的器官，正是这里要听的词。"}, {"text": "亲", "is_correct": false, "explanation": "qīn 与 xīn 声母不同（q 与 x），意思是亲人。"}, {"text": "今", "is_correct": false, "explanation": "jīn 与 xīn 声母不同（j 与 x），意思是今天。"}, {"text": "兴", "is_correct": false, "explanation": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是兴起。"}], "explanations": {"心": "心（xīn，第一声）：指身体里会跳动的器官，正是这里要听的词。", "亲": "qīn 与 xīn 声母不同（q 与 x），意思是亲人。", "今": "jīn 与 xīn 声母不同（j 与 x），意思是今天。", "兴": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是兴起。"}, "sentence_index": null, "correct_answer": "心"}, "level_3": {"options": [{"text": "腿", "is_correct": false, "explanation": "语义：听诊器听的是胸腔里的器官，腿不是听诊的部位，句意不通。"}, {"text": "车", "is_correct": false, "explanation": "语义：车不能被听诊器听，「听了听我的车」句意不通。"}, {"text": "门", "is_correct": false, "explanation": "搭配：「听了听」后面要接身体器官，不能接「门」。"}, {"text": "心", "is_correct": true, "explanation": "心：身体里跳动的器官，听诊器听的正是心脏，「听了听我的心」合乎句意。"}], "explanations": {"腿": "语义：听诊器听的是胸腔里的器官，腿不是听诊的部位，句意不通。", "车": "语义：车不能被听诊器听，「听了听我的车」句意不通。", "门": "搭配：「听了听」后面要接身体器官，不能接「门」。", "心": "心：身体里跳动的器官，听诊器听的正是心脏，「听了听我的心」合乎句意。"}, "sentence_index": 6, "correct_answer": "心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果的心很酸，不好吃。", "explanation": "这里的〈心〉指果实中间的核，不指人体器官；这是另一个义项，与“医生说我的心没有问题”不同。"}, {"text": "听到这个坏消息，他的心很乱。", "explanation": "这里的〈心〉指情绪、思想，属思想感情义，不是身体器官。"}, {"text": "我手里拿着一把心。", "explanation": "这里不该用〈把〉。〈心〉作量词要用〈颗〉，〈把〉用于有柄的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生说他有一只健康的心。", "corrected_sentence": "医生说他有一颗健康的心。", "error_description": "错误：「心」的量词用错了。「只」用于动物或成对的东西，「心」应用量词「颗」，应改为「医生说他有一颗健康的心。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说这颗的心很健康。", "corrected_sentence": "医生说这颗心很健康。", "error_description": "错误：量词短语后加了“的”。“这颗”后面直接接名词“心”，中间不能加“的”，应删去“的”，说“医生说这颗心很健康。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
