INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86384, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心指人的思想、感情或内心活动。", "primary_collocate": null, "pronunciation": "xīn", "ipa": "ɕin⁵⁵", "syllable_count": 1, "sentences": [{"text": "他的心不在学习上。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的心一直放在孩子身上。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，我的心一下子轻松了。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的心很乱，不知道怎么办。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一颗善良的心。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的心很细。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他哭，我的心也难过了。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话让我的心很暖。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失去工作以后，他的心变得很冷。", "target_word": "心", "complexity_tier": "T3", "furigana": "xīn", "sentence_source": "generated"}, {"text": "他离家以后，妈妈的心一直很不安。", "target_word": "心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开心", "label": "复合"}, {"form": "小心", "label": "复合"}], "register": "中性", "sense_fingerprint": "思想感情，内心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86384, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "心", "is_correct": true, "explanation": "心（xīn，第一声）：指思想感情，正是这里要听的词。"}, {"text": "信", "is_correct": false, "explanation": "xìn（第四声）与 xīn（第一声）声调不同，意思是相信或信件。"}, {"text": "今", "is_correct": false, "explanation": "jīn 与 xīn 声母不同（j 与 x），意思是今天。"}, {"text": "兴", "is_correct": false, "explanation": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是兴起。"}], "explanations": {"心": "心（xīn，第一声）：指思想感情，正是这里要听的词。", "信": "xìn（第四声）与 xīn（第一声）声调不同，意思是相信或信件。", "今": "jīn 与 xīn 声母不同（j 与 x），意思是今天。", "兴": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是兴起。"}, "sentence_index": null, "correct_answer": "心"}, "level_3": {"options": [{"text": "手", "is_correct": false, "explanation": "语义：「手」不能用来表示思想或心思，「他的手不在学习上」句意不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：「书」是物品，不能表示注意力或心思，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「不在……上」前面要接人的心思，不能接「桌子」。"}, {"text": "心", "is_correct": true, "explanation": "心：指思想感情或注意力，「他的心不在学习上」表示他的注意力不在学习上，正合句意。"}], "explanations": {"手": "语义：「手」不能用来表示思想或心思，「他的手不在学习上」句意不通。", "书": "语义：「书」是物品，不能表示注意力或心思，句意不通。", "桌子": "搭配：「不在……上」前面要接人的心思，不能接「桌子」。", "心": "心：指思想感情或注意力，「他的心不在学习上」表示他的注意力不在学习上，正合句意。"}, "sentence_index": 0, "correct_answer": "心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜的心很甜。", "explanation": "这里的〈心〉指果实中间的部分，不指思想感情，是另一个义项。"}, {"text": "他的心跳很快，要去医院检查。", "explanation": "这里的〈心〉指身体器官，讲的是心脏跳得快，与句中要表达的思想感情不是一个义项。"}, {"text": "我的一只心很乱，不知道怎么办。", "explanation": "这里不该用〈只〉。〈心〉作量词用〈颗〉，〈只〉用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86384, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "心", "is_correct": true, "explanation": "心（xīn，第一声）：指思想感情，正是这里要听的词。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 xīn 声母不同（j 与 x），意思是金子。"}, {"text": "亲", "is_correct": false, "explanation": "qīn 与 xīn 声母不同（q 与 x），意思是亲人。"}, {"text": "星", "is_correct": false, "explanation": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是星星。"}], "explanations": {"心": "心（xīn，第一声）：指思想感情，正是这里要听的词。", "金": "jīn 与 xīn 声母不同（j 与 x），意思是金子。", "亲": "qīn 与 xīn 声母不同（q 与 x），意思是亲人。", "星": "xīng 与 xīn 韵母不同（后鼻音 ng 与 n），意思是星星。"}, "sentence_index": null, "correct_answer": "心"}, "level_3": {"options": [{"text": "眼", "is_correct": false, "explanation": "语义：「眼」是器官，本身不会难过，「我的眼也难过了」句意不通。"}, {"text": "嘴", "is_correct": false, "explanation": "语义：「嘴」不能表示感情，「我的嘴也难过了」句意不通。"}, {"text": "腿", "is_correct": false, "explanation": "搭配：「难过」的主语要是人的心或感情，不能是「腿」。"}, {"text": "心", "is_correct": true, "explanation": "心：指思想感情，「我的心也难过了」表示我也感到伤心，正合句意。"}], "explanations": {"眼": "语义：「眼」是器官，本身不会难过，「我的眼也难过了」句意不通。", "嘴": "语义：「嘴」不能表示感情，「我的嘴也难过了」句意不通。", "腿": "搭配：「难过」的主语要是人的心或感情，不能是「腿」。", "心": "心：指思想感情，「我的心也难过了」表示我也感到伤心，正合句意。"}, "sentence_index": 6, "correct_answer": "心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一本善良的心。", "explanation": "这里不该用〈本〉。〈心〉作量词用〈颗〉，〈本〉用于书籍。"}, {"text": "我们学校的心在操场旁边。", "explanation": "这里的〈心〉指中心，不指思想感情；这是另一个义项，与“妈妈的心一直很不安”不同。"}, {"text": "妈妈的心一直跳得很快，要去看医生。", "explanation": "这里的〈心〉指身体器官，讲心脏跳得快，与句中表达的不安情绪不是同一个义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一只细腻的心。", "corrected_sentence": "她有一颗细腻的心。", "error_description": "错误：「心」的量词用错了。「只」用于动物或成对的东西，「心」应用量词「颗」，应改为「她有一颗细腻的心。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子平安回家，妈妈的一只心终于放下了。", "corrected_sentence": "孩子平安回家，妈妈的一颗心终于放下了。", "error_description": "错误：「心」的量词用错了。「只」用于动物或成对的东西，「心」应用量词「颗」，应改为「孩子平安回家，妈妈的一颗心终于放下了。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
