INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86385, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86385, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成员是一个队里的每一个人。", "primary_collocate": null, "pronunciation": "chéng yuán", "ipa": "ʈʂʰɤŋ˧˥ ɥæn˧˥", "syllable_count": 2, "sentences": [{"text": "他是我们队的成员。", "target_word": "成员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个队有十名成员。", "target_word": "成员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新成员今天来了。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个成员都要跑步。", "target_word": "成员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥是足球队的成员。", "target_word": "成员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们队来了一个新成员。", "target_word": "成员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队成员都穿着红色的衣服。", "target_word": "成员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请队里的每个成员站好。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王是篮球队里最小的成员。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，成员们一起吃了饭。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "成员们", "label": "复数形式"}], "register": "中性", "sense_fingerprint": "一个队里的每一个人，如队伍成员、新成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86385, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成员", "is_correct": true, "explanation": "正确。“成员”指队里的一个人，与“他是我们队的”搭配。"}, {"text": "皮球", "is_correct": false, "explanation": "语义：“皮球”是物品，不能指队里的一员，句意不通。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：“比赛”是活动，不是人，不能用于“他是……的”。"}, {"text": "球场", "is_correct": false, "explanation": "搭配：“我们队的”后接人或组织，不接场地。"}], "explanations": {"成员": "正确。“成员”指队里的一个人，与“他是我们队的”搭配。", "皮球": "语义：“皮球”是物品，不能指队里的一员，句意不通。", "比赛": "语义：“比赛”是活动，不是人，不能用于“他是……的”。", "球场": "搭配：“我们队的”后接人或组织，不接场地。"}, "sentence_index": 0, "correct_answer": "成员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种饮料的主要成员是糖。", "explanation": "这里应该用〈成分〉。“成分”指组成事物的各部分；“成员”指组织或团体中的人，不能用来说饮料的组成。"}, {"text": "这把椅子是我们队的成员。", "explanation": "这里误用了〈成员〉的“人”义，把它当作“物件”来用。这个词只指团队中的人，椅子不能成为队员。"}, {"text": "他这次考试的成员很高。", "explanation": "这里应该用〈成绩〉。“成绩”指考试或比赛的结果；“成员”指团体中的人，不能说“成员很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86385, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成员", "is_correct": true, "explanation": "正确。“球队成员”指球队里的人，主语是人，可以穿衣服。"}, {"text": "球门", "is_correct": false, "explanation": "语义：“球门”是球场上的设施，不会穿衣服，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不是人，不能作“穿着衣服”的主语。"}, {"text": "球衣", "is_correct": false, "explanation": "搭配：“穿”的主语应是人，“球衣”是被穿的东西，与“穿着”搭配不当。"}], "explanations": {"成员": "正确。“球队成员”指球队里的人，主语是人，可以穿衣服。", "球门": "语义：“球门”是球场上的设施，不会穿衣服，句意不通。", "冰箱": "语义：“冰箱”是家电，不是人，不能作“穿着衣服”的主语。", "球衣": "搭配：“穿”的主语应是人，“球衣”是被穿的东西，与“穿着”搭配不当。"}, "sentence_index": 6, "correct_answer": "成员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家书店的成员一共有三层。", "explanation": "这里应该用〈楼层〉。“成员”指团体中的人，不能用来数书店的楼层。"}, {"text": "这个城市的成员大多是年轻人。", "explanation": "这里应该用〈市民〉。“成员”指团体中的人，住在城市里的人应说市民，不说城市的成员。"}, {"text": "他在比赛中取得了很好的成员。", "explanation": "这里应该用〈成绩〉。“成绩”指取得的结果，“成员”指团体中的人，不能说“取得很好的成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "俱乐部新来了三只成员。", "corrected_sentence": "俱乐部新来了三名成员。", "error_description": "错误：量词“只”用于动物，不能用来数人。应改为“三名成员”，“名”用于指人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三名成员们都来了。", "corrected_sentence": "三名成员都来了。", "error_description": "错误：数词加量词之后，不能再加“们”。“们”只用于没有数量词修饰的复数，应改为“三名成员都来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
