INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指组织或团体中的一分子。", "primary_collocate": null, "pronunciation": "chéng yuán", "ipa": "ʈʂʰɤŋ˧˥ ɥæn˧˥", "syllable_count": 2, "sentences": [{"text": "她是读书会的成员。", "target_word": "成员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个俱乐部有三百名成员。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李想成为合唱团的成员。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家有五位成员，大家都爱笑。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者协会的成员每周见一次面。", "target_word": "成员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经不是我们小组的成员了。", "target_word": "成员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要选三名成员去开会。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要加入这个社团，先要成为正式成员。", "target_word": "成员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组织的成员来自不同的国家。", "target_word": "成员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新成员要先填一张表。", "target_word": "成员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "成员们", "label": "复数形式"}], "register": "中性", "sense_fingerprint": "组织或团体中的一分子，如社团成员、正式成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成员", "is_correct": true, "explanation": "正确。“读书会的成员”指读书会里的人，与句意相符。"}, {"text": "书架", "is_correct": false, "explanation": "语义：“书架”是家具，不是人，不能说“她是读书会的书架”。"}, {"text": "图书", "is_correct": false, "explanation": "语义：“图书”是物品，不能指一个人的身份。"}, {"text": "杂志", "is_correct": false, "explanation": "搭配：“是……的”后接人或身份，不接出版物。"}], "explanations": {"成员": "正确。“读书会的成员”指读书会里的人，与句意相符。", "书架": "语义：“书架”是家具，不是人，不能说“她是读书会的书架”。", "图书": "语义：“图书”是物品，不能指一个人的身份。", "杂志": "搭配：“是……的”后接人或身份，不接出版物。"}, "sentence_index": 0, "correct_answer": "成员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种面包的主要成员是面粉。", "explanation": "这里应该用〈成分〉。“成分”指组成事物的各部分；“成员”指组织或团体中的人，不能用来说食物的组成。"}, {"text": "这把伞是读书会的成员。", "explanation": "这里误用了〈成员〉的“人”义，把它当作“物件”来用。读书会的成员只能是人，伞不能成为其中一员。"}, {"text": "这个项目取得了很大的成员。", "explanation": "这里应该用〈成果〉。“成果”指取得的结果，“成员”指团体中的人，不能说“取得很大的成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成员", "is_correct": true, "explanation": "正确。“选三名成员去开会”指从团体中挑选几个人，符合句意。"}, {"text": "文件", "is_correct": false, "explanation": "语义：“文件”不能被选去开会，句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”不能去开会，选的对象必须是人。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“选……去开会”的对象应是人，“天气”与此搭配不当。"}], "explanations": {"成员": "正确。“选三名成员去开会”指从团体中挑选几个人，符合句意。", "文件": "语义：“文件”不能被选去开会，句意不通。", "椅子": "语义：“椅子”不能去开会，选的对象必须是人。", "天气": "搭配：“选……去开会”的对象应是人，“天气”与此搭配不当。"}, "sentence_index": 6, "correct_answer": "成员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家健身房的成员一共有五台。", "explanation": "这里应该用〈器材〉。“成员”指团体中的人，不能用来数健身房的机器。"}, {"text": "这张表是新成员。", "explanation": "这里误用了〈成员〉的“人”义，把它当作“物件”来用。“成员”只指人，一张表不能成为成员。"}, {"text": "这座小镇的成员大多是老人。", "explanation": "这里应该用〈居民〉。“成员”指团体中的人，住在小镇上的人应说居民，不说小镇的成员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社团有八只成员。", "corrected_sentence": "这个社团有八名成员。", "error_description": "错误：量词“只”用于动物，不能用来数人。应改为“八名成员”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个组织有五十名成员们。", "corrected_sentence": "这个组织有五十名成员。", "error_description": "错误：数词加量词之后，不能再加“们”。应改为“五十名成员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
