INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86387, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“未来”是还没有到的日子。", "primary_collocate": null, "pronunciation": "wèi lái", "ipa": "wei˥˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "未来的日子里，我会常常给你打电话。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想过未来吗？", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱存起来，为未来做打算。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也看不见未来。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没想好未来的工作。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对未来的生活，我有很多想法。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起想想未来十年的计划。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不总想以前的事，更爱想未来。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来的城市会更干净。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在为自己的未来努力工作。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "还没有到的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "正确。“未来的日子里”指还没到的日子，与句意相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不是时间，不能说“钢琴的日子里”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不能修饰“日子”表示时间。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“……的日子里”前应是时间或与时间相关的词，“草地”不搭配。"}], "explanations": {"未来": "正确。“未来的日子里”指还没到的日子，与句意相符。", "钢琴": "语义：“钢琴”是乐器，不是时间，不能说“钢琴的日子里”。", "冰箱": "语义：“冰箱”是家电，不能修饰“日子”表示时间。", "草地": "搭配：“……的日子里”前应是时间或与时间相关的词，“草地”不搭配。"}, "sentence_index": 0, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天都在回忆未来。", "explanation": "这里应该用〈过去〉。“回忆”指想起已经发生的事，未来还没到，不能回忆。"}, {"text": "我们在未来的一个月前分开了。", "explanation": "这里应该用〈以前〉。“一个月前”指过去的时间，与“未来”指还没到的时间矛盾。"}, {"text": "他已经在未来工作了三年。", "explanation": "这里应该用〈过去〉。“已经……了三年”指已经发生的时间，与“未来”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "正确。“想想未来十年的计划”指将要开始的十年，符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是物品，不能作“计划”的修饰语，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“想想……的计划”的修饰语应是时间，“窗户”与此搭配不当。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”不是时间，不能修饰“十年的计划”。"}], "explanations": {"未来": "正确。“想想未来十年的计划”指将要开始的十年，符合句意。", "钥匙": "语义：“钥匙”是物品，不能作“计划”的修饰语，句意不通。", "窗户": "搭配：“想想……的计划”的修饰语应是时间，“窗户”与此搭配不当。", "海洋": "语义：“海洋”不是时间，不能修饰“十年的计划”。"}, "sentence_index": 6, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的未来很厚。", "explanation": "这里误用了〈未来〉：它表示时间，没有厚薄，不能用“很厚”来形容。"}, {"text": "她在未来的昨天努力工作。", "explanation": "这里应该用〈过去〉。“昨天”已经过去，“未来”指还没到的时间，两者不能搭配。"}, {"text": "她把未来放进了书包里。", "explanation": "这里误用了〈未来〉：它表示还没到的时间，不是东西，不能放进书包里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
