INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86388, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指将要到来的时间，与“过去”相对。", "primary_collocate": null, "pronunciation": "wèi lái", "ipa": "wei˥˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "我对未来充满希望。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来的路还很长。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在未来几年出国学习。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人知道未来会怎么样。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要为未来做好准备。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在不久的未来，人人都能坐飞船旅行。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很担心自己的未来。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来一周会下雨。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未来一年，我想多读一些书。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好学习，才能有更好的未来。", "target_word": "未来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "将要到来的时间，与过去相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0ab6f7-c290-4f0d-b235-03751b345931') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86388, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "正确。“充满希望”指对将来的期待，“对未来充满希望”与句意相符。"}, {"text": "过去", "is_correct": false, "explanation": "语义：“充满希望”是对将来的期待，不能对已经过去的事充满希望。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”不是希望的对象，句意不通。"}, {"text": "钟表", "is_correct": false, "explanation": "搭配：“充满希望”的对象应是抽象的事情，不与“钟表”搭配。"}], "explanations": {"未来": "正确。“充满希望”指对将来的期待，“对未来充满希望”与句意相符。", "过去": "语义：“充满希望”是对将来的期待，不能对已经过去的事充满希望。", "垃圾": "语义：“垃圾”不是希望的对象，句意不通。", "钟表": "搭配：“充满希望”的对象应是抽象的事情，不与“钟表”搭配。"}, "sentence_index": 0, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很久以前，未来这里有很多恐龙。", "explanation": "这里应该用〈过去〉。“很久以前”指过去的时间，“未来”指还没到的时间，两者不能搭配。"}, {"text": "我对生活充满未来。", "explanation": "这里应该用〈希望〉。“充满希望”是固定搭配，“未来”是时间名词，不能用来“充满”。"}, {"text": "我们要记住未来的教训。", "explanation": "这里应该用〈过去〉。“记住教训”指已经发生的事，未来还没到，不能记住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86388, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未来", "is_correct": true, "explanation": "正确。“担心自己的未来”指担心将要发生的生活状况，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“担心”的对象应是人的处境或将来的事，“窗户”与此搭配不当。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”是场所，不是需要担心的人生状况，句意不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”不是可以担心的个人状况，句意不通。"}], "explanations": {"未来": "正确。“担心自己的未来”指担心将要发生的生活状况，符合句意。", "窗户": "搭配：“担心”的对象应是人的处境或将来的事，“窗户”与此搭配不当。", "图书馆": "语义：“图书馆”是场所，不是需要担心的人生状况，句意不通。", "海洋": "语义：“海洋”不是可以担心的个人状况，句意不通。"}, "sentence_index": 6, "correct_answer": "未来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把杯子放在未来上了。", "explanation": "这里误用了〈未来〉：它指时间，不表示地方或物体，不能把东西放在“未来上”。"}, {"text": "他在未来的一个星期前病了。", "explanation": "这里应该用〈以前〉。“一个星期前”指过去的时间，“未来”指还没到的时间，两者不能搭配。"}, {"text": "这块石头是更好的未来。", "explanation": "这里误用了〈未来〉：它只表示时间，这里却把它当作具体物品。应表达为“更好的前途”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86388, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在不远未来，我们也许能住在月球上。", "corrected_sentence": "在不远的未来，我们也许能住在月球上。", "error_description": "错误：“不远”修饰“未来”时要加“的”，应说“在不远的未来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86388, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我未来很重要，要好好学习。", "corrected_sentence": "我的未来很重要，要好好学习。", "error_description": "错误：表示“我的未来”时，“的”不能省略。应说“我的未来”，不能说“我未来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b60a0b58-1445-46fe-a6ba-4f5c00d56153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“反”相对，“挂正”与“挂反”构成反义。"}, {"text": "高", "is_correct": false, "explanation": "“高”指高度，与方向或样子的相对义无关。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”指光线明亮，与方向或样子的相对义无关。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”指速度，与方向或样子的相对义无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“反”相对，“挂正”与“挂反”构成反义。", "高": "“高”指高度，与方向或样子的相对义无关。", "亮": "“亮”指光线明亮，与方向或样子的相对义无关。", "慢": "“慢”指速度，与方向或样子的相对义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“反”相对，“字是正的”与“字是反的”构成反义。"}, {"text": "白", "is_correct": false, "explanation": "“白”指颜色，与方向或样子的相对义无关。"}, {"text": "大", "is_correct": false, "explanation": "“大”指大小，与方向或样子的相对义无关。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”指温度，与方向或样子的相对义无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“反”相对，“字是正的”与“字是反的”构成反义。", "白": "“白”指颜色，与方向或样子的相对义无关。", "大": "“大”指大小，与方向或样子的相对义无关。", "冷": "“冷”指温度，与方向或样子的相对义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“反”是说和原来的方向、样子正好相反。", "primary_collocate": null, "pronunciation": "fǎn", "ipa": "fan²¹⁴", "syllable_count": 1, "sentences": [{"text": "你的鞋穿反了。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书拿反了。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把衣服穿反了，大家都笑了。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画挂反了，快改一下。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方向反了，我们走错路了。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把名字写反了。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明看反了地图，所以走错了路。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字写反了，左右要换过来。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把钥匙插反了，怎么也插不进去。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子里的字全都是反的。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反面", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容方向、位置或样子与原来正好相对，常说穿反了、拿反了、写反了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a6dfb6-2ee6-453e-a7c2-961fd8e3fc9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是方向或样子相反。"}, {"text": "翻", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、翻动。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是方向或样子相反。", "翻": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、翻动。", "饭": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。", "赶": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。", "眼": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反", "is_correct": true, "explanation": "“穿反了”表示方向或位置与正确的相反，符合句意。"}, {"text": "晾", "is_correct": false, "explanation": "语法：“晾”是动词，不能作“穿”的结果补语，“穿晾了”不成立。"}, {"text": "凉", "is_correct": false, "explanation": "语义：“凉”描述温度，不能说鞋“穿凉了”来表示穿法出错。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“亮”不能作“穿”的结果补语，“穿亮了”不成立。"}], "explanations": {"反": "“穿反了”表示方向或位置与正确的相反，符合句意。", "晾": "语法：“晾”是动词，不能作“穿”的结果补语，“穿晾了”不成立。", "凉": "语义：“凉”描述温度，不能说鞋“穿凉了”来表示穿法出错。", "亮": "搭配：“亮”不能作“穿”的结果补语，“穿亮了”不成立。"}, "sentence_index": 0, "correct_answer": "反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙反进了抽屉。", "explanation": "这里应该用〈放〉。“反”不能表示放入、收进的意思，这里的说法不通。"}, {"text": "他每天都反自己的毛病。", "explanation": "这里的“反”是反省的意思，但“反”单独没有这个意思，应用〈反省〉。"}, {"text": "他给客人反了一杯茶。", "explanation": "这里应该用〈倒〉。“反”不能表示倒茶的意思，倒茶要用〈倒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是方向或样子相反。"}, {"text": "范", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。"}, {"text": "访", "is_correct": false, "explanation": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 fǎn（第三声）声调不同，意思是烦躁、麻烦。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是方向或样子相反。", "范": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。", "喊": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。", "访": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。", "烦": "fán（第二声）与 fǎn（第三声）声调不同，意思是烦躁、麻烦。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反", "is_correct": true, "explanation": "“看反了地图”表示看颠倒了方向，与“走错了路”的因果相符。"}, {"text": "清", "is_correct": false, "explanation": "语义：“看清了地图”表示看得清楚，与“走错了路”的因果矛盾。"}, {"text": "懂", "is_correct": false, "explanation": "语义：“看懂了地图”表示理解正确，与“走错了路”的因果矛盾。"}, {"text": "准", "is_correct": false, "explanation": "搭配：“看准”多用于看准目标或时机，与“地图”搭配不自然。"}], "explanations": {"反": "“看反了地图”表示看颠倒了方向，与“走错了路”的因果相符。", "清": "语义：“看清了地图”表示看得清楚，与“走错了路”的因果矛盾。", "懂": "语义：“看懂了地图”表示理解正确，与“走错了路”的因果矛盾。", "准": "搭配：“看准”多用于看准目标或时机，与“地图”搭配不自然。"}, "sentence_index": 6, "correct_answer": "反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快就反回了老家。", "explanation": "这里应该用〈返回〉。“反”单独没有“返回”的意思，这里的说法不通。"}, {"text": "他把球反给了对方。", "explanation": "这里应该用〈传〉。“反”不能表示传递、传给的意思，这里的用法不成立。"}, {"text": "他把这份报告反给了老师。", "explanation": "这里应该用〈交〉。“反”不能表示交给、呈交的意思，这里的用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把眼镜戴了反。", "corrected_sentence": "他把眼镜戴反了。", "error_description": "“反”是结果补语，应紧接动词“戴”之后，再接“了”。说成“戴了反”是语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把地图拿了反。", "corrected_sentence": "我把地图拿反了。", "error_description": "“反”是结果补语，应紧接动词“拿”之后，再接“了”。说成“拿了反”是语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "“正”与“反”相对，“正着穿”与“反着穿”构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”是动作动词，与“反”的方向相对义无关。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”是动作动词，与“反”的方向相对义无关。"}, {"text": "停", "is_correct": false, "explanation": "“停”指动作中止，与“反”的方向相对义无关。"}], "correct_answer": "正", "explanations": {"正": "“正”与“反”相对，“正着穿”与“反着穿”构成反义。", "跑": "“跑”是动作动词，与“反”的方向相对义无关。", "跳": "“跳”是动作动词，与“反”的方向相对义无关。", "停": "“停”指动作中止，与“反”的方向相对义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺", "is_correct": true, "explanation": "“顺”与“反”相对，“顺着想”与“反着想”构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”表示明白、不含糊，与“反”的相反义无关。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”表示繁多、不简单，与“反”的相反义无关。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”表示智力高，与“反”的相反义无关。"}], "correct_answer": "顺", "explanations": {"顺": "“顺”与“反”相对，“顺着想”与“反着想”构成反义。", "清楚": "“清楚”表示明白、不含糊，与“反”的相反义无关。", "复杂": "“复杂”表示繁多、不简单，与“反”的相反义无关。", "聪明": "“聪明”表示智力高，与“反”的相反义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“反”作动词，指把东西翻转过来，或做法与别人、与要求相违背。", "primary_collocate": null, "pronunciation": "fǎn", "ipa": "fan²¹⁴", "syllable_count": 1, "sentences": [{"text": "他总爱和我反着干。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把手心反过来看看。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把杯子反过来放在桌上。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把袜子反着穿了。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总跟老师反着来。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说东，你偏说西，为什么总是反着说？", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两个字的顺序反过来写。", "target_word": "反过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让他早睡，他却反着做。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把鞋反过来晾，里面干得快。", "target_word": "反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总跟大家反着想，大家都觉得他很怪。", "target_word": "反", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反过来", "label": "复合"}, {"form": "反着", "label": "体标"}], "register": "中性", "sense_fingerprint": "作动词，表示把东西翻转过来，或做法与别人、与要求相违背，如反过来、反着干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a6dfb6-2ee6-453e-a7c2-961fd8e3fc9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是翻转、相反。"}, {"text": "粉", "is_correct": false, "explanation": "fěn 与 fǎn 韵母不同（en 与 an），声调相同，意思是粉末、粉色。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。"}, {"text": "犯", "is_correct": false, "explanation": "fàn（第四声）与 fǎn 声调不同，意思是犯错、侵犯。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是翻转、相反。", "粉": "fěn 与 fǎn 韵母不同（en 与 an），声调相同，意思是粉末、粉色。", "饭": "fàn（第四声）与 fǎn（第三声）声调不同，意思是米饭、饭食。", "赶": "gǎn 与 fǎn 声母不同（g 与 f），声调相同，意思是赶上、驱赶。", "犯": "fàn（第四声）与 fǎn 声调不同，意思是犯错、侵犯。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反", "is_correct": true, "explanation": "“反着干”表示做法与对方或常规相反，符合句意。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲着干”表示回避，与句中“和我”一起做事的语境矛盾。"}, {"text": "瞒", "is_correct": false, "explanation": "搭配：“瞒着”需要被隐瞒的对象，“和我一起”做事时不能这样用。"}, {"text": "逃", "is_correct": false, "explanation": "搭配：“逃”不能接“着干”表示做事方式，“逃着干”不成立。"}], "explanations": {"反": "“反着干”表示做法与对方或常规相反，符合句意。", "躲": "语义：“躲着干”表示回避，与句中“和我”一起做事的语境矛盾。", "瞒": "搭配：“瞒着”需要被隐瞒的对象，“和我一起”做事时不能这样用。", "逃": "搭配：“逃”不能接“着干”表示做事方式，“逃着干”不成立。"}, "sentence_index": 0, "correct_answer": "反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把新买的书反到了书架上。", "explanation": "这里应该用〈放〉。“反”不能表示把东西放置到某处的意思，这里的说法不通。"}, {"text": "他每天晚上都反自己的过错。", "explanation": "这里的“反”是反省的意思，但“反”单独没有这个意思，应用〈反省〉。"}, {"text": "他给我反了一杯水。", "explanation": "这里应该用〈倒〉。倒水表示把液体注出，“反”不能表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "反", "is_correct": true, "explanation": "fǎn 与目标词同音同调，意思是翻转、相反。"}, {"text": "范", "is_correct": false, "explanation": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。"}, {"text": "喊", "is_correct": false, "explanation": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。"}, {"text": "访", "is_correct": false, "explanation": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。"}], "explanations": {"反": "fǎn 与目标词同音同调，意思是翻转、相反。", "范": "fàn（第四声）与 fǎn（第三声）声调不同，意思是范围、模范。", "喊": "hǎn 与 fǎn 声母不同（h 与 f），声调相同，意思是呼喊。", "眼": "yǎn 与 fǎn 声母不同（y 与 f），声调相同，意思是眼睛。", "访": "fǎng 与 fǎn 韵母不同（ang 与 an），声调相同，意思是拜访。"}, "sentence_index": null, "correct_answer": "反"}, "level_3": {"options": [{"text": "反过来", "is_correct": true, "explanation": "“顺序反过来写”表示按相反的次序书写，符合句意。"}, {"text": "写下来", "is_correct": false, "explanation": "搭配：“写下来”表示记录，不能用来说明“顺序”的调整，句子不通。"}, {"text": "擦掉", "is_correct": false, "explanation": "语义：“擦掉”表示去除，与“顺序”的调整不兼容，句子语义不通。"}, {"text": "念出来", "is_correct": false, "explanation": "语义：“念出来”表示朗读，不能表示调整顺序。"}], "explanations": {"反过来": "“顺序反过来写”表示按相反的次序书写，符合句意。", "写下来": "搭配：“写下来”表示记录，不能用来说明“顺序”的调整，句子不通。", "擦掉": "语义：“擦掉”表示去除，与“顺序”的调整不兼容，句子语义不通。", "念出来": "语义：“念出来”表示朗读，不能表示调整顺序。"}, "sentence_index": 6, "correct_answer": "反过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这本书反进了书架。", "explanation": "这里应该用〈放〉。“反”不能表示把东西放入某处的意思，这里的说法不通。"}, {"text": "他把这个问题反给了领导。", "explanation": "这里应该用〈反映〉。“反”单独没有“汇报、告知”的意思，这里的用法不成立。"}, {"text": "他一拳反给了对手。", "explanation": "这里应该用〈还〉。“反”不能表示还击的意思，还击要说〈还〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书反过放在桌上。", "corrected_sentence": "他把书反过来放在桌上。", "error_description": "“反过来”是一个整体，这里漏掉了“来”，应说“反过来放”。正确说法是“他把书反过来放在桌上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把词语念着反。", "corrected_sentence": "他把词语反着念。", "error_description": "“反着”作状语，应放在动词“念”之前。说成“念着反”是语序错误，不符合汉语的状语位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
