INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86391, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“条”用来数细长的东西，比如一条鱼、一条路。", "primary_collocate": null, "pronunciation": "tiáo", "ipa": "tʰiɑʊ̯³⁵", "syllable_count": 1, "sentences": [{"text": "河里有一条大鱼。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很长，我们走了一个小时。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一条红裙子。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一条白毛巾。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着一条蓝裤子。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上有一条小蛇。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的狗有一条长尾巴。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一条绳子。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河又宽又长。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我喜欢戴一条厚围巾。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数细长的东西的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86391, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "条", "is_correct": true, "explanation": "tiáo（第二声），量词，用于细长的东西，如“一条鱼”“一条路”。"}, {"text": "挑", "is_correct": false, "explanation": "tiāo（第一声）与 tiáo（第二声）声调不同，意思是挑选。"}, {"text": "跳", "is_correct": false, "explanation": "tiào（第四声）与 tiáo（第二声）声调不同，意思是跳跃。"}, {"text": "甜", "is_correct": false, "explanation": "tián 与 tiáo 只有韵母不同（ián 与 iáo），声调都是第二声，意思是甜。"}], "explanations": {"条": "tiáo（第二声），量词，用于细长的东西，如“一条鱼”“一条路”。", "挑": "tiāo（第一声）与 tiáo（第二声）声调不同，意思是挑选。", "跳": "tiào（第四声）与 tiáo（第二声）声调不同，意思是跳跃。", "甜": "tián 与 tiáo 只有韵母不同（ián 与 iáo），声调都是第二声，意思是甜。"}, "sentence_index": null, "correct_answer": "条"}, "level_3": {"options": [{"text": "条", "is_correct": true, "explanation": "条用于细长的东西，鱼是细长的，“一条大鱼”是正确搭配。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不能用来数鱼。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、桥等大型固定的东西，与“大鱼”不符。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的东西，不能用来数鱼。"}], "explanations": {"条": "条用于细长的东西，鱼是细长的，“一条大鱼”是正确搭配。", "张": "搭配：“张”用于平面的东西，不能用来数鱼。", "座": "语义：“座”指山、桥等大型固定的东西，与“大鱼”不符。", "把": "搭配：“把”用于有柄的东西，不能用来数鱼。"}, "sentence_index": 0, "correct_answer": "条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一条新书。", "explanation": "这里应该用〈本〉。书用“本”计量，“条”用于细长的东西，不能用来数书。"}, {"text": "我家养了一条猫。", "explanation": "这里应该用〈只〉。猫用“只”计量；“条”只用于鱼、蛇、狗等身体细长的动物，不用来数猫。"}, {"text": "教室里放着一条椅子。", "explanation": "这里应该用〈把〉。椅子用“把”计量，“条”不用于有靠背的家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条", "is_correct": true, "explanation": "条用于细长的东西，狗的尾巴是细长的，“一条长尾巴”是正确搭配。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能用来数尾巴。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌、歌曲，与“长尾巴”不符。"}, {"text": "场", "is_correct": false, "explanation": "语义：“场”指一次活动或比赛，不能用来数尾巴。"}], "explanations": {"条": "条用于细长的东西，狗的尾巴是细长的，“一条长尾巴”是正确搭配。", "辆": "搭配：“辆”用于车辆，不能用来数尾巴。", "首": "语义：“首”用于诗歌、歌曲，与“长尾巴”不符。", "场": "语义：“场”指一次活动或比赛，不能用来数尾巴。"}, "sentence_index": 6, "correct_answer": "条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他划了一条火柴。", "explanation": "这里应该用〈根〉。火柴是细小的杆状物，用“根”计量；“条”多用于绳索、带子、鱼、道路等细长的东西，火柴不用“条”。"}, {"text": "他点着了一条蜡烛。", "explanation": "这里应该用〈支〉。蜡烛用“支”计量，不用“条”。"}, {"text": "这个手电筒里装着一条电池。", "explanation": "这里应该用〈节〉。电池用“节”计量，“条”不用于电池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘里有一条的小鱼。", "corrected_sentence": "池塘里有一条小鱼。", "error_description": "结构错误：“一条”与后面的“小鱼”之间不能加“的”，应说“一条小鱼”，不说“一条的小鱼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脚上缠着一条的绷带。", "corrected_sentence": "他的脚上缠着一条绷带。", "error_description": "结构错误：“一条”与后面的“绷带”之间不能加“的”，应说“一条绷带”，不说“一条的绷带”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
