INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86392, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“条”用来数消息、规定、建议等事物。", "primary_collocate": null, "pronunciation": "tiáo", "ipa": "tʰiɑʊ̯³⁵", "syllable_count": 1, "sentences": [{"text": "我收到了一条短信。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天有一条重要的新闻。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有一条新规定。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告诉我一条好消息。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我一条很好的建议。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条消息是真的吗？", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上发了一条评论。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规定从明天开始执行。", "target_word": "条", "complexity_tier": "T3", "furigana": "tiáo", "sentence_source": "generated"}, {"text": "他在群里发了一条通知。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你回我一条信息。", "target_word": "条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数消息、规定、建议等事物的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fd271da-7053-4e94-b9bc-a929e14d7b33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86392, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "条", "is_correct": true, "explanation": "tiáo（第二声），量词，用于消息、规定、建议等可数的事物，如“一条短信”。"}, {"text": "挑", "is_correct": false, "explanation": "tiāo（第一声）与 tiáo（第二声）声调不同，意思是挑选。"}, {"text": "跳", "is_correct": false, "explanation": "tiào（第四声）与 tiáo（第二声）声调不同，意思是跳跃。"}, {"text": "甜", "is_correct": false, "explanation": "tián 与 tiáo 只有韵母不同（ián 与 iáo），声调都是第二声，意思是甜。"}], "explanations": {"条": "tiáo（第二声），量词，用于消息、规定、建议等可数的事物，如“一条短信”。", "挑": "tiāo（第一声）与 tiáo（第二声）声调不同，意思是挑选。", "跳": "tiào（第四声）与 tiáo（第二声）声调不同，意思是跳跃。", "甜": "tián 与 tiáo 只有韵母不同（ián 与 iáo），声调都是第二声，意思是甜。"}, "sentence_index": null, "correct_answer": "条"}, "level_3": {"options": [{"text": "条", "is_correct": true, "explanation": "条可以计量消息、短信等可数的事物，“一条短信”是正确搭配。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、桥等大型固定的东西，不能用来数短信。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的东西，不能用来数短信。"}, {"text": "片", "is_correct": false, "explanation": "语义：“片”指平面或成片的东西，与“短信”不符。"}], "explanations": {"条": "条可以计量消息、短信等可数的事物，“一条短信”是正确搭配。", "座": "语义：“座”指山、桥等大型固定的东西，不能用来数短信。", "把": "搭配：“把”用于有柄的东西，不能用来数短信。", "片": "语义：“片”指平面或成片的东西，与“短信”不符。"}, "sentence_index": 0, "correct_answer": "条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天读了一条小说。", "explanation": "这里应该用〈本〉。小说用“本”计量，“条”不能用来数小说。"}, {"text": "我家门口停了一条车。", "explanation": "这里应该用〈辆〉。车用“辆”计量，“条”不能用来数车。"}, {"text": "窗台上摆着一条花。", "explanation": "这里应该用〈朵〉。花用“朵”计量，“条”不能用来数花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条", "is_correct": true, "explanation": "条可以计量消息、评论等事物，“一条评论”是正确搭配。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车辆，不能用来数评论。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗歌、歌曲，与“评论”不符。"}, {"text": "场", "is_correct": false, "explanation": "语义：“场”指一次活动或比赛，不能用来数评论。"}], "explanations": {"条": "条可以计量消息、评论等事物，“一条评论”是正确搭配。", "辆": "搭配：“辆”用于车辆，不能用来数评论。", "首": "语义：“首”用于诗歌、歌曲，与“评论”不符。", "场": "语义：“场”指一次活动或比赛，不能用来数评论。"}, "sentence_index": 6, "correct_answer": "条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他送给我一条礼物。", "explanation": "这里应该用〈份〉。礼物用“份”计量；“条”多用于消息、规定、建议等，不用来数礼物。"}, {"text": "他唱了一条歌。", "explanation": "这里应该用〈首〉。歌用“首”计量，“条”不用于歌曲。"}, {"text": "我们昨天看了一条比赛。", "explanation": "这里应该用〈场〉。比赛用“场”计量，“条”不用于比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他给我发了一条的短信。", "corrected_sentence": "他给我发了一条短信。", "error_description": "结构错误：“一条”与后面的“短信”之间不能加“的”，应说“一条短信”，不说“一条的短信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友圈里有一条的新评论。", "corrected_sentence": "朋友圈里有一条新评论。", "error_description": "结构错误：“一条”与后面的“新评论”之间不能加“的”，应说“一条新评论”，不说“一条的新评论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47afdfdb-faac-4e71-8615-1782ee3bbe6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
