INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86393, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“的话”放在前面一句话后面，是说要是这样。", "primary_collocate": null, "pronunciation": "de huà", "ipa": "tɤ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "明天下雨的话，我们就不去了。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有空的话，请给我打电话。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是他不来的话，我们先开始。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累的话，就早点儿休息。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去商店的话，请帮我买点水果。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好的话，我想去公园。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他同意的话，我就没问题。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢的话，这本书送给你。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太贵的话，我就不买了。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班早的话，我去接你。", "target_word": "的话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在前一分句后；表示要是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a6dfb6-2ee6-453e-a7c2-961fd8e3fc9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "的话", "is_correct": true, "explanation": "正确。“的话”表示假设，“明天下雨的话”即如果明天下雨。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”是动态助词，表示持续，不能放在分句末表示假设，“明天下雨着”不成句。"}, {"text": "啦", "is_correct": false, "explanation": "语义：“啦”表示当前出现的新情况或感叹，与“明天”这一假设语境不合。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，与口语的“我们就不去了”不协调。"}], "explanations": {"的话": "正确。“的话”表示假设，“明天下雨的话”即如果明天下雨。", "着": "语法：“着”是动态助词，表示持续，不能放在分句末表示假设，“明天下雨着”不成句。", "啦": "语义：“啦”表示当前出现的新情况或感叹，与“明天”这一假设语境不合。", "矣": "语域：“矣”是文言语气词，与口语的“我们就不去了”不协调。"}, "sentence_index": 0, "correct_answer": "的话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去北京的话，买了很多东西。", "explanation": "这里不该用〈的话〉。“的话”表示假设，而“昨天”已经发生，不能用假设的语气。"}, {"text": "因为天气冷的话，我们就没去公园。", "explanation": "这里误把〈的话〉用在表示原因的分句里。“的话”只表示假设，而“天气冷”是已经存在的原因，应直接说“因为天气冷，所以……”。"}, {"text": "他刚才打电话的话，已经挂了。", "explanation": "这里不该用〈的话〉。“的话”表示假设，而“刚才打电话”已经发生，不能用假设的语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "的话", "is_correct": true, "explanation": "正确。“的话”表示假设，“他同意的话”即如果他同意。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”是疑问语气词，“他同意吗”变成询问，不能表示假设的条件。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言语气词，与口语的“我就没问题”不协调。"}, {"text": "罢", "is_correct": false, "explanation": "语义：“罢”表示让步或了结，与“他同意”这一假设条件的表达不合。"}], "explanations": {"的话": "正确。“的话”表示假设，“他同意的话”即如果他同意。", "吗": "语义：“吗”是疑问语气词，“他同意吗”变成询问，不能表示假设的条件。", "哉": "语域：“哉”是文言语气词，与口语的“我就没问题”不协调。", "罢": "语义：“罢”表示让步或了结，与“他同意”这一假设条件的表达不合。"}, "sentence_index": 6, "correct_answer": "的话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我上个月搬家的话，就找到了新工作。", "explanation": "这里不该用〈的话〉。“的话”表示假设，而“上个月搬家”已经发生，不能用假设的语气。"}, {"text": "因为下雨的话，我们就不去了。", "explanation": "这里误把〈的话〉用在表示原因的分句里。“的话”只表示假设，而“下雨”是已经发生或确定的原因，应直接说“因为下雨，所以……”。"}, {"text": "因为他没空的话，所以我们换个时间吧。", "explanation": "这里误把〈的话〉用在表示原因的分句里。“的话”只表示假设，与“因为……所以……”的因果关系冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你有时间的的话，我们一起吃饭吧。", "corrected_sentence": "你有时间的话，我们一起吃饭吧。", "error_description": "错误形式：“你有时间的的话”。“的话”是一个整体，其中的“的”不能重复；正确形式是“你有时间的话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你同意吗的话，我就去试试。", "corrected_sentence": "你同意的话，我就去试试。", "error_description": "错误形式：“吗的话”。“吗”是疑问语气词，不能与“的话”叠用；正确形式是“你同意的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
