INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86397, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“除了”是说把这个放在外面，不算在里面。", "primary_collocate": null, "pronunciation": "chú le", "ipa": "ʈʂʰu˧˥ lə", "syllable_count": 2, "sentences": [{"text": "除了周日，我每天都上班。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了他，大家都来了。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了鱼，我什么肉都吃。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里除了老师，没有别人。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题除了小明，没人做对。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家除了我，都喜欢喝茶。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了下雨天，他天天跑步。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了这本书，别的书我都看过了。", "target_word": "除了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了苹果，别的水果我都不爱吃。", "target_word": "除了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了冬天，这里的天气都很好。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "除了：介词，把某人或某物排除在外，其余都如何", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "除了", "is_correct": true, "explanation": "正确答案：“除了”，把“周日”排除在外，其余日子都上班，符合句意。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“为了周日”后接“我每天都上班”，句意不通。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”要引出依据或标准，不能把“周日”作为排除的对象。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对周日”不能表示排除，句意不通。"}], "explanations": {"除了": "正确答案：“除了”，把“周日”排除在外，其余日子都上班，符合句意。", "为了": "语义：“为了”表示目的，“为了周日”后接“我每天都上班”，句意不通。", "按照": "搭配：“按照”要引出依据或标准，不能把“周日”作为排除的对象。", "对": "语义：“对”引出对象，“对周日”不能表示排除，句意不通。"}, "sentence_index": 0, "correct_answer": "除了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "除了周日，我周日也上班。", "explanation": "这里应该用〈连〉。“除了”已把周日排除在外，后句又说周日也上班，前后矛盾；甚至包括在内应说“连周日也上班”。"}, {"text": "这次旅行的活动除了爬山和游泳。", "explanation": "这里应该用〈包括〉。“除了”表示排除在外，句子也不完整；表示计入在内要用“包括”。"}, {"text": "我们班的人都来了，除了老师，老师也来了。", "explanation": "这里应该用〈连〉。“除了”已把老师排除在外，后句又说老师也来了，前后矛盾；应说“连老师也来了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "除了", "is_correct": true, "explanation": "正确答案：“除了”，把“下雨天”排除在外，其余时间他天天跑步，符合句意。"}, {"text": "凭", "is_correct": false, "explanation": "搭配：“凭”要引出依据，“凭下雨天”不能作为排除的对象，搭配不当。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”要引出标准或依据，“按照下雨天”搭配不当。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“向”引出动作的方向或对象，“向下雨天”不能作为排除的对象，句意不通。"}], "explanations": {"除了": "正确答案：“除了”，把“下雨天”排除在外，其余时间他天天跑步，符合句意。", "凭": "搭配：“凭”要引出依据，“凭下雨天”不能作为排除的对象，搭配不当。", "按照": "搭配：“按照”要引出标准或依据，“按照下雨天”搭配不当。", "向": "搭配：“向”引出动作的方向或对象，“向下雨天”不能作为排除的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "除了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "除了小李，班里的人除了都来了。", "explanation": "这里应该删去第二个〈除了〉。“除了”只能用在被排除的对象前面，不能放在“都”前面重复使用。"}, {"text": "这件事除了小孩，小孩也都知道。", "explanation": "这里应该用〈连〉。“除了”已把小孩排除在外，后句又说小孩也都知道，前后矛盾；应说“连小孩也都知道”。"}, {"text": "除了冬天，这里冬天的天气也很好。", "explanation": "这里应该用〈连〉。“除了”已把冬天排除在外，后句又说冬天也好，前后矛盾；应说“连冬天天气也很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "除了，我们班的人都来了。", "corrected_sentence": "除了他，我们班的人都来了。", "error_description": "错误形式：“除了，我们班的人都来了。” 正确形式：“除了他，我们班的人都来了。” “除了”是介词，后面必须带所排除的对象；此处缺少对象“他”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "除了，大家都很累。", "corrected_sentence": "除了老师，大家都很累。", "error_description": "错误形式：“除了，大家都很累。”正确形式：“除了老师，大家都很累。”“除了”是介词，后面必须带所排除的对象；此处缺少对象“老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
