INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86398, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示在某一范围之外另有的人或事物，常与“还”“也”呼应。", "primary_collocate": null, "pronunciation": "chú le", "ipa": "ʈʂʰu˧˥ lə", "syllable_count": 2, "sentences": [{"text": "除了英语，他还会说日语。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了苹果，我还买了一些香蕉。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了工作，她也喜欢画画。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了妈妈，家里还有爸爸和弟弟。", "target_word": "除了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了中文课，我们还有音乐课。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了看书，他还常常去公园跑步。", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店除了卖茶，还卖各种点心。", "target_word": "除了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了小王，小李也来参加了会议。", "target_word": "除了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了牛奶，早上我还喝一杯咖啡。", "target_word": "除了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了你，还有谁知道这件事？", "target_word": "除了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "除了：介词，引出范围之外另有的人或事物，后接“还/也”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "除了", "is_correct": true, "explanation": "正确答案：“除了”，引出“英语”这一排除项，后句说明此外还会说日语，符合句意。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，“为了英语”与后半句的意思不相关，句意不通。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”要引出依据或标准，不能引出“英语”这类对象。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点或来源，“从英语”后接“还会说日语”，句意不通。"}], "explanations": {"除了": "正确答案：“除了”，引出“英语”这一排除项，后句说明此外还会说日语，符合句意。", "为了": "语义：“为了”表示目的，“为了英语”与后半句的意思不相关，句意不通。", "按照": "搭配：“按照”要引出依据或标准，不能引出“英语”这类对象。", "从": "语义：“从”表示起点或来源，“从英语”后接“还会说日语”，句意不通。"}, "sentence_index": 0, "correct_answer": "除了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "除了英语，他还会说英语。", "explanation": "这里应该把后一个〈英语〉改为别的语言。“除了英语”已把英语单列，后句又重复“英语”，与“除了”引出的追加对象不符。"}, {"text": "这次旅行除了爬山和游泳。", "explanation": "这里应该用〈包括〉。“除了”表示排除在外，句子也不完整；表示计入在内要用“包括”。"}, {"text": "除了他会说英语，还会说日语。", "explanation": "这里应该把〈他〉放到“除了”前面：“他除了会说英语，还会说日语”。主语放在“除了”短语里，后一句就没有主语了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "除了", "is_correct": true, "explanation": "正确答案：“除了”，引出“卖茶”之外还卖点心，符合句意。"}, {"text": "凭", "is_correct": false, "explanation": "搭配：“凭”要引出依据，“凭卖茶”不能引出后面的内容，搭配不当。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”要引出标准或依据，“按照卖茶”搭配不当。"}, {"text": "由", "is_correct": false, "explanation": "语义：“由”表示由某人或某事引出施事，“由卖茶”与后文句意不通。"}], "explanations": {"除了": "正确答案：“除了”，引出“卖茶”之外还卖点心，符合句意。", "凭": "搭配：“凭”要引出依据，“凭卖茶”不能引出后面的内容，搭配不当。", "按照": "搭配：“按照”要引出标准或依据，“按照卖茶”搭配不当。", "由": "语义：“由”表示由某人或某事引出施事，“由卖茶”与后文句意不通。"}, "sentence_index": 6, "correct_answer": "除了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很聪明，除了很努力。", "explanation": "这里应该用〈而且〉。“除了”要引出一个排除或增加的对象，不能直接接形容词作并列。"}, {"text": "这家店除了卖茶，也不卖点心。", "explanation": "这里应该用〈还卖〉。“除了”引出追加的内容时，后面要用“还/也”说明另外有什么，不能接否定。"}, {"text": "我们班的人都来了，除了小王，小王也来了。", "explanation": "这里应该用〈连〉。“除了小王”已把小王排除在外，后句又说小王也来了，前后矛盾；应说“连小王也来了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "除了，大家都没去。", "corrected_sentence": "除了小王，大家都没去。", "error_description": "错误形式：“除了，大家都没去。” 正确形式：“除了小王，大家都没去。” “除了”是介词，后面必须带所排除的对象；此处缺少对象“小王”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "除了，还有谁能帮忙？", "corrected_sentence": "除了我，还有谁能帮忙？", "error_description": "错误形式：“除了，还有谁能帮忙？”正确形式：“除了我，还有谁能帮忙？”“除了”是介词，后面必须带对象；此处缺少对象“我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
