INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86400, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，很；相当。", "primary_collocate": null, "pronunciation": "tǐng", "ipa": "tʰiŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这家店的面条挺好吃的。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气挺好，我们去公园吧。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得挺流利。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服我穿着挺合适。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个电影挺有意思的。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里挺安静，大家都在看书。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天挺高兴，因为考试通过了。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我家到学校挺远的，要坐地铁。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书挺贵，我没有买。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来挺累，应该早点休息。", "target_word": "挺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词，用在形容词前，表示程度相当高，口语常与“的”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfe20271-9b49-478a-a8e6-68fb9be44438') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挺", "is_correct": true, "explanation": "正确：挺 tǐng，意思是很、相当，程度副词。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 tǐng（第三声）声调不同，意思是停止。"}, {"text": "听", "is_correct": false, "explanation": "tīng（第一声）与 tǐng（第三声）声调不同，意思是听见。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng 与 tǐng 声母不同（d 与 t），意思是顶住。"}, {"text": "醒", "is_correct": false, "explanation": "xǐng 与 tǐng 声母不同（x 与 t），意思是醒来。"}], "explanations": {"挺": "正确：挺 tǐng，意思是很、相当，程度副词。", "停": "tíng（第二声）与 tǐng（第三声）声调不同，意思是停止。", "听": "tīng（第一声）与 tǐng（第三声）声调不同，意思是听见。", "顶": "dǐng 与 tǐng 声母不同（d 与 t），意思是顶住。", "醒": "xǐng 与 tǐng 声母不同（x 与 t），意思是醒来。"}, "sentence_index": null, "correct_answer": "挺"}, "level_3": {"options": [{"text": "挺", "is_correct": true, "explanation": "正确：“挺好吃的”表示程度相当高，符合句意。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不好吃的”与“面条”的赞美语境相反，句意不符。"}, {"text": "必", "is_correct": false, "explanation": "搭配：“必”只用于“必须、必定”一类，不能修饰形容词“好吃”。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有转折语境，“却好吃的”说不通。"}], "explanations": {"挺": "正确：“挺好吃的”表示程度相当高，符合句意。", "不": "语义：“不好吃的”与“面条”的赞美语境相反，句意不符。", "必": "搭配：“必”只用于“必须、必定”一类，不能修饰形容词“好吃”。", "却": "语义：“却”表示转折，句中没有转折语境，“却好吃的”说不通。"}, "sentence_index": 0, "correct_answer": "挺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的房间挺在二楼，窗户朝南。", "explanation": "这里应该用〈就〉，表示位置明确。“挺”不能修饰“在”这类动词。"}, {"text": "我挺吃饭，一天三顿。", "explanation": "这里应该用〈常常〉。“挺”只修饰形容词或心理动词，不能修饰“吃”这类动作。"}, {"text": "这件衣服我穿着不挺合适。", "explanation": "这里应该用〈不太〉。“挺”表示程度高，不能用于否定式“不挺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86400, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挺", "is_correct": true, "explanation": "正确：挺 tǐng，意思是很、相当，程度副词。"}, {"text": "厅", "is_correct": false, "explanation": "tīng（第一声）与 tǐng（第三声）声调不同，意思是厅堂。"}, {"text": "亭", "is_correct": false, "explanation": "tíng（第二声）与 tǐng（第三声）声调不同，意思是亭子。"}, {"text": "领", "is_correct": false, "explanation": "lǐng 与 tǐng 声母不同（l 与 t），意思是领导、领取。"}, {"text": "井", "is_correct": false, "explanation": "jǐng 与 tǐng 声母不同（j 与 t），意思是水井。"}], "explanations": {"挺": "正确：挺 tǐng，意思是很、相当，程度副词。", "厅": "tīng（第一声）与 tǐng（第三声）声调不同，意思是厅堂。", "亭": "tíng（第二声）与 tǐng（第三声）声调不同，意思是亭子。", "领": "lǐng 与 tǐng 声母不同（l 与 t），意思是领导、领取。", "井": "jǐng 与 tǐng 声母不同（j 与 t），意思是水井。"}, "sentence_index": null, "correct_answer": "挺"}, "level_3": {"options": [{"text": "挺", "is_correct": true, "explanation": "正确：“挺高兴”表示相当高兴，与后面的因果句吻合。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不高兴”与“因为考试通过了”的因果语境相反。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”一般与“不”连用，不能直接修饰“高兴”。"}, {"text": "没", "is_correct": false, "explanation": "语义：“没高兴”与“因为考试通过了”的因果关系相反，句意不符。"}], "explanations": {"挺": "正确：“挺高兴”表示相当高兴，与后面的因果句吻合。", "不": "语义：“不高兴”与“因为考试通过了”的因果语境相反。", "并": "搭配：“并”一般与“不”连用，不能直接修饰“高兴”。", "没": "语义：“没高兴”与“因为考试通过了”的因果关系相反，句意不符。"}, "sentence_index": 6, "correct_answer": "挺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店比那家挺便宜，大家都去那里买。", "explanation": "这里应该用〈更〉。比较句中“挺”不能与“比”连用，要说“比那家更便宜”。"}, {"text": "他今天挺到，比大家都晚。", "explanation": "这里应该用〈才〉，表示时间晚。“挺”不能修饰“到”这类动词。"}, {"text": "请你挺说一遍，我没听清楚。", "explanation": "这里应该用〈再〉。“挺”不能修饰“说”这类动作动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气热挺的，我们去游泳吧。", "corrected_sentence": "天气挺热的，我们去游泳吧。", "error_description": "“挺”是副词，要放在形容词前面。“热挺的”语序错误，应说“挺热的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路挺的远，我们坐车去吧。", "corrected_sentence": "这条路挺远的，我们坐车去吧。", "error_description": "“挺”修饰形容词，“的”应放在形容词后。“挺的远”把“的”放错了位置，应说“挺远的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
