INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86405, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中年是不老也不小的人，大约四十到五十岁。", "primary_collocate": null, "pronunciation": "zhōng nián", "ipa": "ʈʂʊŋ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他今年四十五岁，已经是中年了。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位中年男人每天骑车上班。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个中年女人在超市买了很多菜。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位中年工人在路边修车。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有几位中年的叔叔在打球。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个中年的老师对学生很好。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中年的王先生开了一家小饭馆。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一位中年妈妈，每天照顾孩子。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站有一个中年司机在等客人。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位中年医生很有经验，大家都信他。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中年人", "label": "复合"}], "register": "中性", "sense_fingerprint": "四五十岁不老不小的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c5d38-188c-4474-8f42-65925038992f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中年", "is_correct": true, "explanation": "中年：指不老也不小、大约四十到五十岁的人，与“四十五岁”相符。"}, {"text": "青年", "is_correct": false, "explanation": "语义：“青年”指二三十岁的人，与“四十五岁”不符。"}, {"text": "老年", "is_correct": false, "explanation": "语义：“老年”多指六十岁以后，与“四十五岁”矛盾。"}, {"text": "老头", "is_correct": false, "explanation": "语域：“老头”是口语、带贬义的说法，不用来客观陈述年龄；而且与“四十五岁”也对不上。"}], "explanations": {"中年": "中年：指不老也不小、大约四十到五十岁的人，与“四十五岁”相符。", "青年": "语义：“青年”指二三十岁的人，与“四十五岁”不符。", "老年": "语义：“老年”多指六十岁以后，与“四十五岁”矛盾。", "老头": "语域：“老头”是口语、带贬义的说法，不用来客观陈述年龄；而且与“四十五岁”也对不上。"}, "sentence_index": 0, "correct_answer": "中年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台中年电脑最近运行得很慢。", "explanation": "这里应该用〈旧〉。中年只指人的年龄阶段，不能用来形容电脑。"}, {"text": "他刚进大学，是一位朝气蓬勃的中年人。", "explanation": "这里应该用〈青年〉。中年指四十到五十岁左右的人，刚进大学的学生应说青年。"}, {"text": "这个中年的孩子只有五岁。", "explanation": "这里应该用〈年幼〉。中年只指成年人的年龄阶段，不能用来形容五岁的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中年", "is_correct": true, "explanation": "中年：修饰“王先生”，说明他是四十到五十岁左右的成年人，与“王先生”的称呼相符。"}, {"text": "少年", "is_correct": false, "explanation": "语义：“少年”指十几岁的未成年人，与“王先生”这一对成年人的尊称矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”指刚出生不久的孩子，不可能开饭馆，也不配“先生”的称呼。"}, {"text": "儿童", "is_correct": false, "explanation": "语义：“儿童”是小孩子，不可能开饭馆，也不配“先生”的称呼。"}], "explanations": {"中年": "中年：修饰“王先生”，说明他是四十到五十岁左右的成年人，与“王先生”的称呼相符。", "少年": "语义：“少年”指十几岁的未成年人，与“王先生”这一对成年人的尊称矛盾。", "婴儿": "语义：“婴儿”指刚出生不久的孩子，不可能开饭馆，也不配“先生”的称呼。", "儿童": "语义：“儿童”是小孩子，不可能开饭馆，也不配“先生”的称呼。"}, "sentence_index": 6, "correct_answer": "中年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的运动会定在中年举行。", "explanation": "这里应该用〈年中〉。中年指人的年龄阶段，不表示一年的中间时段。"}, {"text": "他的手上长了一块中年斑。", "explanation": "这里应该用〈老年〉。“老年斑”是固定说法，中年不能替换。"}, {"text": "我们周末去中年宫学画画。", "explanation": "这里应该用〈少年〉。“少年宫”是固定名称，中年不能替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位中年了妈妈在超市工作，每天都很忙。", "corrected_sentence": "这位中年妈妈在超市工作，每天都很忙。", "error_description": "错误：“中年了妈妈”，多了“了”。正确：“中年妈妈”。“中年”作定语修饰“妈妈”时，“了”不能插在定语和中心词之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位中年在公园里教孩子下棋。", "corrected_sentence": "那位中年人在公园里教孩子下棋。", "error_description": "错误：“那位中年”。正确：“那位中年人”。“中年”指年龄阶段，指人时要说“中年人”，不能省略“人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
