INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指四十岁到六十岁左右的年龄阶段。", "primary_collocate": null, "pronunciation": "zhōng nián", "ipa": "ʈʂʊŋ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "人到中年，工作和家里的事都很多。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他中年的时候搬到了上海。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中年是人生中很忙的一段时间。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在中年开始学画画。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的中年过得很辛苦。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入中年以后，他每天都去跑步。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人到了中年才明白健康很重要。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的少年和中年都在农村度过。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中年时他换了工作，生活也变了。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人在中年要多注意身体。", "target_word": "中年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中年人", "label": "复合"}], "register": "中性", "sense_fingerprint": "四十到六十岁的人生阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c5d38-188c-4474-8f42-65925038992f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中年", "is_correct": true, "explanation": "中年：指四十到六十岁左右的年龄阶段，与“工作和家里的事都很多”的句意相符。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“人到”后一般接“中年、晚年”这类成年阶段，不说“人到童年”。"}, {"text": "晚年", "is_correct": false, "explanation": "语义：“晚年”多指退休之后的时期，与“工作和家里的事都很多”矛盾。"}, {"text": "少年", "is_correct": false, "explanation": "语义：“少年”是未成年的阶段，没有工作和家务，与句意矛盾。"}], "explanations": {"中年": "中年：指四十到六十岁左右的年龄阶段，与“工作和家里的事都很多”的句意相符。", "童年": "搭配：“人到”后一般接“中年、晚年”这类成年阶段，不说“人到童年”。", "晚年": "语义：“晚年”多指退休之后的时期，与“工作和家里的事都很多”矛盾。", "少年": "语义：“少年”是未成年的阶段，没有工作和家务，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "中年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他才五岁，就已经步入中年了。", "explanation": "这里应该用〈童年〉。中年指四十到六十岁左右的年龄阶段，五岁的孩子应说童年。"}, {"text": "这次培训定在中年进行。", "explanation": "这里应该用〈年中〉。中年指人的一个年龄阶段，不表示一年的中间时段。"}, {"text": "这场比赛的中年很精彩。", "explanation": "这里应该用〈中场〉。中年指人的年龄阶段，比赛的中间时段要说中场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中年", "is_correct": true, "explanation": "中年：指四十到六十岁左右的阶段，符合“才明白健康很重要”的句意。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“到了”后面一般接“中年、晚年”这类成年阶段，“童年”不这样用。"}, {"text": "幼年", "is_correct": false, "explanation": "语义：“幼年”的人还不会理解健康的重要，与“才明白”的句意不符。"}, {"text": "婴儿期", "is_correct": false, "explanation": "语义：“婴儿期”的人还无法明白这些道理，句意不通。"}], "explanations": {"中年": "中年：指四十到六十岁左右的阶段，符合“才明白健康很重要”的句意。", "童年": "搭配：“到了”后面一般接“中年、晚年”这类成年阶段，“童年”不这样用。", "幼年": "语义：“幼年”的人还不会理解健康的重要，与“才明白”的句意不符。", "婴儿期": "语义：“婴儿期”的人还无法明白这些道理，句意不通。"}, "sentence_index": 6, "correct_answer": "中年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她刚大学毕业，正处于中年时期。", "explanation": "这里应该用〈青年〉。中年指四十到六十岁左右的年龄阶段，刚大学毕业的人应说青年。"}, {"text": "他买了一张中年票去公园。", "explanation": "这里应该用〈老年〉。“老年票”是固定说法，中年不能替换。"}, {"text": "他每天都去中年宫学画画。", "explanation": "这里应该用〈少年〉。“少年宫”是固定名称，中年不能替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他中年的以后开始注意锻炼身体。", "corrected_sentence": "他中年以后开始注意锻炼身体。", "error_description": "错误：“中年的以后”，多了“的”。正确：“中年以后”。表示时间的“中年以后”之间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人中年，身体就会慢慢变差。", "corrected_sentence": "人到中年，身体就会慢慢变差。", "error_description": "错误：“人中年”，漏掉了“到”。正确：“人到中年”。“到”是动词，表示人进入某个年龄阶段，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
