INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气助词，是“了”和“啊”的合音，用在句末，表示感叹或变化。", "primary_collocate": null, "pronunciation": "la", "ipa": "la", "syllable_count": 1, "sentences": [{"text": "下雨啦，快回家吧！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到家啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子都长这么高啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来啦，花都开了。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经走啦。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好啦，快来吃！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑啦，我们回去吧。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你终于来啦！", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束啦，大家可以玩了。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃饱啦，谢谢你。", "target_word": "啦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "了+啊合音；句末表感叹或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9a6dfb6-2ee6-453e-a7c2-961fd8e3fc9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动，不是句末语气词。"}, {"text": "辣", "is_correct": false, "explanation": "辣（là，第四声）与啦（la，轻声）声调不同，意思是辣味。"}, {"text": "喇", "is_correct": false, "explanation": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。"}, {"text": "蜡", "is_correct": false, "explanation": "蜡（là，第四声）与啦（la，轻声）声调不同，意思是蜡烛。"}], "explanations": {"啦": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。", "拉": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动，不是句末语气词。", "辣": "辣（là，第四声）与啦（la，轻声）声调不同，意思是辣味。", "喇": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。", "蜡": "蜡（là，第四声）与啦（la，轻声）声调不同，意思是蜡烛。"}, "sentence_index": null, "correct_answer": "啦"}, "level_3": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确。“啦”表示雨已经下起来了这一变化，并带有提醒、感叹的语气。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”用于是非问句，句末要用问号；“下雨吗，快回家吧”把陈述变成疑问，与催促的语气不合。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”是动态助词，须接在动词后表持续，不作句末语气词，“下雨着”不成句。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”不作句末语气词，“下雨的”不能独立成句，句子不通。"}], "explanations": {"啦": "正确。“啦”表示雨已经下起来了这一变化，并带有提醒、感叹的语气。", "吗": "语义：“吗”用于是非问句，句末要用问号；“下雨吗，快回家吧”把陈述变成疑问，与催促的语气不合。", "着": "语法：“着”是动态助词，须接在动词后表持续，不作句末语气词，“下雨着”不成句。", "的": "语法：“的”不作句末语气词，“下雨的”不能独立成句，句子不通。"}, "sentence_index": 0, "correct_answer": "啦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小到大一直很瘦，现在还是那么瘦啦。", "explanation": "这里不该用〈啦〉。“啦”表示出现了新的变化，而句子强调状态一直没有改变，两者矛盾。"}, {"text": "会议于今天下午召开啦。", "explanation": "这里不该用〈啦〉。“啦”是口语语气词，书面的会议通知里要写“召开了”，不用语气词“啦”。"}, {"text": "本合同自双方签字之日起生效啦。", "explanation": "这里不该用〈啦〉。“啦”是口语语气词，表示感叹或新变化，正式的合同条款不能用语气词“啦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动。"}, {"text": "腊", "is_correct": false, "explanation": "腊（là，第四声）与啦（la，轻声）声调不同，意思是腊月。"}, {"text": "喇", "is_correct": false, "explanation": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。"}, {"text": "浪", "is_correct": false, "explanation": "浪（làng）比啦（la）多一个韵尾 ng，意思是波浪。"}, {"text": "懒", "is_correct": false, "explanation": "懒（lǎn）比啦（la）多一个韵尾 n，意思是懒惰。"}], "explanations": {"啦": "正确答案。“啦”是“了”和“啊”的合音，句末读轻声 la。", "拉": "拉（lā，第一声）与啦（la，轻声）声调不同，意思是拉动。", "腊": "腊（là，第四声）与啦（la，轻声）声调不同，意思是腊月。", "喇": "喇（lǎ，第三声）与啦（la，轻声）声调不同，常见于“喇叭”一词。", "浪": "浪（làng）比啦（la）多一个韵尾 ng，意思是波浪。", "懒": "懒（lǎn）比啦（la）多一个韵尾 n，意思是懒惰。"}, "sentence_index": null, "correct_answer": "啦"}, "level_3": {"options": [{"text": "啦", "is_correct": true, "explanation": "正确。“啦”表示天色已经变黑，这种变化正是“啦”的典型用法。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言语气词，与口语的“我们回去吧”风格不协调。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言感叹助词，口语中不用，与句子的语体不合。"}, {"text": "的", "is_correct": false, "explanation": "语法：“天黑的”不能独立成句，“的”在这里不起语气词的作用，句子不通。"}], "explanations": {"啦": "正确。“啦”表示天色已经变黑，这种变化正是“啦”的典型用法。", "矣": "语域：“矣”是文言语气词，与口语的“我们回去吧”风格不协调。", "哉": "语域：“哉”是文言感叹助词，口语中不用，与句子的语体不合。", "的": "语法：“天黑的”不能独立成句，“的”在这里不起语气词的作用，句子不通。"}, "sentence_index": 6, "correct_answer": "啦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都吃饱啦。", "explanation": "这里不该用〈啦〉。“啦”表示刚出现的一次性变化，“每天”说的是习惯，不是新变化。"}, {"text": "这份报告包含了三个章节啦。", "explanation": "这里误把〈啦〉用在平铺直叙的数量陈述上。〈啦〉只表示感叹或新出现的变化，单纯说明章节数量并没有这些意味，不能用〈啦〉。"}, {"text": "依据本法第三条之规定，特此公告啦。", "explanation": "这里不该用〈啦〉。“啦”是口语语气词，正式的法律公告中不能使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪啦停，我们出去玩吧。", "corrected_sentence": "雪停啦，我们出去玩吧。", "error_description": "错误形式：“雪啦停”。语气词“啦”只能放在句末，不能插在主语和动词之间；正确形式是“雪停啦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我吃饱吗啦，谢谢大家。", "corrected_sentence": "我吃饱啦，谢谢大家。", "error_description": "错误形式：“吗啦”。“吗”是疑问语气词，陈述句中不能与“啦”叠用；正确形式是“吃饱啦”，句末只用“啦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7292f83-ee8b-4714-9e12-f9778fc8df9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
