INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "演员是在电影或舞台上扮演别人的人。", "primary_collocate": null, "pronunciation": "yǎn yuán", "ipa": "jæn˨˩˦ ɥæn˧˥", "syllable_count": 2, "sentences": [{"text": "我姐姐是舞台上的演员。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个演员在电影里演医生。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员的电影我看过很多。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员穿着红衣服站在台上。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员很高，说话也很好听。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们明天要去学校演出。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好演员要会哭，也要会笑。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是演员，是写故事的人。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员在后面换衣服，马上就出来。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿长大后想做演员。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "男演员", "label": "复合"}, {"form": "女演员", "label": "复合"}, {"form": "演員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电影或舞台上扮演别人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b99fe0-ca51-4411-a7d6-da75aa0fad5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的织物，不是人，不能说“我姐姐是……地毯”。"}, {"text": "演员", "is_correct": true, "explanation": "正确：“演员”指在舞台上扮演角色的人，与“我姐姐是舞台上的”相符。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：灯光是光线，不是人，不能用来说明“我姐姐”的身份。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“是……的”后接指人名词才合理，“钢琴”不能用来说明“我姐姐”的身份。"}], "explanations": {"地毯": "语义：地毯是铺在地上的织物，不是人，不能说“我姐姐是……地毯”。", "演员": "正确：“演员”指在舞台上扮演角色的人，与“我姐姐是舞台上的”相符。", "灯光": "语义：灯光是光线，不是人，不能用来说明“我姐姐”的身份。", "钢琴": "搭配：“是……的”后接指人名词才合理，“钢琴”不能用来说明“我姐姐”的身份。"}, "sentence_index": 0, "correct_answer": "演员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把演员很高，说话也很好听。", "explanation": "这里应该用〈位〉。“把”用于有柄的东西，如椅子、刀；指人要用“位”或“名”。"}, {"text": "他是一名演员，每天在医院给病人看病。", "explanation": "这里应该用〈医生〉。给病人看病的是医生，演员是在电影或舞台上扮演别人的人。"}, {"text": "这本书的演员是一位老人。", "explanation": "这里应该用〈作者〉。写书的人是作者，演员是在电影或舞台上扮演角色的人，不写书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有感情，不会哭也不会笑，“要会哭”说不通。"}, {"text": "演员", "is_correct": true, "explanation": "正确：“演员”需要表演情绪，要会哭会笑，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有面部表情，不能做出哭和笑的样子。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能哭也不能笑，与“要会哭”相矛盾。"}], "explanations": {"椅子": "语义：椅子没有感情，不会哭也不会笑，“要会哭”说不通。", "演员": "正确：“演员”需要表演情绪，要会哭会笑，与句意相符。", "石头": "体貌：石头没有面部表情，不能做出哭和笑的样子。", "桌子": "语义：桌子是家具，不能哭也不能笑，与“要会哭”相矛盾。"}, "sentence_index": 6, "correct_answer": "演员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位演员每天在实验室研究新药。", "explanation": "这里应该用〈科学家〉。在实验室研究新药的是科学家，演员是在电影或舞台上扮演别人的人。"}, {"text": "这位演员在比赛中吹哨判罚，很公平。", "explanation": "这里应该用〈裁判〉。在比赛中吹哨判罚的是裁判，演员是在电影或舞台上扮演别人的人。"}, {"text": "演员用镜头拍出了很美的画面。", "explanation": "这里应该用〈摄影师〉。用镜头拍画面的是摄影师，演员不负责拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多演员们在后台化妆。", "corrected_sentence": "很多演员在后台化妆。", "error_description": "“们”不能与“很多”等数量词连用，应说“很多演员”，不说“很多演员们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候想当了演员，后来做了老师。", "corrected_sentence": "他小时候想当演员，后来做了老师。", "error_description": "时态错误：“想”表示希望，动作尚未发生，“当”后不能加“了”，应说“想当演员”，不说“想当了演员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
