INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在戏剧、电影等中扮演角色的人。", "primary_collocate": null, "pronunciation": "yǎn yuán", "ipa": "jæn˨˩˦ ɥæn˧˥", "syllable_count": 2, "sentences": [{"text": "她是一位有名的演员。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个演员把老人演得很像。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们在台上练习了一个下午。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当演员。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位演员今年拍了三部电影。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员要记住很多话。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的演员都很年轻。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很喜欢那个演员的声音。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员在舞台上哭了，很多人也哭了。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了二十年演员，演过很多角色。", "target_word": "演员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "男演员", "label": "复合"}, {"form": "女演员", "label": "复合"}, {"form": "演員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戏剧电影中扮演角色的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b99fe0-ca51-4411-a7d6-da75aa0fad5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "影院", "is_correct": false, "explanation": "语义：影院是场所，不是人，“她是一位有名的影院”不成立。"}, {"text": "演员", "is_correct": true, "explanation": "正确：“演员”指扮演角色的人，可以用“一位”修饰，“她是一位有名的演员”句意通顺。"}, {"text": "字幕", "is_correct": false, "explanation": "语义：字幕是屏幕上的文字，不是人，“她是……字幕”说不通。"}, {"text": "相机", "is_correct": false, "explanation": "语义：相机是拍摄工具，不能指人，“她是一位……相机”不成立。"}], "explanations": {"影院": "语义：影院是场所，不是人，“她是一位有名的影院”不成立。", "演员": "正确：“演员”指扮演角色的人，可以用“一位”修饰，“她是一位有名的演员”句意通顺。", "字幕": "语义：字幕是屏幕上的文字，不是人，“她是……字幕”说不通。", "相机": "语义：相机是拍摄工具，不能指人，“她是一位……相机”不成立。"}, "sentence_index": 0, "correct_answer": "演员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一条有名的演员。", "explanation": "这里应该用〈位〉。演员指人，量词用“位”；“条”用于细长的东西。"}, {"text": "这部电影的演员决定了每个镜头怎么拍。", "explanation": "这里应该用〈导演〉。决定拍摄方式的是导演，演员只负责扮演角色。"}, {"text": "这位演员负责设计桥梁，每天都去工地。", "explanation": "这里应该用〈工程师〉。设计桥梁、天天去工地的是工程师，演员是在戏剧或电影中扮演角色的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜头", "is_correct": false, "explanation": "语义：镜头不是人，不能说“都很年轻”。"}, {"text": "演员", "is_correct": true, "explanation": "正确：“演员”是人，可以说“都很年轻”，与句意相符。"}, {"text": "剧本", "is_correct": false, "explanation": "语义：剧本是文字作品，没有年龄，不能说“都很年轻”。"}, {"text": "片名", "is_correct": false, "explanation": "体貌：“年轻”形容人的外貌，片名没有外貌，不能说“都很年轻”。"}], "explanations": {"镜头": "语义：镜头不是人，不能说“都很年轻”。", "演员": "正确：“演员”是人，可以说“都很年轻”，与句意相符。", "剧本": "语义：剧本是文字作品，没有年龄，不能说“都很年轻”。", "片名": "体貌：“年轻”形容人的外貌，片名没有外貌，不能说“都很年轻”。"}, "sentence_index": 6, "correct_answer": "演员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的演员写了三年剧本。", "explanation": "这里应该用〈编剧〉。写剧本的是编剧，演员的工作是扮演角色，不写剧本。"}, {"text": "演员把这一段风景拍得很美。", "explanation": "这里应该用〈摄影师〉。拍摄画面、把风景拍美的是摄影师，演员不负责拍摄。"}, {"text": "这位演员每天负责给医院采购药品。", "explanation": "这里应该用〈采购员〉。给医院采购药品的是采购员，演员是在戏剧或电影中扮演角色的人，不负责采购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多演员们在台上等着上场。", "corrected_sentence": "很多演员在台上等着上场。", "error_description": "“们”不能与“很多”等数量词连用，应说“很多演员”，不说“很多演员们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当了十年个演员，拍过很多电影。", "corrected_sentence": "她当了十年演员，拍过很多电影。", "error_description": "量词错误：“个”不能插在“十年”和“演员”之间，应说“当了十年演员”，不说“当了十年个演员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
