INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86413, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“年中”是一年的中间，大约是六月。", "primary_collocate": null, "pronunciation": "nián zhōng", "ipa": "nʲɛn˧˥ ʈʂʊŋ˥˥", "syllable_count": 2, "sentences": [{"text": "公司在年中和年底各开一次会。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年中的天气已经很热了。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算年中的时候去旅行。", "target_word": "年中", "complexity_tier": "T3", "furigana": "wǒmen dǎsuàn niánzhōng de shíhou qù lǚxíng", "sentence_source": "generated"}, {"text": "他的工作到了年中就最忙。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年中我常常去海边玩。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店年中有大减价。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年年中，我搬了新家。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了年中，学校就放假了。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年中的时候，我换了工作。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年年中给大家发奖金。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一年的中间，约六月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是时间，不能作“在……和年底各开一次会”的时间成分。"}, {"text": "年中", "is_correct": true, "explanation": "「年中」指一年的中间，与“年底”并列，符合“在年中和年底各开一次会”的语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」不表示时间，与“各开一次会”的安排不相符。"}, {"text": "会议", "is_correct": false, "explanation": "语义：「会议」指集会本身，不表示时间，不能充当“在……和年底各开一次会”中的时间成分。"}], "explanations": {"天气": "语义：「天气」不是时间，不能作“在……和年底各开一次会”的时间成分。", "年中": "「年中」指一年的中间，与“年底”并列，符合“在年中和年底各开一次会”的语境。", "价格": "语义：「价格」不表示时间，与“各开一次会”的安排不相符。", "会议": "语义：「会议」指集会本身，不表示时间，不能充当“在……和年底各开一次会”中的时间成分。"}, "sentence_index": 0, "correct_answer": "年中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在年中过春节。", "explanation": "这里应该用〈年初〉。春节在一年开头，年中约六月，不能说在年中过春节。"}, {"text": "学校在年中放寒假。", "explanation": "这里应该用〈年初〉。寒假在一年开头的冬季，年中约六月，是夏天，不能说在年中放寒假。"}, {"text": "大家在年中忙着买年货。", "explanation": "这里应该用〈岁末〉。年货是在岁末采购的，年中不能说买年货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：「体重」不是时间，不能放在“今年”之后作时间状语。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」不表示时间，与“今年……我搬了新家”的时间框架不符。"}, {"text": "年中", "is_correct": true, "explanation": "「年中」指一年的中间，与“今年”搭配表示时间，符合“今年年中，我搬了新家”的语境。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：「今年」后接的应是时间名词，“人口”不能作时间成分。"}], "explanations": {"体重": "语义：「体重」不是时间，不能放在“今年”之后作时间状语。", "价格": "语义：「价格」不表示时间，与“今年……我搬了新家”的时间框架不符。", "年中": "「年中」指一年的中间，与“今年”搭配表示时间，符合“今年年中，我搬了新家”的语境。", "人口": "搭配：「今年」后接的应是时间名词，“人口”不能作时间成分。"}, "sentence_index": 6, "correct_answer": "年中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年中的他已经很有经验了。", "explanation": "这里应该用〈中年〉。年中是一年的中间，形容人的年纪要用中年，不能用年中。"}, {"text": "我每天年中起床。", "explanation": "这里应该用〈早上〉。年中是一年的中间，不能表示每天的时间，每天起床的时间要用早上。"}, {"text": "这个例会在每周的年中举行。", "explanation": "这里应该用〈周中〉。年中指一年的中间，指一周中间要用周中，年中不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年中时候，我们开了一次总结会。", "corrected_sentence": "年中的时候，我们开了一次总结会。", "error_description": "助词缺失：“年中”作定语修饰“时候”时需要“的”。错误形式“年中时候”，正确形式“年中的时候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年年中的都开一次总结会。", "corrected_sentence": "我们每年年中都开一次总结会。", "error_description": "“的”多余：“年中”作状语修饰“都开”时不能加“的”，“的”只用于修饰名词。错误形式“年中的都开”，正确形式“年中都开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
