INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指一年的中间时期，或一年之内。", "primary_collocate": null, "pronunciation": "nián zhōng", "ipa": "nʲɛn˧˥ ʈʂʊŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这家商店年中那段时间生意最好。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年中的大部分时间在国外。", "target_word": "年中", "complexity_tier": "T3", "furigana": "tā niánzhōng de dà bùfen shíjiān zài guówài", "sentence_source": "generated"}, {"text": "年中那几个月，我特别忙。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年年中，公司换了新老板。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在年中得了一次奖。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年中的时候，我们学校有两次考试。", "target_word": "年中", "complexity_tier": "T3", "furigana": "niánzhōng de shíhou, wǒmen xuéxiào yǒu liǎng cì kǎoshì", "sentence_source": "generated"}, {"text": "年中放假的时候，我回了老家。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店年中的客人特别多。", "target_word": "年中", "complexity_tier": "T3", "furigana": "zhè jiā fàndiàn niánzhōng de kèrén tèbié duō", "sentence_source": "generated"}, {"text": "年中的生意比年底好。", "target_word": "年中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在年中的一个周末，他突然来了。", "target_word": "年中", "complexity_tier": "T3", "furigana": "zài niánzhōng de yí ge zhōumò, tā tūrán lái le", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一年中间的时期，或一年之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：「价格」不表示一段时间，与“那段时间”的所指矛盾。"}, {"text": "年中", "is_correct": true, "explanation": "「年中」指一年中间的时期，与“那段时间”搭配，符合“商店那段时间生意最好”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是时间段，不能与“那段时间”指代同一时期。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：「手机」不表示时间，也不能与“那段时间”构成时间状语。"}], "explanations": {"价格": "语义：「价格」不表示一段时间，与“那段时间”的所指矛盾。", "年中": "「年中」指一年中间的时期，与“那段时间”搭配，符合“商店那段时间生意最好”的语境。", "天气": "语义：「天气」不是时间段，不能与“那段时间”指代同一时期。", "手机": "搭配：「手机」不表示时间，也不能与“那段时间”构成时间状语。"}, "sentence_index": 0, "correct_answer": "年中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在年中过春节。", "explanation": "这里应该用〈年初〉。春节在一年开头，年中约六月，不能说在年中过春节。"}, {"text": "老师在年中布置寒假作业。", "explanation": "这里应该用〈年底〉。寒假作业在年底布置，年中是夏天，不能这样说。"}, {"text": "家家在年中准备年夜饭。", "explanation": "这里应该用〈岁末〉。年夜饭是在岁末准备的，年中不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭菜", "is_correct": false, "explanation": "语义：「饭菜」不是时间，不能作“放假的时候”的修饰语，句意不通。"}, {"text": "年中", "is_correct": true, "explanation": "「年中」指一年的中间，作“放假的时候”的修饰语，符合“我回了老家”的语境。"}, {"text": "工资", "is_correct": false, "explanation": "语义：「工资」不能放假，与“放假的时候”的语义不相符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「放假」的主语应是人或单位，“窗户”不能用于“放假”。"}], "explanations": {"饭菜": "语义：「饭菜」不是时间，不能作“放假的时候”的修饰语，句意不通。", "年中": "「年中」指一年的中间，作“放假的时候”的修饰语，符合“我回了老家”的语境。", "工资": "语义：「工资」不能放假，与“放假的时候”的语义不相符。", "窗户": "搭配：「放假」的主语应是人或单位，“窗户”不能用于“放假”。"}, "sentence_index": 6, "correct_answer": "年中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "年中的他已经很有经验了。", "explanation": "这里应该用〈中年〉。年中是一年的中间，形容人的年纪要用中年，不能用年中。"}, {"text": "我每天年中起床。", "explanation": "这里应该用〈早上〉。年中是一年的中间，不能表示每天的时间，每天起床的时间要用早上。"}, {"text": "这个例会在每周的年中举行。", "explanation": "这里应该用〈周中〉。年中指一年的中间，指一周中间要用周中，年中不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年中时候，他去了一次北京。", "corrected_sentence": "年中的时候，他去了一次北京。", "error_description": "助词缺失：“年中”修饰“时候”时需要“的”。错误形式“年中时候”，正确形式“年中的时候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年中了那段时间，我们很忙。", "corrected_sentence": "年中那段时间，我们很忙。", "error_description": "助词误加：名词“年中”后不能加“了”。错误形式“年中了那段时间”，正确形式“年中那段时间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
