INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中间；其中。", "primary_collocate": null, "pronunciation": "dāng zhōng", "ipa": "taŋ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这些书当中，我最喜欢这一本。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们当中，小王的汉语最好。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友当中有两个是老师。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果当中，苹果最便宜。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这么多人当中，只有他会说法语。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个孩子当中，老二最爱笑。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的人当中，一半是女的。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几家饭馆当中，哪一家最近？", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好几个问题当中，这个最难。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画当中，我最爱这一幅。", "target_word": "当中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "当中：在一群人或事物之中，指其中的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '749151d6-7ed4-4f35-af8d-c2dbfaf13d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当中", "is_correct": true, "explanation": "当中：表示在这几本书之中挑选，与“我最喜欢这一本”的说法相符。"}, {"text": "上面", "is_correct": false, "explanation": "语义：“上面”指位置在高处，“这些书上面”与在一组书中挑选最喜欢的意思不符。"}, {"text": "对面", "is_correct": false, "explanation": "搭配：“对面”指隔着相对的一方，不能用于一堆书之中的挑选。"}, {"text": "外面", "is_correct": false, "explanation": "语义：“外面”指范围之外，与“这些书当中”所限定的范围相矛盾。"}], "explanations": {"当中": "当中：表示在这几本书之中挑选，与“我最喜欢这一本”的说法相符。", "上面": "语义：“上面”指位置在高处，“这些书上面”与在一组书中挑选最喜欢的意思不符。", "对面": "搭配：“对面”指隔着相对的一方，不能用于一堆书之中的挑选。", "外面": "语义：“外面”指范围之外，与“这些书当中”所限定的范围相矛盾。"}, "sentence_index": 0, "correct_answer": "当中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个苹果当中最便宜。", "explanation": "这里应该删去〈当中〉：“这个苹果最便宜”即可。“当中”需要一群事物可供挑选，只有一个对象时不能用。"}, {"text": "他的心当中很难受。", "explanation": "这里应该用〈心里〉。当中表示空间或范围的内部，不能用来说身体或心理感受。"}, {"text": "我的座位在他当中。", "explanation": "这里应该用〈旁边〉。当中指在一群人或事物之内，不能用来指紧挨着某个人的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当中", "is_correct": true, "explanation": "当中：表示在公司的人之中，与“一半是女的”的整体统计相符。"}, {"text": "底下", "is_correct": false, "explanation": "语义：“底下”指在下方，与“公司的人”这种人群的说法不符。"}, {"text": "之上", "is_correct": false, "explanation": "语义：“之上”指位置在高处，“公司的人之上”与“一半是女的”的统计说法不搭。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：“之间”多用于两方或两者之间，不能用于“公司的人之间”这种对整体人群的统计。"}], "explanations": {"当中": "当中：表示在公司的人之中，与“一半是女的”的整体统计相符。", "底下": "语义：“底下”指在下方，与“公司的人”这种人群的说法不符。", "之上": "语义：“之上”指位置在高处，“公司的人之上”与“一半是女的”的统计说法不搭。", "之间": "搭配：“之间”多用于两方或两者之间，不能用于“公司的人之间”这种对整体人群的统计。"}, "sentence_index": 6, "correct_answer": "当中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十点当中他来了。", "explanation": "这里应该用〈整〉。当中表示范围内部，不能用来指一个具体的时间点。"}, {"text": "这个人当中很高。", "explanation": "这里应该删去〈当中〉：“这个人很高”即可。当中要求有一群人或事物，只有一个人时不能用。"}, {"text": "这幅画当中很好看。", "explanation": "这里应该用〈本身〉。“当中”需要一群事物可供比较，只指一幅画时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几种鸟的当中，燕子最常见。", "corrected_sentence": "这几种鸟当中，燕子最常见。", "error_description": "错误形式：“鸟的当中”；正确形式：“鸟当中”。“当中”是方位词，前面的名词后直接接“当中”，不能再加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里的同学很当中，小王最努力。", "corrected_sentence": "班里的同学当中，小王最努力。", "error_description": "错误形式：“很当中”；正确形式：“当中”。“很”不能修饰方位词“当中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004070df-06ea-4322-b76d-56c06d8a92e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
