INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86419, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "秒是很短很短的时间，比一分钟还短。", "primary_collocate": null, "pronunciation": "miǎo", "ipa": "mjɑʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "等我一秒，我马上来。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他只看了一秒就笑了。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯亮了几秒又灭了。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红灯还有五秒。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这一秒我什么也没想。", "target_word": "秒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她想了三秒才回答。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了十秒，门还没开。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要一秒，你就能看清楚。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子安静了几秒。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人停了两秒，又往前走。", "target_word": "秒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "秒钟", "label": "复合"}, {"form": "毫秒", "label": "复合"}], "register": "中性", "sense_fingerprint": "秒：很短很短的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86419, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "秒", "is_correct": true, "explanation": "秒是很短的时间，“等我一秒”与“马上来”相符，符合句意。"}, {"text": "根", "is_correct": false, "explanation": "搭配：根计量细长的东西，不能计量时间，“等我一根”说不通。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”计量动作的次数，不能用来计量时间段，“等我一次”说不通。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”不能计量时间，“等我一个”不成句。"}], "explanations": {"秒": "秒是很短的时间，“等我一秒”与“马上来”相符，符合句意。", "根": "搭配：根计量细长的东西，不能计量时间，“等我一根”说不通。", "次": "搭配：“次”计量动作的次数，不能用来计量时间段，“等我一次”说不通。", "个": "搭配：“个”不能计量时间，“等我一个”不成句。"}, "sentence_index": 0, "correct_answer": "秒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他得了九十秒。", "explanation": "这里应该用〈分〉。考试得分用“分”，〈秒〉是时间单位，不能表示分数。"}, {"text": "他今年才十秒。", "explanation": "这里应该用〈岁〉。年龄用“岁”，〈秒〉是时间单位，不能用来表示年龄。"}, {"text": "今天的温度是三十秒。", "explanation": "这里应该用〈度〉。气温用“度”，〈秒〉不能表示温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86419, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秒", "is_correct": true, "explanation": "秒是很短的时间，“过了十秒”后门还没开，符合句意。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”计量书册，不能用来计量时间，“过了十本”说不通。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”计量纸张、桌子等，不能计量时间。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”计量有柄的东西，如椅子、伞，不能计量时间。"}], "explanations": {"秒": "秒是很短的时间，“过了十秒”后门还没开，符合句意。", "本": "搭配：“本”计量书册，不能用来计量时间，“过了十本”说不通。", "张": "搭配：“张”计量纸张、桌子等，不能计量时间。", "把": "语义：“把”计量有柄的东西，如椅子、伞，不能计量时间。"}, "sentence_index": 6, "correct_answer": "秒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服卖了五秒。", "explanation": "这里应该用〈元〉。价钱用“元”，〈秒〉不能表示价钱。"}, {"text": "这条路长五秒。", "explanation": "这里应该用〈米〉。长度用“米”，〈秒〉不能表示长度。"}, {"text": "这袋米重十秒。", "explanation": "这里应该用〈斤〉。重量用“斤”，〈秒〉不能表示重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86419, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红灯还有几次秒就变绿了。", "corrected_sentence": "红灯还有几秒就变绿了。", "error_description": "量词错误：“次”计量动作的次数，不能用于时间单位；应为“几秒”，“几次秒”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86419, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只用了一次秒就找到了钥匙。", "corrected_sentence": "他只用了一秒就找到了钥匙。", "error_description": "量词错误：“次”计量动作，不能用于时间单位；应为“一秒”，“一次秒”不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
