INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“版”指书刊的印刷次数，即书印了第几次。", "primary_collocate": null, "pronunciation": "bǎn", "ipa": "pan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这本书已经出到第五版了。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买的是第二版，不是第一版。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典的第三版有很多新词。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说一共印了三版，卖得很好。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一版里有一个错字，第二版改过来了。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你手里的是哪一版？", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社说下个月印第四版。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本教材的第四版比第三版便宜。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢收藏第一版的老书。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书第六版多了两章。", "target_word": "版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "版本", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，书的版次，印了第几次，常说“第几版”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 这本 (Zipf 3.99), 词典 (Zipf 3.99), 新词 (Zipf 3.2)']::text[], 'bfe20271-9b49-478a-a8e6-68fb9be44438') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86421, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指书的印刷次数，读 bǎn（第三声）。"}, {"text": "办", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理。"}, {"text": "半", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。"}, {"text": "伴", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是陪伴。"}, {"text": "满", "is_correct": false, "explanation": "mǎn 与 bǎn 声母不同（m 与 b），意思是满的、充满。"}], "explanations": {"版": "正确：版指书的印刷次数，读 bǎn（第三声）。", "办": "bàn（第四声）与 bǎn（第三声）声调不同，意思是办理。", "半": "bàn（第四声）与 bǎn（第三声）声调不同，意思是一半。", "伴": "bàn（第四声）与 bǎn（第三声）声调不同，意思是陪伴。", "满": "mǎn 与 bǎn 声母不同（m 与 b），意思是满的、充满。"}, "sentence_index": null, "correct_answer": "版"}, "level_3": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指书的版次，“第五版”即印了第五次。"}, {"text": "页", "is_correct": false, "explanation": "语义：页指书的一张纸，不指版次，“第五页”不是印刷次数。"}, {"text": "届", "is_correct": false, "explanation": "量词：届用于比赛或届别等，不用于书的印刷次数，“出到第五届”读不通。"}, {"text": "季", "is_correct": false, "explanation": "搭配：季用于电视剧或季节，不能和“出到第五”连用来指书的版次。"}], "explanations": {"版": "正确：版指书的版次，“第五版”即印了第五次。", "页": "语义：页指书的一张纸，不指版次，“第五页”不是印刷次数。", "届": "量词：届用于比赛或届别等，不用于书的印刷次数，“出到第五届”读不通。", "季": "搭配：季用于电视剧或季节，不能和“出到第五”连用来指书的版次。"}, "sentence_index": 0, "correct_answer": "版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电视剧一共有三十版。", "explanation": "这里应该用〈集〉。版指书的印刷次数或版面，电视剧的集数要用集，不能用版。"}, {"text": "这个学生一共印了三版。", "explanation": "版指书刊的印刷次数，学生不能“印了三版”，这里的版用法不通。"}, {"text": "我买了一版桌子。", "explanation": "这里应该用〈张〉。版不是桌子的量词，量桌子要用张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86421, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指书的印刷次数，读 bǎn（第三声）。"}, {"text": "扮", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是扮演。"}, {"text": "拌", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是搅拌。"}, {"text": "榜", "is_correct": false, "explanation": "bǎng 与 bǎn 韵母不同（ang 与 an），意思是榜样或榜单。"}, {"text": "斑", "is_correct": false, "explanation": "bān（第一声）与 bǎn（第三声）声调不同，意思是斑点。"}], "explanations": {"版": "正确：版指书的印刷次数，读 bǎn（第三声）。", "扮": "bàn（第四声）与 bǎn（第三声）声调不同，意思是扮演。", "拌": "bàn（第四声）与 bǎn（第三声）声调不同，意思是搅拌。", "榜": "bǎng 与 bǎn 韵母不同（ang 与 an），意思是榜样或榜单。", "斑": "bān（第一声）与 bǎn（第三声）声调不同，意思是斑点。"}, "sentence_index": null, "correct_answer": "版"}, "level_3": {"options": [{"text": "版", "is_correct": true, "explanation": "正确：版指印刷次数，“印第四版”即印第四次。"}, {"text": "号", "is_correct": false, "explanation": "语义：号是期刊的期号，不用于书的印刷次数。"}, {"text": "篇", "is_correct": false, "explanation": "搭配：篇用于文章，不能和“印第四”搭配来指印刷次数。"}, {"text": "幅", "is_correct": false, "explanation": "搭配：幅是画或字画的量词，不能说“印第四幅”指书的印次。"}], "explanations": {"版": "正确：版指印刷次数，“印第四版”即印第四次。", "号": "语义：号是期刊的期号，不用于书的印刷次数。", "篇": "搭配：篇用于文章，不能和“印第四”搭配来指印刷次数。", "幅": "搭配：幅是画或字画的量词，不能说“印第四幅”指书的印次。"}, "sentence_index": 6, "correct_answer": "版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本词典多了一千版。", "explanation": "这里应该表示增加的词条数，版只说印刷次数，不能用来计算词数。"}, {"text": "我的房子印了第三版。", "explanation": "版指书刊的印刷次数，房子不能“印了第三版”，这里的版用法不对。"}, {"text": "我买了一版笔。", "explanation": "这里应该用〈支〉。版不是笔的量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本小说已经出到第八版的了。", "corrected_sentence": "这本小说已经出到第八版了。", "error_description": "“版”后面不能加“的”：应说“第八版了”，“版的了”是错误的词语搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出版社下个月会印第五本版。", "corrected_sentence": "出版社下个月会印第五版。", "error_description": "多余量词：〈版〉本身就表示版次，“第五”后面直接接〈版〉，不能再加量词“本”。应说“印第五版”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
