INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情留在脑子里；写下来。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "老师说的话，你要记在心里。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕忘了，所以把电话号码记在手机里。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他记不住这个字怎么写。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时他认真地把黑板上的内容记下来。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把明天的会议时间记下来。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多人的名字，我一下子记不住。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把要买的东西记在小本子上。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记了很多生词，可是还是会忘。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的事，他到现在还记在心里。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拿笔把我的电话号码记一下。", "target_word": "记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "记了", "label": "体标"}, {"form": "记过", "label": "体标"}, {"form": "记着", "label": "体标"}, {"form": "记住", "label": "复合"}, {"form": "記", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把事情留在脑子里或写下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记", "is_correct": true, "explanation": "“记”读作 jì，意思是把事情留在脑子里或写下来。"}, {"text": "几", "is_correct": false, "explanation": "“几”（jǐ 第三声）与“记”声调不同，意思是“几个”。"}, {"text": "鸡", "is_correct": false, "explanation": "“鸡”（jī 第一声）与“记”声调不同，意思是鸡。"}, {"text": "急", "is_correct": false, "explanation": "“急”（jí 第二声）与“记”声调不同，意思是着急。"}, {"text": "气", "is_correct": false, "explanation": "“气”（qì）与“记”声母不同（q 与 j），声调相同，意思是空气。"}, {"text": "细", "is_correct": false, "explanation": "“细”（xì）与“记”声母不同（x 与 j），声调相同，意思是细小。"}], "explanations": {"记": "“记”读作 jì，意思是把事情留在脑子里或写下来。", "几": "“几”（jǐ 第三声）与“记”声调不同，意思是“几个”。", "鸡": "“鸡”（jī 第一声）与“记”声调不同，意思是鸡。", "急": "“急”（jí 第二声）与“记”声调不同，意思是着急。", "气": "“气”（qì）与“记”声母不同（q 与 j），声调相同，意思是空气。", "细": "“细”（xì）与“记”声母不同（x 与 j），声调相同，意思是细小。"}, "sentence_index": null, "correct_answer": "记"}, "level_3": {"options": [{"text": "记", "is_correct": true, "explanation": "“记在心里”表示把话牢牢记住，与句意相合，正确。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，与“留在心里”的意思相反。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是东西，不能说“买在心里”。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指重重地落下或抛掉，与“记在心里”的意思不符。"}], "explanations": {"记": "“记在心里”表示把话牢牢记住，与句意相合，正确。", "扔": "语义：“扔”是丢掉，与“留在心里”的意思相反。", "买": "搭配：“买”的对象是东西，不能说“买在心里”。", "摔": "语义：“摔”指重重地落下或抛掉，与“记在心里”的意思不符。"}, "sentence_index": 0, "correct_answer": "记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他记了一封长长的信。", "explanation": "写信要用〈写〉。“记”表示记在脑中或记下要点，不能用来指写一封完整的信。"}, {"text": "他记了一杯茶。", "explanation": "喝茶要用〈喝〉。“记”不能表示喝，这里用错了。"}, {"text": "他记了一幅画。", "explanation": "画画要用〈画〉。“记”不能表示创作，只能表示记住或写下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86424, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "记", "is_correct": true, "explanation": "“记”读作 jì，意思是把事情留在脑子里或写下来。"}, {"text": "己", "is_correct": false, "explanation": "“己”（jǐ 第三声）与“记”声调不同，意思是自己。"}, {"text": "机", "is_correct": false, "explanation": "“机”（jī 第一声）与“记”声调不同，意思是机器。"}, {"text": "集", "is_correct": false, "explanation": "“集”（jí 第二声）与“记”声调不同，意思是集合。"}, {"text": "戏", "is_correct": false, "explanation": "“戏”（xì）与“记”声母不同（x 与 j），声调相同，意思是戏剧。"}, {"text": "基", "is_correct": false, "explanation": "“基”（jī 第一声）与“记”声调不同，意思是基础。"}], "explanations": {"记": "“记”读作 jì，意思是把事情留在脑子里或写下来。", "己": "“己”（jǐ 第三声）与“记”声调不同，意思是自己。", "机": "“机”（jī 第一声）与“记”声调不同，意思是机器。", "集": "“集”（jí 第二声）与“记”声调不同，意思是集合。", "戏": "“戏”（xì）与“记”声母不同（x 与 j），声调相同，意思是戏剧。", "基": "“基”（jī 第一声）与“记”声调不同，意思是基础。"}, "sentence_index": null, "correct_answer": "记"}, "level_3": {"options": [{"text": "记", "is_correct": true, "explanation": "“记在小本子上”表示写下来，与句意相合，正确。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“在小本子上”搭配，说“洗在小本子上”不成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“在小本子上”搭配，说“唱在小本子上”不成立。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿用力夹住，与“写在小本子上”的意思无关。"}], "explanations": {"记": "“记在小本子上”表示写下来，与句意相合，正确。", "洗": "搭配：“洗”不能与“在小本子上”搭配，说“洗在小本子上”不成立。", "唱": "搭配：“唱”不能与“在小本子上”搭配，说“唱在小本子上”不成立。", "咬": "语义：“咬”指用牙齿用力夹住，与“写在小本子上”的意思无关。"}, "sentence_index": 6, "correct_answer": "记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他记了一双鞋。", "explanation": "穿鞋要用〈穿〉。“记”不能表示穿戴，这里用错了。"}, {"text": "他记了一个苹果。", "explanation": "摘苹果要用〈摘〉。“记”不能用于拿取或摘下东西。"}, {"text": "他记了一张照片。", "explanation": "拍照片要用〈拍〉。“记”不能表示拍摄，这里用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content 