INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把它记着下来了。", "corrected_sentence": "我已经把它记下来了。", "error_description": "“着”不能插在动词“记”和补语“下来”之间。错误写法是“记着下来”，正确写法是“记下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我记了住电话号码。", "corrected_sentence": "我记住了电话号码。", "error_description": "“了”应放在复合动词“记住”后面，不能插在“记”和“住”之间。错误写法是“记了住”，正确写法是“记住了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
