INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86425, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行政是管理一个地方或一个单位里日常事情的工作。", "primary_collocate": null, "pronunciation": "xíng zhèng", "ipa": "ɕiŋ˧˥ ʈʂəŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她在公司做行政工作。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学校做行政很忙，每天有很多小事。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个行政的工作。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不教书，在学校做行政。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公司做行政，每天要负责买桌子和笔。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行政的事每天都很多，也很小。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前在医院做过三年行政，现在去学校教书了。", "target_word": "行政", "complexity_tier": "T3", "furigana": "tā yǐqián zài yīyuàn zuò guo sān nián xíngzhèng, xiànzài qù xuéxiào jiāo shū le.", "sentence_source": "generated"}, {"text": "做行政要细心，也要会和人说话。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了三年行政，学会了很多。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在二楼做行政，每天很早来。", "target_word": "行政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政部门", "label": "复合"}, {"form": "行政人员", "label": "复合"}, {"form": "行政工作", "label": "复合"}], "register": "中性", "sense_fingerprint": "管理单位日常事务的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b99fe0-ca51-4411-a7d6-da75aa0fad5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86425, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行政", "is_correct": true, "explanation": "正确。行政是管理一个地方或单位日常事务的工作。"}, {"text": "形成", "is_correct": false, "explanation": "chéng 与 zhèng 的声母（ch/zh）和声调都不同，“形成”指事物逐渐出现、构成。"}, {"text": "行程", "is_correct": false, "explanation": "chéng 与 zhèng 声母（ch/zh）和声调都不同，“行程”指旅途的路线或安排。"}, {"text": "新政", "is_correct": false, "explanation": "xīn 与 xíng 韵母（in/ing）和声调不同，“新政”指新的政策。"}, {"text": "行省", "is_correct": false, "explanation": "shěng 与 zhèng 声母（sh/zh）和声调不同，“行省”是历史上的一级行政区划。"}], "explanations": {"行政": "正确。行政是管理一个地方或单位日常事务的工作。", "形成": "chéng 与 zhèng 的声母（ch/zh）和声调都不同，“形成”指事物逐渐出现、构成。", "行程": "chéng 与 zhèng 声母（ch/zh）和声调都不同，“行程”指旅途的路线或安排。", "新政": "xīn 与 xíng 韵母（in/ing）和声调不同，“新政”指新的政策。", "行省": "shěng 与 zhèng 声母（sh/zh）和声调不同，“行省”是历史上的一级行政区划。"}, "sentence_index": null, "correct_answer": "行政"}, "level_3": {"options": [{"text": "行政", "is_correct": true, "explanation": "正确。“行政工作”指管理公司日常事务的工作，与“在公司做”相符。"}, {"text": "临床", "is_correct": false, "explanation": "语义：“临床”指医院的诊疗工作，与“在公司”冲突。"}, {"text": "教务", "is_correct": false, "explanation": "语义：“教务”是学校的教学事务管理，公司里不做这类工作。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“钢笔”是物品，不能修饰“工作”来表示工作的类别。"}], "explanations": {"行政": "正确。“行政工作”指管理公司日常事务的工作，与“在公司做”相符。", "临床": "语义：“临床”指医院的诊疗工作，与“在公司”冲突。", "教务": "语义：“教务”是学校的教学事务管理，公司里不做这类工作。", "钢笔": "搭配：“钢笔”是物品，不能修饰“工作”来表示工作的类别。"}, "sentence_index": 0, "correct_answer": "行政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被派去行政一个部门，负责日常事务。", "explanation": "这里应该用〈管理〉。“行政”是名词，指一类具体的工作，不能当动词用来表示“管理一个部门”。"}, {"text": "她行政了这个项目，每天都很辛苦。", "explanation": "这里应该用〈负责〉。“行政”是名词，不能当动词表示“负责这个项目”。"}, {"text": "那座行政很高，离公司很远。", "explanation": "这里应该用〈大楼〉。“座”可以用于大楼，但“行政”指一类工作，不是建筑物，不能说“很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政", "is_correct": true, "explanation": "正确。“行政”指单位里的管理工作，符合“在医院做过三年”的叙述。"}, {"text": "农业", "is_correct": false, "explanation": "语义：“农业”指种植和养殖，与“在医院”的工作场所不符。"}, {"text": "采矿", "is_correct": false, "explanation": "语义：“采矿”是矿场的工作，与“在医院”不符。"}, {"text": "行伍", "is_correct": false, "explanation": "语义：“行伍”指军队里的士兵行列，与“在医院”的工作场所不符。"}], "explanations": {"行政": "正确。“行政”指单位里的管理工作，符合“在医院做过三年”的叙述。", "农业": "语义：“农业”指种植和养殖，与“在医院”的工作场所不符。", "采矿": "语义：“采矿”是矿场的工作，与“在医院”不符。", "行伍": "语义：“行伍”指军队里的士兵行列，与“在医院”的工作场所不符。"}, "sentence_index": 6, "correct_answer": "行政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她正在行政这三个部门，每天很忙。", "explanation": "这里应该用〈管理〉。“行政”是名词，不能当动词表示“管理这三个部门”。"}, {"text": "那颗行政很亮，在夜空里很显眼。", "explanation": "这里应该用〈星星〉。“颗”可以用于星星，但“行政”指工作，不能用于天体。"}, {"text": "他行政了这个团队，效果很好。", "explanation": "这里应该用〈领导〉。“行政”是名词，不能当动词表示“领导这个团队”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下个月开始做了行政工作。", "corrected_sentence": "他下个月开始做行政工作。", "error_description": "时态错误：“下个月”表示将来，动作尚未发生，“做”后不能加“了”，应说“开始做行政工作”，不说“开始做了行政工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在公司做了两年了行政，很有经验。", "corrected_sentence": "她在公司做了两年行政，很有经验。", "error_description": "错误：“了”不能放在时量词“两年”和宾语“行政”之间，应说“做了两年行政”，不说“做了两年了行政”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
