INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "银行是可以放钱和取钱的地方。", "primary_collocate": null, "pronunciation": "yín háng", "ipa": "in˧˥ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我去银行取钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱存在银行里。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行里有很多人在排队取钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行离我家很近，我常去存钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈下午要去银行存钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的门口有一台取钱的机器。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在银行取了五百块钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去银行存钱，你去吗？", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在银行里等着取钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从银行取出了一些钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "银行卡", "label": "复合"}, {"form": "銀行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "银行：人们去存钱、取钱的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): 很近 (Zipf 3.22), 我常 (Zipf 3.17), 存钱 (Zipf 3.17)']::text[], 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不办理取钱，“我去医院取钱”说不通。"}, {"text": "银行", "is_correct": true, "explanation": "正确。银行是存钱、取钱的地方，与“取钱”搭配自然。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借书阅读的地方，不办理取钱。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：取钱这一动作不与公园搭配，公园不是取款的场所。"}], "explanations": {"医院": "语义：医院是看病的地方，不办理取钱，“我去医院取钱”说不通。", "银行": "正确。银行是存钱、取钱的地方，与“取钱”搭配自然。", "图书馆": "语义：图书馆是借书阅读的地方，不办理取钱。", "公园": "搭配：取钱这一动作不与公园搭配，公园不是取款的场所。"}, "sentence_index": 0, "correct_answer": "银行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把银行数了一遍。", "explanation": "银行指可以存取钱的地方，不是钱，这里把它当作钱来数，意思不对。"}, {"text": "我在那只银行存了钱。", "explanation": "这里应该用〈家〉。银行是机构，量词用〈家〉，不用〈只〉，应说那家银行。"}, {"text": "他把银行装进口袋里带走了。", "explanation": "银行指金融机构，不是可以装进口袋的物品，这里把它当作钱包用，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "药店", "is_correct": false, "explanation": "语义：药店卖药，不办理取钱业务，“在药店取了五百块钱”不通。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是办理取钱业务的地方。"}, {"text": "银行", "is_correct": true, "explanation": "正确。银行是办理取钱业务的地方，与“取了五百块钱”搭配自然。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：取钱不与饭店搭配，取钱要去金融机构。"}], "explanations": {"药店": "语义：药店卖药，不办理取钱业务，“在药店取了五百块钱”不通。", "学校": "语义：学校不是办理取钱业务的地方。", "银行": "正确。银行是办理取钱业务的地方，与“取了五百块钱”搭配自然。", "饭店": "搭配：取钱不与饭店搭配，取钱要去金融机构。"}, "sentence_index": 6, "correct_answer": "银行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们那条银行很大。", "explanation": "这里应该用〈家〉。银行用〈家〉计量，〈条〉用于细长的物体，不用于银行。"}, {"text": "这家银行很好吃。", "explanation": "银行指可以存取钱的地方，不是食物，这里把它当作食物用，意思不对。"}, {"text": "他每天坐银行去上班。", "explanation": "银行是金融机构，不是交通工具，这里把它当作车用，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每个月都去那只银行还贷款。", "corrected_sentence": "我每个月都去那家银行还贷款。", "error_description": "「那只银行」错。银行的量词是〈家〉，〈只〉不用于机构，应改为「那家银行」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去很家银行贷款。", "corrected_sentence": "他去那家银行贷款。", "error_description": "「很家银行」错。银行前的指示词应为〈那〉或〈这〉，“很”不能修饰量词短语，应改为「那家银行」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
