INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经营存款、贷款、汇兑等业务的金融机构。", "primary_collocate": null, "pronunciation": "yín háng", "ipa": "in˧˥ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他向银行贷了一笔款。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行会给存款付利息。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行可以办理贷款。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在银行办了一张信用卡。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的利息最近变高了。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行工作，每天和钱打交道。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行是经营存款和贷款业务的机构。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要买房子，他得先向银行借钱。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行在很多国家都有业务。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司和三家银行有合作。", "target_word": "银行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "银行账户", "label": "复合"}, {"form": "銀行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "银行：办理存款、贷款等业务的金融机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商店", "is_correct": false, "explanation": "语义：商店是卖东西的地方，不发放贷款，“向商店贷了一笔款”不通。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不发放贷款，向学校贷款说不通。"}, {"text": "银行", "is_correct": true, "explanation": "正确。银行是经营贷款业务的机构，与“贷了一笔款”搭配自然。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“贷款”不搭配饭店，饭店不经营贷款业务。"}], "explanations": {"商店": "语义：商店是卖东西的地方，不发放贷款，“向商店贷了一笔款”不通。", "学校": "语义：学校不发放贷款，向学校贷款说不通。", "银行": "正确。银行是经营贷款业务的机构，与“贷了一笔款”搭配自然。", "饭店": "搭配：“贷款”不搭配饭店，饭店不经营贷款业务。"}, "sentence_index": 0, "correct_answer": "银行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在那只银行办了一张信用卡。", "explanation": "这里应该用〈家〉。银行是机构，量词用〈家〉，不用〈只〉，应说那家银行。"}, {"text": "他把银行种在院子里。", "explanation": "银行指金融机构，不能种植，这里把它当作植物用，意思不对。"}, {"text": "我把银行放进了口袋。", "explanation": "银行指金融机构，不是可以装进口袋的物品，这里把它当作钱包用，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "超市", "is_correct": false, "explanation": "语义：超市是零售商店，不经营存款和贷款业务。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院提供诊疗服务，不经营存款和贷款业务。"}, {"text": "保险公司", "is_correct": false, "explanation": "语义：保险公司经营保险业务，不经营存款和贷款业务。"}, {"text": "银行", "is_correct": true, "explanation": "正确。银行是经营存款和贷款业务的金融机构，与定义相符。"}], "explanations": {"超市": "语义：超市是零售商店，不经营存款和贷款业务。", "医院": "语义：医院提供诊疗服务，不经营存款和贷款业务。", "保险公司": "语义：保险公司经营保险业务，不经营存款和贷款业务。", "银行": "正确。银行是经营存款和贷款业务的金融机构，与定义相符。"}, "sentence_index": 6, "correct_answer": "银行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司和三辆银行有合作。", "explanation": "这里应该用〈家〉。银行不用辆计量，〈辆〉用于车辆。"}, {"text": "我们公司把银行存进了冰箱。", "explanation": "银行指金融机构，不是能存放在冰箱里的物品，这里把它当作物体用，意思不对。"}, {"text": "我们公司的员工每天骑银行上班。", "explanation": "银行指金融机构，不是交通工具，这里把它当作自行车用，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只银行的利率今年降了不少。", "corrected_sentence": "这家银行的利率今年降了不少。", "error_description": "「这只银行」错。银行的量词是〈家〉，〈只〉不用于机构，应改为「这家银行」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司的账户在很家银行。", "corrected_sentence": "我们公司的账户在那家银行。", "error_description": "「很家银行」错。银行前的指示词应为〈那〉或〈这〉，“很”不能修饰量词短语，应改为「那家银行」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86431, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
