INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86431, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遭到是碰上了不好的事。", "primary_collocate": null, "pronunciation": "zāo dào", "ipa": "tsau˥ tau˥˩", "syllable_count": 2, "sentences": [{"text": "他的做法遭到老师批评。", "target_word": "遭到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的船遭到了大风浪的袭击。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的小路遭到大雪的破坏。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇遭到过地震的破坏。", "target_word": "遭到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话遭到所有人的反对。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨晚这家商店遭到了抢劫。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家的新书遭到很多批评。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "庄稼遭到了虫子的破坏。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的提议遭到了市民的反对。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人在街上遭到坏人的欺负。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遭到了", "label": "体标"}, {"form": "遭到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "碰上了不好的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遭到", "is_correct": true, "explanation": "遭到：碰上不利的事，「他的做法遭到老师批评」符合句意。"}, {"text": "获得", "is_correct": false, "explanation": "搭配：「获得」多指取得好的事物，「获得老师批评」搭配不当。"}, {"text": "赞同", "is_correct": false, "explanation": "语义：「赞同」与「批评」态度相反，「做法赞同老师批评」不通。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：「讨论」的宾语应是议题，不能接「老师批评」这样的结构。"}], "explanations": {"遭到": "遭到：碰上不利的事，「他的做法遭到老师批评」符合句意。", "获得": "搭配：「获得」多指取得好的事物，「获得老师批评」搭配不当。", "赞同": "语义：「赞同」与「批评」态度相反，「做法赞同老师批评」不通。", "讨论": "配价：「讨论」的宾语应是议题，不能接「老师批评」这样的结构。"}, "sentence_index": 0, "correct_answer": "遭到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的画遭到了很多人的欣赏。", "explanation": "这里应该用〈获得〉。遭到只用于不利的事，欣赏是好事，应该用获得。"}, {"text": "我们的队遭到了胜利。", "explanation": "这里应该用〈取得〉。遭到只用于不利的事，胜利是好事，应该用取得。"}, {"text": "路上我遭到了一位老朋友。", "explanation": "这里应该用〈遇见〉。遭到表示碰上不利的事，偶然遇见老朋友不属于这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遭到", "is_correct": true, "explanation": "遭到：碰上不利的事，「这位作家的新书遭到很多批评」符合句意。"}, {"text": "发明", "is_correct": false, "explanation": "语义：「发明」指创造新事物，与「批评」的意思无关。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：「打开」后接的是门、局面等，「打开批评」搭配不当。"}, {"text": "旅行", "is_correct": false, "explanation": "配价：「旅行」是不及物动词，不能带「批评」作宾语。"}], "explanations": {"遭到": "遭到：碰上不利的事，「这位作家的新书遭到很多批评」符合句意。", "发明": "语义：「发明」指创造新事物，与「批评」的意思无关。", "打开": "搭配：「打开」后接的是门、局面等，「打开批评」搭配不当。", "旅行": "配价：「旅行」是不及物动词，不能带「批评」作宾语。"}, "sentence_index": 6, "correct_answer": "遭到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天他在公园遭到了一位老同学。", "explanation": "这里应该用〈遇到〉。遭到表示碰上不利的事，与老同学偶然相遇是愉快的事，不能用遭到。"}, {"text": "老人在街上遭到了一本书。", "explanation": "这里应该用〈捡到〉。遭到的对象必须是不幸或不利的事，一本书是具体物品，捡到它才合适。"}, {"text": "他的作文遭到了很大的进步。", "explanation": "这里应该用〈取得〉。遭到只用于不利的事，进步是好事，应该用取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的车遭到了大雨了的损坏。", "corrected_sentence": "我的车遭到了大雨的损坏。", "error_description": "错误形式：「遭到了大雨了的损坏」；正确形式：「遭到了大雨的损坏」。「了」只应紧跟动词「遭到」，「大雨」之后不能再加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把稻田遭到了洪水的冲刷。", "corrected_sentence": "稻田遭到了洪水的冲刷。", "error_description": "错误形式：「把稻田遭到了洪水的冲刷」；正确形式：「稻田遭到了洪水的冲刷」。「遭到」表示承受不利的事，不能用于「把」字句，去掉「把」、让「稻田」作主语即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
