INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86432, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86432, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到（不幸或不利的事）。", "primary_collocate": null, "pronunciation": "zāo dào", "ipa": "tsau˥ tau˥˩", "syllable_count": 2, "sentences": [{"text": "他的想法遭到大家反对。", "target_word": "遭到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小船在海上遭到风暴的袭击。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子遭到了洪水的破坏。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的请求遭到了老师的拒绝。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新电影遭到很多人批评。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在路上遭到了坏人的攻击。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花园遭到大雨的破坏，花都坏了。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的建议遭到经理的反对。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家曾经遭到别国的进攻。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她第一次投稿就遭到了拒绝。", "target_word": "遭到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遭到了", "label": "体标"}, {"form": "遭到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "受到不幸或不利的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遭到", "is_correct": true, "explanation": "遭到：受到不利的事，「他的想法遭到大家反对」符合句意。"}, {"text": "得到", "is_correct": false, "explanation": "搭配：「得到」多指获得好的事物，「得到大家反对」搭配不当。"}, {"text": "赞成", "is_correct": false, "explanation": "语义：「赞成」与「反对」意思相反，「想法赞成大家反对」不通。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：「讨论」的宾语应是议题，不能接「大家反对」这样的结构。"}], "explanations": {"遭到": "遭到：受到不利的事，「他的想法遭到大家反对」符合句意。", "得到": "搭配：「得到」多指获得好的事物，「得到大家反对」搭配不当。", "赞成": "语义：「赞成」与「反对」意思相反，「想法赞成大家反对」不通。", "讨论": "配价：「讨论」的宾语应是议题，不能接「大家反对」这样的结构。"}, "sentence_index": 0, "correct_answer": "遭到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位学生的成绩遭到了老师的表扬。", "explanation": "这里应该用〈得到〉。遭到只用于不幸或不利的事，表扬是好事，应该用得到。"}, {"text": "他终于遭到了成功。", "explanation": "这里应该用〈取得〉。遭到只用于不幸或不利的事，成功是好事，应该用取得。"}, {"text": "路上他遭到了一只小猫。", "explanation": "这里应该用〈遇见〉。遭到的对象必须是不幸或不利的事，不能是具体的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遭到", "is_correct": true, "explanation": "遭到：受到不利的事，「花园遭到大雨的破坏」符合句意。"}, {"text": "享受", "is_correct": false, "explanation": "语义：「享受」指得到愉快的事物，与「破坏」的不利义相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」指欣赏美好的事物，「花园欣赏大雨的破坏」不通。"}, {"text": "迎接", "is_correct": false, "explanation": "配价：「迎接」后面多接来到的人或事，不能直接带「破坏」这种结果作宾语。"}], "explanations": {"遭到": "遭到：受到不利的事，「花园遭到大雨的破坏」符合句意。", "享受": "语义：「享受」指得到愉快的事物，与「破坏」的不利义相反。", "欣赏": "语义：「欣赏」指欣赏美好的事物，「花园欣赏大雨的破坏」不通。", "迎接": "配价：「迎接」后面多接来到的人或事，不能直接带「破坏」这种结果作宾语。"}, "sentence_index": 6, "correct_answer": "遭到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于遭到了一份好工作。", "explanation": "这里应该用〈得到〉。遭到只用于不幸或不利的事，找到好工作是好事，应该用得到。"}, {"text": "他在图书馆遭到了一本书。", "explanation": "这里应该用〈借到〉。遭到只用于不幸或不利的事，借到书是好事，而且遭到不能带具体物品作宾语。"}, {"text": "节日的晚上，我们遭到了很多好消息。", "explanation": "这里应该用〈收到〉。遭到只用于不幸或不利的事，好消息不能用遭到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥遭到了暴雨了的冲击。", "corrected_sentence": "这座桥遭到了暴雨的冲击。", "error_description": "错误形式：「遭到了暴雨了的冲击」；正确形式：「遭到了暴雨的冲击」。「了」只应紧跟动词「遭到」，「暴雨」之后不能再加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片树林遭到了过大火的破坏。", "corrected_sentence": "这片树林遭到过大火的破坏。", "error_description": "错误形式：「遭到了过」；正确形式：「遭到过」。表示曾经经历某事用「遭到过」，「了」和「过」不能同时用在同一动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
