INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使停止行动；不让前进。", "primary_collocate": null, "pronunciation": "zǔ zhǐ", "ipa": "tsu˨˩˦ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "大雪阻止了我们前进。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在路口阻止车辆通过。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水阻止了汽车前进。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水太深，阻止了他们过河。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的大树阻止了车前进。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有什么能阻止他向前走。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用墙阻止水流进来。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察阻止人们走进那条街。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气阻止过船出海。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯阻止车辆继续前进。", "target_word": "阻止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "阻止了", "label": "完成体"}, {"form": "阻止过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使人或物停止行动、不能前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b99fe0-ca51-4411-a7d6-da75aa0fad5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86434, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阻止", "is_correct": true, "explanation": "正确。阻止指使人或物停止行动，不让前进。"}, {"text": "组织", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，“组织”指把人或事物有计划地集合起来。"}, {"text": "阻滞", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“阻滞”指受阻而不畅通。"}, {"text": "阻值", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，“阻值”指电路中电阻的大小。"}], "explanations": {"阻止": "正确。阻止指使人或物停止行动，不让前进。", "组织": "zhī（第一声）与 zhǐ（第三声）声调不同，“组织”指把人或事物有计划地集合起来。", "阻滞": "zhì（第四声）与 zhǐ（第三声）声调不同，“阻滞”指受阻而不畅通。", "阻值": "zhí（第二声）与 zhǐ（第三声）声调不同，“阻值”指电路中电阻的大小。"}, "sentence_index": null, "correct_answer": "阻止"}, "level_3": {"options": [{"text": "阻止", "is_correct": true, "explanation": "正确。“阻止”表示使前进的大雪或物体停下，与“大雪”和“前进”相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：大雪不能欢迎人，“欢迎我们前进”与语境不符。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”要求有意志的施事，大雪不能鼓励人前进。"}, {"text": "叫", "is_correct": false, "explanation": "配价：“叫”要求有意志的施事发出指令，大雪不能叫人前进。"}], "explanations": {"阻止": "正确。“阻止”表示使前进的大雪或物体停下，与“大雪”和“前进”相符。", "欢迎": "语义：大雪不能欢迎人，“欢迎我们前进”与语境不符。", "鼓励": "语义：“鼓励”要求有意志的施事，大雪不能鼓励人前进。", "叫": "配价：“叫”要求有意志的施事发出指令，大雪不能叫人前进。"}, "sentence_index": 0, "correct_answer": "阻止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一阵风阻止了他的回忆。", "explanation": "这里应该用〈打断〉。“阻止”的对象应是能停下或前进的行动或车辆，回忆不能被“阻止”，只能被打断。"}, {"text": "这些垃圾阻止了下水道。", "explanation": "这里应该用〈堵塞〉。“阻止”的对象是人或车辆的行动，下水道应说被堵塞。"}, {"text": "一堵墙阻止了视线。", "explanation": "这里应该用〈阻挡〉。“阻止”的宾语应是能停下或前进的对象，视线不能被“阻止”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阻止", "is_correct": true, "explanation": "正确。“用墙阻止水流”指用墙挡住水流，与“用墙”相符。"}, {"text": "吸引", "is_correct": false, "explanation": "语义：墙不能吸引水流，“吸引”的主体应是有吸引力的事物。"}, {"text": "邀请", "is_correct": false, "explanation": "配价：“邀请”的对象需要是人，不能带“水流”作宾语。"}, {"text": "迎接", "is_correct": false, "explanation": "搭配：“迎接”的对象是人或事件，不搭配“水流”。"}], "explanations": {"阻止": "正确。“用墙阻止水流”指用墙挡住水流，与“用墙”相符。", "吸引": "语义：墙不能吸引水流，“吸引”的主体应是有吸引力的事物。", "邀请": "配价：“邀请”的对象需要是人，不能带“水流”作宾语。", "迎接": "搭配：“迎接”的对象是人或事件，不搭配“水流”。"}, "sentence_index": 6, "correct_answer": "阻止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这阵噪音阻止了她的睡眠。", "explanation": "这里应该用〈打扰〉。“阻止”的对象应是人的行动，睡眠不能被“阻止”，只能被打扰。"}, {"text": "窗帘阻止了阳光。", "explanation": "这里应该用〈挡住〉。“阻止”要求能停下或前进的对象，阳光不能被“阻止”。"}, {"text": "一场突如其来的疾病阻止了他的梦想。", "explanation": "这里应该用〈阻碍〉。“阻止”的宾语是人的行动或车辆的前进，不能用于“梦想”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门卫阻止了我们了进门。", "corrected_sentence": "门卫阻止了我们进门。", "error_description": "错误：“阻止了我们了进门”应为“阻止了我们进门”。“了”已用在动词“阻止”后表示完成，不能再放在宾语“我们”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洪水阻止了村民了回家。", "corrected_sentence": "洪水阻止了村民回家。", "error_description": "错误：“阻止了村民了回家”，应为“阻止了村民回家”。“了”只表示动作完成，已用在动词“阻止”后，不能再放在宾语“村民”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dde2ccb8-f9a5-4f6b-b6ec-79fb5caf918e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
