INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86435, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "龙是故事里的动物，身体很长，会飞。", "primary_collocate": null, "pronunciation": "lóng", "ipa": "lʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "故事里的龙会飞。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看到一条很长的龙。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩想有一条会飞的龙。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条龙飞到了山上。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的龙很大，也很可怕。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢听龙的故事。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里有一条红色的龙。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙的身体很长，还有四只脚。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给妹妹讲了一个龙的故事。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条龙不吃人，它是好朋友。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条龙", "label": "量词"}, {"form": "龍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "龙：故事里身体很长、会飞的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86435, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "龙", "is_correct": true, "explanation": "龙指故事里身体很长、会飞的动物，正是本词。"}, {"text": "农", "is_correct": false, "explanation": "农（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是农业。"}, {"text": "荣", "is_correct": false, "explanation": "荣（róng）与龙（lóng）声母不同，r 与 l 的区别，意思是荣誉。"}, {"text": "垄", "is_correct": false, "explanation": "垄（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是田垄。"}], "explanations": {"龙": "龙指故事里身体很长、会飞的动物，正是本词。", "农": "农（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是农业。", "荣": "荣（róng）与龙（lóng）声母不同，r 与 l 的区别，意思是荣誉。", "垄": "垄（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是田垄。"}, "sentence_index": null, "correct_answer": "龙"}, "level_3": {"options": [{"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是故事里会飞的东西，“会飞”说不通。"}, {"text": "龙", "is_correct": true, "explanation": "龙是故事里会飞的动物，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是活动，不能用“会飞”来形容。"}, {"text": "哲学", "is_correct": false, "explanation": "语义：哲学是抽象的学问，不是会飞的东西，“会飞”说不通。"}], "explanations": {"数学": "语义：数学是学科，不是故事里会飞的东西，“会飞”说不通。", "龙": "龙是故事里会飞的动物，符合句意。", "考试": "语义：考试是活动，不能用“会飞”来形容。", "哲学": "语义：哲学是抽象的学问，不是会飞的东西，“会飞”说不通。"}, "sentence_index": 0, "correct_answer": "龙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天骑着一条龙去上学。", "explanation": "这里应该用〈自行车〉。上学骑的是自行车，龙是故事里的动物。"}, {"text": "那条龙是饭店里的一道菜。", "explanation": "这里应该用〈鸡〉。龙是神话动物，不能指饭店里的菜，饭店里的菜应说“鸡”或“鱼”。"}, {"text": "那条龙是我们班的数学老师。", "explanation": "这里应该用〈人〉。龙是故事中的动物，不能指人，应说“那位数学老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86435, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "龙", "is_correct": true, "explanation": "龙指故事里身体很长、会飞的动物，正是本词。"}, {"text": "浓", "is_correct": false, "explanation": "浓（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是浓稠。"}, {"text": "郎", "is_correct": false, "explanation": "郎（láng）与龙（lóng）韵母不同，ang 与 ong 的区别，意思是男子。"}, {"text": "拢", "is_correct": false, "explanation": "拢（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是合起来。"}], "explanations": {"龙": "龙指故事里身体很长、会飞的动物，正是本词。", "浓": "浓（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是浓稠。", "郎": "郎（láng）与龙（lóng）韵母不同，ang 与 ong 的区别，意思是男子。", "拢": "拢（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是合起来。"}, "sentence_index": null, "correct_answer": "龙"}, "level_3": {"options": [{"text": "数字", "is_correct": false, "explanation": "语义：数字不是可以“红色”的动物或物品，“一条红色的数字”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不能用“一条红色的”来修饰，句子不通。"}, {"text": "龙", "is_correct": true, "explanation": "龙是故事、电影里的动物，“一条红色的龙”符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“一条红色的”不能修饰空气，两者搭配不当。"}], "explanations": {"数字": "语义：数字不是可以“红色”的动物或物品，“一条红色的数字”说不通。", "时间": "语义：时间不能用“一条红色的”来修饰，句子不通。", "龙": "龙是故事、电影里的动物，“一条红色的龙”符合句意。", "空气": "搭配：“一条红色的”不能修饰空气，两者搭配不当。"}, "sentence_index": 6, "correct_answer": "龙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去邮局寄了一条龙。", "explanation": "这里应该用〈包裹〉。寄出去的是包裹，龙是故事中的动物，不能寄送。"}, {"text": "我用一条龙给妈妈打电话。", "explanation": "这里应该用〈手机〉。打电话用手机，龙是故事里的动物。"}, {"text": "这条龙是班里的一个学生。", "explanation": "这里应该用〈同学〉。龙指故事里的动物，不能指班里的学生，应说“班里的同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条龙在云里飞的很快。", "corrected_sentence": "那条龙在云里飞得很快。", "error_description": "补语标记错误：表示程度的补语要用“得”，应说“飞得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他画了一张很长的龙。", "corrected_sentence": "他画了一条很长的龙。", "error_description": "量词错误：龙身体长，量词用“条”，“张”用于纸、桌子等平的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
