INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86436, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "神话传说中的神异动物，身体长，有鳞有角有爪。", "primary_collocate": null, "pronunciation": "lóng", "ipa": "lʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "中国人常说自己是龙的传人。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书里说，龙能呼风唤雨。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说龙住在很深的海里。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时街上有一条很长的龙。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝的衣服上常常画着龙。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的柱子上有一条金色的龙。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙在神话里是很有力量的动物。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在画一条红色的龙。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人觉得龙会带来雨水。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神话里的龙有角有爪，还有鳞。", "target_word": "龙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条龙", "label": "量词"}, {"form": "龍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "龙：中国神话传说中有鳞有角有爪的神异动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86436, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "龙", "is_correct": true, "explanation": "龙指神话中的神异动物，正是本词。"}, {"text": "农", "is_correct": false, "explanation": "农（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是农业。"}, {"text": "荣", "is_correct": false, "explanation": "荣（róng）与龙（lóng）声母不同，r 与 l 的区别，意思是荣誉。"}, {"text": "垄", "is_correct": false, "explanation": "垄（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是田垄。"}], "explanations": {"龙": "龙指神话中的神异动物，正是本词。", "农": "农（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是农业。", "荣": "荣（róng）与龙（lóng）声母不同，r 与 l 的区别，意思是荣誉。", "垄": "垄（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是田垄。"}, "sentence_index": null, "correct_answer": "龙"}, "level_3": {"options": [{"text": "花", "is_correct": false, "explanation": "语义：花不是中国人自称的传人，“花的传人”说不通。"}, {"text": "龙", "is_correct": true, "explanation": "龙是中华民族的象征，“龙的传人”是固定说法。"}, {"text": "狗", "is_correct": false, "explanation": "语义：中国人自称“龙的传人”，不说“狗的传人”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“传人”指继承某种文化的人，书不能有“传人”。"}], "explanations": {"花": "语义：花不是中国人自称的传人，“花的传人”说不通。", "龙": "龙是中华民族的象征，“龙的传人”是固定说法。", "狗": "语义：中国人自称“龙的传人”，不说“狗的传人”。", "书": "搭配：“传人”指继承某种文化的人，书不能有“传人”。"}, "sentence_index": 0, "correct_answer": "龙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用一条龙写作业。", "explanation": "这里应该用〈笔〉。写作业用笔，龙是神话中的动物。"}, {"text": "他每天早上都喝一条龙当早饭。", "explanation": "这里应该用〈牛奶〉。喝的是饮料，龙是神话中的动物，不能当饮料喝，应说“喝一杯牛奶”。"}, {"text": "他在银行里存了一条龙。", "explanation": "这里应该用〈钱〉。存进银行的是钱，龙是神话中的动物，不能存入银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86436, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "龙", "is_correct": true, "explanation": "龙指神话中的神异动物，正是本词。"}, {"text": "浓", "is_correct": false, "explanation": "浓（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是浓稠。"}, {"text": "郎", "is_correct": false, "explanation": "郎（láng）与龙（lóng）韵母不同，ang 与 ong 的区别，意思是男子。"}, {"text": "拢", "is_correct": false, "explanation": "拢（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是合起来。"}], "explanations": {"龙": "龙指神话中的神异动物，正是本词。", "浓": "浓（nóng）与龙（lóng）声母不同，n 与 l 的区别，意思是浓稠。", "郎": "郎（láng）与龙（lóng）韵母不同，ang 与 ong 的区别，意思是男子。", "拢": "拢（lǒng）与龙（lóng）声调不同，2 声与 3 声的区别，意思是合起来。"}, "sentence_index": null, "correct_answer": "龙"}, "level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是“很有力量的动物”。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“很有力量的动物”的修饰对象应是动物，空气不能这样搭配。"}, {"text": "龙", "is_correct": true, "explanation": "龙是神话中很有力量的神异动物，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是动物，“很有力量的动物”说的不是石头。"}], "explanations": {"桌子": "语义：桌子是家具，不是“很有力量的动物”。", "空气": "搭配：“很有力量的动物”的修饰对象应是动物，空气不能这样搭配。", "龙": "龙是神话中很有力量的神异动物，符合句意。", "石头": "语义：石头不是动物，“很有力量的动物”说的不是石头。"}, "sentence_index": 6, "correct_answer": "龙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道数学题的答案是一条龙。", "explanation": "这里应该用〈数字〉。答案是数字，龙是神话中的动物，不能作为数学题的答案。"}, {"text": "他每天早上用一条龙刷牙。", "explanation": "这里应该用〈牙刷〉。刷牙用的是牙刷，龙是神话中的动物，不能用来刷牙。"}, {"text": "他每天坐一条龙去上班。", "explanation": "这里应该用〈公交车〉。上班坐的是公交车，龙是神话中的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张龙的鳞片闪着金光。", "corrected_sentence": "这条龙的鳞片闪着金光。", "error_description": "量词错误：龙身体长，量词用“条”，“张”用于纸等平的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上画着一条金色的的龙。", "corrected_sentence": "墙上画着一条金色的龙。", "error_description": "重复的“的”：“的”只用一次，连接修饰语和“龙”，“金色的的龙”多了一个“的”。正确说法是“一条金色的龙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86437, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下述", "is_correct": true, "explanation": "正确：“下述”与“上述”相对，指后面将要说的内容。"}, {"text": "特殊", "is_correct": false, "explanation": "“特殊”表示与一般不同，与“上述”不构成反义关系。"}, {"text": "具体", "is_correct": false, "explanation": "“具体”表示明确详细，与“上述”不构成反义关系。"}, {"text": "特定", "is_correct": false, "explanation": "“特定”表示指定的，与“上述”不构成反义关系。"}], "correct_answer": "下述", "explanations": {"下述": "正确：“下述”与“上述”相对，指后面将要说的内容。", "特殊": "“特殊”表示与一般不同，与“上述”不构成反义关系。", "具体": "“具体”表示明确详细，与“上述”不构成反义关系。", "特定": "“特定”表示指定的，与“上述”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
