INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86437, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上述是前面已经说过的。", "primary_collocate": null, "pronunciation": "shàng shù", "ipa": "ʂaŋ˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "上述两个例子说明了同一个道理。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述地点都离学校很近。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据上述数据，我们可以做出决定。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述人员请明天早上八点到。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述几本书我都看过。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他同意上述看法。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述时间不能改变。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述结果让大家很高兴。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述内容我们需要重新核对。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述故事发生在北京。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "定语性词语，用来回指前面已经说过的事物或内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上述", "is_correct": true, "explanation": "正确：“上述”是前面已经说过的，shàng shù。"}, {"text": "上诉", "is_correct": false, "explanation": "shù 与 sù 声母不同（sh 与 s），意思是对判决不服，向上级或法院申请重新审理。"}, {"text": "商数", "is_correct": false, "explanation": "shàng 与 shāng 声调不同，意思是数学中两数相除的结果。"}, {"text": "上书", "is_correct": false, "explanation": "shù 与 shū 声调不同，意思是向上级或君主写信陈述意见。"}], "explanations": {"上述": "正确：“上述”是前面已经说过的，shàng shù。", "上诉": "shù 与 sù 声母不同（sh 与 s），意思是对判决不服，向上级或法院申请重新审理。", "商数": "shàng 与 shāng 声调不同，意思是数学中两数相除的结果。", "上书": "shù 与 shū 声调不同，意思是向上级或君主写信陈述意见。"}, "sentence_index": null, "correct_answer": "上述"}, "level_3": {"options": [{"text": "上述", "is_correct": true, "explanation": "正确：“上述”指前文已经说过的两个例子，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰数量短语“两个例子”，句子不通。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能直接放在数量短语“两个例子”前，句子不通。"}, {"text": "新", "is_correct": false, "explanation": "搭配：“新”修饰“两个例子”不自然，而且与指代前文的语境矛盾。"}], "explanations": {"上述": "正确：“上述”指前文已经说过的两个例子，符合句意。", "很": "语法：“很”是程度副词，不能直接修饰数量短语“两个例子”，句子不通。", "已经": "语法：“已经”是副词，不能直接放在数量短语“两个例子”前，句子不通。", "新": "搭配：“新”修饰“两个例子”不自然，而且与指代前文的语境矛盾。"}, "sentence_index": 0, "correct_answer": "上述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上述规定如下：桌子上不能放书。", "explanation": "这里应该用〈以下〉。“上述”指前文已经说过的内容，引出后文要说的规定要用“以下”，不能说“上述如下”。"}, {"text": "上述节目如下：先唱歌，再跳舞。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，后面要列出的节目要用“以下”，不能说“上述如下”。"}, {"text": "上述情况如下：我们明天再说吧。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，引出后文的情况要用“以下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上述", "is_correct": true, "explanation": "正确：“上述”指前文已经说过的时间，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰名词“时间”，句子不通。"}, {"text": "普通", "is_correct": false, "explanation": "搭配：“普通”修饰“时间”不自然，而且与指代前文的语境不合。"}, {"text": "下一", "is_correct": false, "explanation": "语义：“下一”指接着的那一个，这句说的是前文已经提到的时间。"}], "explanations": {"上述": "正确：“上述”指前文已经说过的时间，符合句意。", "很": "语法：“很”是程度副词，不能直接修饰名词“时间”，句子不通。", "普通": "搭配：“普通”修饰“时间”不自然，而且与指代前文的语境不合。", "下一": "语义：“下一”指接着的那一个，这句说的是前文已经提到的时间。"}, "sentence_index": 6, "correct_answer": "上述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上述现象如下：今晚的月亮很亮。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，后面要说明的现象要用“以下”，不能说“上述如下”。"}, {"text": "上述步骤如下：请把椅子搬走。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，后面的步骤要用“以下”，不能说“上述如下”。"}, {"text": "上述原因如下：风吹得很大。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，后面列出的原因要用“以下”，不能说“上述如下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
