INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86438, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下述", "is_correct": true, "explanation": "正确：“下述”与“上述”相对，指后面将要说的内容。"}, {"text": "特殊", "is_correct": false, "explanation": "“特殊”表示与一般不同，与“上述”不构成反义关系。"}, {"text": "普遍", "is_correct": false, "explanation": "“普遍”表示到处都有，与“上述”不构成反义关系。"}, {"text": "具体", "is_correct": false, "explanation": "“具体”表示明确详细，与“上述”不构成反义关系。"}], "correct_answer": "下述", "explanations": {"下述": "正确：“下述”与“上述”相对，指后面将要说的内容。", "特殊": "“特殊”表示与一般不同，与“上述”不构成反义关系。", "普遍": "“普遍”表示到处都有，与“上述”不构成反义关系。", "具体": "“具体”表示明确详细，与“上述”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86438, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上面说过的。", "primary_collocate": null, "pronunciation": "shàng shù", "ipa": "ʂaŋ˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "上述问题我们明天再讨论。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述情况都是真的。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家看一下上述内容。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述办法都很有用。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述几点你同意吗？", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把上述句子写在黑板上。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述工作需要三个人完成。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述意见我都记下来了。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了上述原因，还有天气不好。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上述规定从下个月开始用。", "target_word": "上述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "定语性词语，放在名词前，指前文已经提到的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上述", "is_correct": true, "explanation": "正确：“上述”是前面已经说过的，shàng shù。"}, {"text": "上诉", "is_correct": false, "explanation": "shù 与 sù 声母不同（sh 与 s），意思是对判决不服，向上级或法院申请重新审理。"}, {"text": "商数", "is_correct": false, "explanation": "shàng 与 shāng 声调不同，意思是数学中两数相除的结果。"}, {"text": "上书", "is_correct": false, "explanation": "shù 与 shū 声调不同，意思是向上级或君主写信陈述意见。"}], "explanations": {"上述": "正确：“上述”是前面已经说过的，shàng shù。", "上诉": "shù 与 sù 声母不同（sh 与 s），意思是对判决不服，向上级或法院申请重新审理。", "商数": "shàng 与 shāng 声调不同，意思是数学中两数相除的结果。", "上书": "shù 与 shū 声调不同，意思是向上级或君主写信陈述意见。"}, "sentence_index": null, "correct_answer": "上述"}, "level_3": {"options": [{"text": "上述", "is_correct": true, "explanation": "正确：“上述”指前文已经提到的，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰名词“问题”，句子不通。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能直接修饰名词“问题”，句子不通。"}, {"text": "都", "is_correct": false, "explanation": "语法：“都”是副词，不能直接修饰名词“问题”，句子不通。"}], "explanations": {"上述": "正确：“上述”指前文已经提到的，符合句意。", "很": "语法：“很”是程度副词，不能直接修饰名词“问题”，句子不通。", "已经": "语法：“已经”是副词，不能直接修饰名词“问题”，句子不通。", "都": "语法：“都”是副词，不能直接修饰名词“问题”，句子不通。"}, "sentence_index": 0, "correct_answer": "上述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上述要点如下：大家都要按时到。", "explanation": "这里应该用〈以下〉。“上述”指前文已经说过的内容，后面列出的内容要说“以下”或“如下”，不能说“上述如下”。"}, {"text": "上述规定如下：不得迟到。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，引出后文的规定要用“以下”。"}, {"text": "上述情况如下：我们明天出发。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，引出后文的情况要用“以下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上述", "is_correct": true, "explanation": "正确：“上述”指前文已经提到的工作，符合句意。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰名词“工作”，句子不通。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰名词“工作”，句子不通。"}, {"text": "同", "is_correct": false, "explanation": "搭配：“同”一般不直接修饰“工作”，这里应说指代前文的工作。"}], "explanations": {"上述": "正确：“上述”指前文已经提到的工作，符合句意。", "很": "语法：“很”是程度副词，不能直接修饰名词“工作”，句子不通。", "非常": "语法：“非常”是程度副词，不能直接修饰名词“工作”，句子不通。", "同": "搭配：“同”一般不直接修饰“工作”，这里应说指代前文的工作。"}, "sentence_index": 6, "correct_answer": "上述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上述步骤如下：先打开电脑。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，后面列出的步骤要用“以下”，不能说“上述如下”。"}, {"text": "你看那辆上述的汽车，停在路边。", "explanation": "这里不能同时用“那辆”和“上述”。“上述”只回指前文，眼前的汽车用“那辆”指示即可，应说“你看那辆汽车，停在路边。”"}, {"text": "上述原因如下：天气很热。", "explanation": "这里应该用〈以下〉。“上述”只回指前文，后面列出的原因要用“以下”，不能说“上述如下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很上述办法我们明天再试。", "corrected_sentence": "上述办法我们明天再试。", "error_description": "“很”不能修饰“上述”，“上述”是指代前文的区别词。应改为：“上述办法我们明天再试。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这上述办法需要三个人完成。", "corrected_sentence": "上述办法需要三个人完成。", "error_description": "“这”与“上述”不能同时修饰名词，指代前文时直接用“上述”。应改为：“上述办法需要三个人完成。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
