INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86439, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "他人是别的人，不是你自己。", "primary_collocate": null, "pronunciation": "tā rén", "ipa": "tʰa˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他人不是你，所以不会完全懂你。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做事时要想一想他人怎么看。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她愿意把机会让给他人。", "target_word": "他人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要用自己的想法要求他人。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他人的帮助让我走过了难关。", "target_word": "他人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱笑，也常常逗笑他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请不要打扰他人休息。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们不能只想自己，不顾他人。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他人说什么，你不用都放在心上。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们要理解他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "他人：与自己相对的别的人，如理解他人、打扰他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "“他人”指与自己相对的别人，作主语，符合“不是你”的语境。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：「哪儿」问处所，不指人，不能作“懂你”的主语。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，不指人，无法说明“不是你”。"}], "explanations": {"他人": "“他人”指与自己相对的别人，作主语，符合“不是你”的语境。", "谁": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。", "哪儿": "语义：「哪儿」问处所，不指人，不能作“懂你”的主语。", "什么": "语义：“什么”是疑问代词，不指人，无法说明“不是你”。"}, "sentence_index": 0, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天特别累，他人想早点睡觉。", "explanation": "这里指说话的人自己，应用〈自己〉，不能用〈他人〉。“他人”指自己以外的人。"}, {"text": "她是我最亲的他人。", "explanation": "这里应该用〈亲人〉。“他人”泛指自己以外的人，不用于形容最亲近的家人。"}, {"text": "这个杯子很漂亮，我很喜欢他人。", "explanation": "这里应该用〈它〉。“他人”只指人，不指物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "“他人”指别人，与“打扰……休息”搭配，符合句意。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“打扰自己休息”自相矛盾，“自己”不是需要安静的被打扰者。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。"}, {"text": "这些", "is_correct": false, "explanation": "搭配：“打扰”的对象应是具体的人，“这些”没有明确所指。"}], "explanations": {"他人": "“他人”指别人，与“打扰……休息”搭配，符合句意。", "自己": "语义：“打扰自己休息”自相矛盾，“自己”不是需要安静的被打扰者。", "谁": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。", "这些": "搭配：“打扰”的对象应是具体的人，“这些”没有明确所指。"}, "sentence_index": 6, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他人，麻烦你帮我拿一下书。", "explanation": "这里是直接称呼对方，应用〈同学〉〈师傅〉等称呼。“他人”泛指自己以外的别人，不能用来称呼面前的人。"}, {"text": "李阿姨刚打来电话，他人说今天不过来了。", "explanation": "这里应该用〈她〉。“他人”泛指别人，不用来指刚提到的某位女性。"}, {"text": "那个孩子很懂事，他人从不让大人操心。", "explanation": "这里应该用〈他〉。“他人”泛指别人，不用来指已经提到的那个孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不应该用自己的标准评价他人们。", "corrected_sentence": "我们不应该用自己的标准评价他人。", "error_description": "“他人”已是复数的泛指，后面不能再加“们”，应说“评价他人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该尊重这个他人的选择。", "corrected_sentence": "我们应该尊重他人的选择。", "error_description": "“他人”是代词，前面不能用“这个”修饰，应说“他人的选择”，不能说“这个他人的选择”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
