INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "别人；其他的人。", "primary_collocate": null, "pronunciation": "tā rén", "ipa": "tʰa˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我们要学会尊重他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不要随便打听他人的事。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很少谈论他人的缺点。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "帮助他人会让人觉得快乐。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她总是先考虑他人的感受。", "target_word": "他人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事不能怪他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别把自己的错误推给他人。", "target_word": "他人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不抢他人的东西。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该多关心他人。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他人的看法有时很有用。", "target_word": "他人", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "他人：指自己以外的别人，常见于书面语，如尊重他人、关心他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "“他人”指自己以外的别人，与“尊重”搭配，符合句意。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指说话人这一方，而“尊重”的对象应是别人，二者冲突。"}, {"text": "哪里", "is_correct": false, "explanation": "搭配：“尊重”的对象应是人，“哪里”指处所，不能作“尊重”的对象。"}], "explanations": {"他人": "“他人”指自己以外的别人，与“尊重”搭配，符合句意。", "谁": "语义：“谁”是疑问代词，这里是陈述句，不能指泛指的别人。", "我们": "语义：“我们”指说话人这一方，而“尊重”的对象应是别人，二者冲突。", "哪里": "搭配：“尊重”的对象应是人，“哪里”指处所，不能作“尊重”的对象。"}, "sentence_index": 0, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你最近太累了，他人应该多休息。", "explanation": "这里指说话的对象本人，应用〈自己〉，不能用〈他人〉。“他人”指自己以外的别人，不指正在对话的人。"}, {"text": "这只猫很可爱，大家都很喜欢他人。", "explanation": "这里应该用〈它〉。“他人”只指人，不指动物。"}, {"text": "我今天有点累，他人想一个人待着。", "explanation": "这里指说话的人自己，应用〈自己〉，不能用〈他人〉。“他人”指自己以外的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "“他人”指别的人，与“推给”搭配，符合句意。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“推给自己”与“自己的错误”自相矛盾，“自己”不能接收错误。"}, {"text": "哪里", "is_correct": false, "explanation": "搭配：“推给”的对象应是人，“哪里”指处所，不能接收错误。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，不指人，与“推给”的对象不符。"}], "explanations": {"他人": "“他人”指别的人，与“推给”搭配，符合句意。", "自己": "语义：“推给自己”与“自己的错误”自相矛盾，“自己”不能接收错误。", "哪里": "搭配：“推给”的对象应是人，“哪里”指处所，不能接收错误。", "什么": "语义：“什么”是疑问代词，不指人，与“推给”的对象不符。"}, "sentence_index": 6, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他人，麻烦你把门关一下。", "explanation": "这里是直接称呼对方，应用〈同学〉〈先生〉等称呼。“他人”泛指自己以外的别人，不能用来称呼面前的人。"}, {"text": "张老师刚打来电话，他人说会晚一点到。", "explanation": "这里应该用〈他〉。“他人”泛指自己以外的别人，不用来指刚提到的某个人。"}, {"text": "那位同学很聪明，他人经常帮我讲题。", "explanation": "这里应该用〈他〉。“他人”泛指别人，不用来指已经提到的那位同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不应该议论他人们的私事。", "corrected_sentence": "我们不应该议论他人的私事。", "error_description": "“他人”本身已表示“别人”，不能再加“们”，应说“他人的私事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该听取一个他人的意见。", "corrected_sentence": "我们应该听取他人的意见。", "error_description": "“他人”是代词，不能直接与数量短语“一个”组合修饰名词，应说“他人的意见”，不能说“一个他人的意见”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
