INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86441, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "供是把东西给别人用。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "这个房间供客人休息。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的长椅供散步的人坐。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书供学生免费借阅。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的小桌子供客人写字。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的草地供游客野餐。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的操场晚上供市民锻炼。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些雨伞供下雨天的路人使用。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的小房子供爬山的人避雨。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站的热水供旅客免费喝。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块空地供孩子们玩球。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提供", "label": "复合词"}, {"form": "供给", "label": "复合词"}], "register": "中性", "sense_fingerprint": "供：把场所或物品拿出来给别人使用，常说“供……使用／休息”。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86441, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "供", "is_correct": true, "explanation": "正确答案：供（gōng），意思是把东西拿出来给别人使用。"}, {"text": "共", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是共同。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱（如拱手、拱桥）。"}, {"text": "空", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（k 与 g），意思是空。"}, {"text": "耕", "is_correct": false, "explanation": "gēng 与 gōng 韵母不同（e 与 o），意思是耕种。"}, {"text": "轰", "is_correct": false, "explanation": "hōng 与 gōng 声母不同（h 与 g），意思是轰隆。"}], "explanations": {"供": "正确答案：供（gōng），意思是把东西拿出来给别人使用。", "共": "gòng（第四声）与 gōng（第一声）声调不同，意思是共同。", "拱": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱（如拱手、拱桥）。", "空": "kōng 与 gōng 声母不同（k 与 g），意思是空。", "耕": "gēng 与 gōng 韵母不同（e 与 o），意思是耕种。", "轰": "hōng 与 gōng 声母不同（h 与 g），意思是轰隆。"}, "sentence_index": null, "correct_answer": "供"}, "level_3": {"options": [{"text": "供", "is_correct": true, "explanation": "正确：供是提供、让人使用，“供客人休息”符合句意。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指有偿转让，与“供客人休息”的无偿提供不符。"}, {"text": "借", "is_correct": false, "explanation": "搭配：“借”要带借出的物品或借入的人，“借客人休息”不成立。"}, {"text": "租", "is_correct": false, "explanation": "配价：“租”要说“租给”才能带接受者，不能直接说“租客人休息”。"}], "explanations": {"供": "正确：供是提供、让人使用，“供客人休息”符合句意。", "卖": "语义：“卖”指有偿转让，与“供客人休息”的无偿提供不符。", "借": "搭配：“借”要带借出的物品或借入的人，“借客人休息”不成立。", "租": "配价：“租”要说“租给”才能带接受者，不能直接说“租客人休息”。"}, "sentence_index": 0, "correct_answer": "供"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我供他一个好消息。", "explanation": "这里应该用〈告诉〉。供指把东西拿出来让人使用，消息不能像物品那样供人使用，应说“告诉他一个好消息”。"}, {"text": "我供他一个汉字。", "explanation": "这里应该用〈教〉。供指把物品拿出来给人使用，文字知识不能这样供给，应说“教他一个汉字”。"}, {"text": "他终于供出了一篇小说。", "explanation": "这里应该用〈写出〉。供出是招供、交代的意思，指说出罪行或同伙，不能用于写出作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86441, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "供", "is_correct": true, "explanation": "正确答案：供（gōng），意思是把东西拿出来给别人使用。"}, {"text": "贡", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。"}, {"text": "巩", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 gōng 声母不同（d 与 g），意思是东边。"}, {"text": "刚", "is_correct": false, "explanation": "gāng 与 gōng 韵母不同（a 与 o），意思是刚才。"}], "explanations": {"供": "正确答案：供（gōng），意思是把东西拿出来给别人使用。", "贡": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。", "巩": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。", "东": "dōng 与 gōng 声母不同（d 与 g），意思是东边。", "刚": "gāng 与 gōng 韵母不同（a 与 o），意思是刚才。"}, "sentence_index": null, "correct_answer": "供"}, "level_3": {"options": [{"text": "供", "is_correct": true, "explanation": "正确：供是提供、让人使用，“供路人使用”符合句意。"}, {"text": "收", "is_correct": false, "explanation": "语义：“收”是收取，与“供路人使用”的意思相反。"}, {"text": "赔", "is_correct": false, "explanation": "语义：“赔”指赔偿，与“雨伞供路人使用”无关。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象要能被拆开，“拆路人使用”搭配不通。"}], "explanations": {"供": "正确：供是提供、让人使用，“供路人使用”符合句意。", "收": "语义：“收”是收取，与“供路人使用”的意思相反。", "赔": "语义：“赔”指赔偿，与“雨伞供路人使用”无关。", "拆": "搭配：“拆”的对象要能被拆开，“拆路人使用”搭配不通。"}, "sentence_index": 6, "correct_answer": "供"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈供我一个拥抱。", "explanation": "这里应该用〈给〉。供指提供物资或服务让人使用，拥抱不能像物品一样供给，应说“给我一个拥抱”。"}, {"text": "爸爸供我一条围巾。", "explanation": "这里应该用〈送〉。供指把场所或物品拿出来让人使用，不用于私人赠送衣物。"}, {"text": "同学供他一本书。", "explanation": "这里应该用〈赠〉。供用于公共提供或使用，不用于同学之间的个人赠送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些长椅供在路人休息。", "corrected_sentence": "这些长椅供路人休息。", "error_description": "错误：“供”后多加了“在”，“供在”指供奉、摆放在某处，与“供路人休息”的意思不符。正确：应去掉“在”，写作“供路人休息”，“路人”是“供”的受益对象，应放在“供”之后作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些车位供得住户停车。", "corrected_sentence": "这些车位供住户停车。", "error_description": "错误：“供”后多加了“得”，“供得”需要补语（如“供得起”）才能带宾语，“供得住户停车”不成立。正确：去掉“得”，写作“供住户停车”，“住户”是“供”的受益对象，应放在“供”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
