INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86442, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "供给；提供。", "primary_collocate": null, "pronunciation": "gōng", "ipa": "kʊŋ˥", "syllable_count": 1, "sentences": [{"text": "这个水库供全城的人用水。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的泉水供村民喝了很多年。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家牛奶厂供学校的孩子喝牛奶。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能板供小房子用电。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水供两岸的农民浇地。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口井供三个村子的人饮用。", "target_word": "供", "complexity_tier": "T3", "furigana": "zhè kǒu jǐng gōng sān ge cūnzi de rén yǐnyòng", "sentence_source": "generated"}, {"text": "这家餐厅供员工免费吃午饭。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的食堂供学生吃三顿饭。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司供每位新同事用一台电脑。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管子供大楼里的人用热水。", "target_word": "供", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提供", "label": "复合词"}, {"form": "供给", "label": "复合词"}], "register": "中性", "sense_fingerprint": "供：供给水、电、饭、用品等，满足人们的需要。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851174ca-2114-4551-bf43-9f2fc3ac5b77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "供", "is_correct": true, "explanation": "正确答案：供（gōng），意思是供给，满足人们的需要。"}, {"text": "贡", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。"}, {"text": "拱", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱（如拱手、拱桥）。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 gōng 声母不同（d 与 g），意思是东边。"}, {"text": "耕", "is_correct": false, "explanation": "gēng 与 gōng 韵母不同（e 与 o），意思是耕种。"}], "explanations": {"供": "正确答案：供（gōng），意思是供给，满足人们的需要。", "贡": "gòng（第四声）与 gōng（第一声）声调不同，意思是贡献。", "拱": "gǒng（第三声）与 gōng（第一声）声调不同，意思是拱（如拱手、拱桥）。", "东": "dōng 与 gōng 声母不同（d 与 g），意思是东边。", "耕": "gēng 与 gōng 韵母不同（e 与 o），意思是耕种。"}, "sentence_index": null, "correct_answer": "供"}, "level_3": {"options": [{"text": "供", "is_correct": true, "explanation": "正确：供是供给、提供，“水库供全城的人用水”符合句意。"}, {"text": "抽", "is_correct": false, "explanation": "搭配：“抽”指抽取液体，不能带“全城的人”作宾语，搭配不通。"}, {"text": "占", "is_correct": false, "explanation": "语义：“占”指占据，与“水库为全城供水”的意思不符。"}, {"text": "收", "is_correct": false, "explanation": "语义：“收”指收取，与“水库给人供水”的意思不合。"}], "explanations": {"供": "正确：供是供给、提供，“水库供全城的人用水”符合句意。", "抽": "搭配：“抽”指抽取液体，不能带“全城的人”作宾语，搭配不通。", "占": "语义：“占”指占据，与“水库为全城供水”的意思不符。", "收": "语义：“收”指收取，与“水库给人供水”的意思不合。"}, "sentence_index": 0, "correct_answer": "供"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我供她一个笑脸。", "explanation": "这里应该用〈给〉。供表示提供物资或服务让人使用，笑脸不能像物品一样供应，应说“给她一个笑脸”。"}, {"text": "他供我一个吻。", "explanation": "这里应该用〈给〉。供表示提供物资或服务让人使用，吻不能像物品一样供给，应说“给我一个吻”。"}, {"text": "他在花园里供了一棵树。", "explanation": "这里应该用〈种〉。供表示提供物资让人使用，不用于栽种植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86442, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "供", "is_correct": true, "explanation": "正确答案：供（gōng），意思是供给，满足人们的需要。"}, {"text": "共", "is_correct": false, "explanation": "gòng（第四声）与 gōng（第一声）声调不同，意思是共同。"}, {"text": "巩", "is_correct": false, "explanation": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。"}, {"text": "空", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（k 与 g），意思是空。"}, {"text": "刚", "is_correct": false, "explanation": "gāng 与 gōng 韵母不同（a 与 o），意思是刚才。"}], "explanations": {"供": "正确答案：供（gōng），意思是供给，满足人们的需要。", "共": "gòng（第四声）与 gōng（第一声）声调不同，意思是共同。", "巩": "gǒng（第三声）与 gōng（第一声）声调不同，意思是巩固。", "空": "kōng 与 gōng 声母不同（k 与 g），意思是空。", "刚": "gāng 与 gōng 韵母不同（a 与 o），意思是刚才。"}, "sentence_index": null, "correct_answer": "供"}, "level_3": {"options": [{"text": "供", "is_correct": true, "explanation": "正确：供是供给、提供，“餐厅供员工免费吃午饭”符合句意。"}, {"text": "罚", "is_correct": false, "explanation": "语义：“罚”是处罚，与“免费吃午饭”的意思相悖。"}, {"text": "赔", "is_correct": false, "explanation": "搭配：“赔”后面不接“吃午饭”这类供应性的动作，搭配不通。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“餐厅供员工吃饭”的意思不符。"}], "explanations": {"供": "正确：供是供给、提供，“餐厅供员工免费吃午饭”符合句意。", "罚": "语义：“罚”是处罚，与“免费吃午饭”的意思相悖。", "赔": "搭配：“赔”后面不接“吃午饭”这类供应性的动作，搭配不通。", "偷": "语义：“偷”是窃取，与“餐厅供员工吃饭”的意思不符。"}, "sentence_index": 6, "correct_answer": "供"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷供我一个道理。", "explanation": "这里应该用〈教〉。供表示提供物资，道理不能像物品一样供给，应说“教我一个道理”。"}, {"text": "朋友供我一张电影票。", "explanation": "这里应该用〈送〉。供指提供物品让人使用，不用于朋友之间的个人赠票。"}, {"text": "老师供我一个笑话。", "explanation": "这里应该用〈讲〉。供指提供物资，笑话不能像物品一样供给，应说“给我讲一个笑话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公园供在游客免费使用厕所。", "corrected_sentence": "这座公园供游客免费使用厕所。", "error_description": "错误：“供”后多加了“在”，“供在”指供奉、摆放在某处，与“供游客免费使用厕所”的意思不符。正确：应去掉“在”，写作“供游客免费使用厕所”，“游客”是“供”的受益对象，应放在“供”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学供得学生免费住宿。", "corrected_sentence": "这所大学供学生免费住宿。", "error_description": "错误：“供”后多加了“得”，“供得”需要补语（如“供得起”）才能带宾语，“供得学生免费住宿”不成立。正确：去掉“得”，写作“供学生免费住宿”，“学生”是“供”的受益对象，应放在“供”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '711ec6d4-218e-455b-9b09-3ea66234cce2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，与「古代」的时间概念没有对立关系。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是材料名词，与「古代」没有反义关系。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是职业名词，与「古代」没有反义关系。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "太阳": "语义：太阳是天体，与「古代」的时间概念没有对立关系。", "玻璃": "语义：玻璃是材料名词，与「古代」没有反义关系。", "老师": "语义：老师是职业名词，与「古代」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是地理事物，与「古代」不构成反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，与时间概念「古代」没有对立关系。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是职业名词，与「古代」没有反义关系。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "海洋": "语义：海洋是地理事物，与「古代」不构成反义关系。", "书包": "语义：书包是物品，与时间概念「古代」没有对立关系。", "医生": "语义：医生是职业名词，与「古代」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "古代是很久很久以前。", "primary_collocate": null, "pronunciation": "gǔ dài", "ipa": "ku˨˩˦ tai˥˩", "syllable_count": 2, "sentences": [{"text": "古代没有手机，人们写信。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一件古代的衣服。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的夏天没有空调。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在古代，女孩子很少上学。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的城市比现在小得多。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲古代的英雄。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的人怎么过春节？", "target_word": "古代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是古代的生活。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的人看月亮，想起远方的家人。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学里学习古代文学。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "古代人", "label": "复合"}, {"form": "古代史", "label": "复合"}], "register": "中性", "sense_fingerprint": "很久很久以前的时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：很久很久以前的时代，「古代没有手机，人们写信」符合句意。"}, {"text": "现代", "is_correct": false, "explanation": "语义：现代有手机，「现代没有手机，人们写信」与常识相矛盾。"}, {"text": "当代", "is_correct": false, "explanation": "语义：「当代」指现在这个时代，现在有手机，「当代没有手机」与常识相矛盾。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市通常都有手机和通信设施，「城市没有手机」与常识不符。"}], "explanations": {"古代": "古代：很久很久以前的时代，「古代没有手机，人们写信」符合句意。", "现代": "语义：现代有手机，「现代没有手机，人们写信」与常识相矛盾。", "当代": "语义：「当代」指现在这个时代，现在有手机，「当代没有手机」与常识相矛盾。", "城市": "语义：城市通常都有手机和通信设施，「城市没有手机」与常识不符。"}, "sentence_index": 0, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我古代很喜欢踢足球。", "explanation": "这里应该用〈小时候〉。古代指很久以前的历史时期，不能用来指个人的童年。"}, {"text": "我昨天在古代吃了午饭。", "explanation": "这里应该用〈家里〉。古代是很久以前的时期，不是地点，也不能用来说昨天发生的事。"}, {"text": "我古代住过北京。", "explanation": "这里应该用〈以前〉。古代指遥远的历史时期，讲自己的经历要用以前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：很久很久以前的时代，「古代的人怎么过春节」符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：「数学」不能修饰「人」指一类人，「数学的人」不成立。"}, {"text": "大海", "is_correct": false, "explanation": "语义：「大海的人」不能指一类人，句子无法理解为某个时代的人。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「星期」是时间单位，不能作「人」的修饰语。"}], "explanations": {"古代": "古代：很久很久以前的时代，「古代的人怎么过春节」符合句意。", "数学": "搭配：「数学」不能修饰「人」指一类人，「数学的人」不成立。", "大海": "语义：「大海的人」不能指一类人，句子无法理解为某个时代的人。", "星期": "搭配：「星期」是时间单位，不能作「人」的修饰语。"}, "sentence_index": 6, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的古代比较便宜。", "explanation": "这里应该用〈商品〉。古代是时期名词，不能描述价格；说商品便宜要用具体的事物作主语。"}, {"text": "窗台上摆着一个古代。", "explanation": "这里应该用〈花瓶〉。古代是时间概念，不能当作可以摆在窗台上、用「个」计数的具体物品。"}, {"text": "我把古代带回了家。", "explanation": "这里应该用〈纪念品〉。古代是时间概念，不能被拿着带回家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在博物馆看到了古代的的瓷器。", "corrected_sentence": "我在博物馆看到了古代的瓷器。", "error_description": "错误形式：「古代的的瓷器」；正确形式：「古代的瓷器」。「古代」作定语，「的」只用一次，多写一个「的」就不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书讲的是古代的的战争。", "corrected_sentence": "这本书讲的是古代的战争。", "error_description": "错误形式：「古代的的战争」；正确形式：「古代的战争」。「古代」作定语，「的」只用一次，多写一个「的」就不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，与「古代」没有反义关系。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是一个季节，与历史时代不构成反义关系。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是地点名词，与「古代」的时间概念不对应。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "桌子": "语义：桌子是家具，与「古代」没有反义关系。", "春天": "语义：春天是一个季节，与历史时代不构成反义关系。", "学校": "语义：学校是地点名词，与「古代」的时间概念不对应。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现代", "is_correct": true, "explanation": "现代：与「古代」相对的时代，二者是反义词。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是地理事物，与「古代」不构成反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，与时间概念「古代」没有对立关系。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是职业名词，与「古代」没有反义关系。"}], "correct_answer": "现代", "explanations": {"现代": "现代：与「古代」相对的时代，二者是反义词。", "海洋": "语义：海洋是地理事物，与「古代」不构成反义关系。", "书包": "语义：书包是物品，与时间概念「古代」没有对立关系。", "医生": "语义：医生是职业名词，与「古代」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去距离现代较远的时代。", "primary_collocate": null, "pronunciation": "gǔ dài", "ipa": "ku˨˩˦ tai˥˩", "syllable_count": 2, "sentences": [{"text": "古代的人没有电灯。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "古代的孩子也要读书。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥是古代留下来的。", "target_word": "古代", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢看讲古代故事的电影。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在古代，皇帝住在很大的宫殿里。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代没有汽车，人们骑马出门。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里有很多古代的钱。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的医生用草药给人看病。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷对古代的历史很感兴趣。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代的路不好走，坐车要很多天。", "target_word": "古代", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "古代人", "label": "复合"}, {"form": "古代史", "label": "复合"}], "register": "中性", "sense_fingerprint": "距离现代很远的过去时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去距离现代较远的时代，符合句意：古时候的人没有电灯。"}, {"text": "现代", "is_correct": false, "explanation": "语义：现代指当今时代，「现代的人没有电灯」与事实相矛盾。"}, {"text": "当代", "is_correct": false, "explanation": "语义：「当代」指现在这个时代，现在的人都用电灯，「当代的人没有电灯」与事实相矛盾。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市的人通常都用电灯，「城市的人没有电灯」与常识相矛盾。"}], "explanations": {"古代": "古代：过去距离现代较远的时代，符合句意：古时候的人没有电灯。", "现代": "语义：现代指当今时代，「现代的人没有电灯」与事实相矛盾。", "当代": "语义：「当代」指现在这个时代，现在的人都用电灯，「当代的人没有电灯」与事实相矛盾。", "城市": "语义：城市的人通常都用电灯，「城市的人没有电灯」与常识相矛盾。"}, "sentence_index": 0, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我古代是老师。", "explanation": "这里应该用〈从前〉。古代指很久以前的时期，不能用来说自己曾经担任的身份。"}, {"text": "我今天在古代开了会。", "explanation": "这里应该用〈公司〉。古代是很久以前的时期，不是地点，也不能用来说今天的事。"}, {"text": "我古代在北京工作过。", "explanation": "这里应该用〈曾经〉。古代指遥远的历史时期，讲个人经历的时间要用曾经。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "古代", "is_correct": true, "explanation": "古代：过去很久远的时代，「博物馆里有很多古代的钱」指古代的钱币，符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：「数学」不能修饰「钱」，「数学的钱」无法成立。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「星期」是时间单位，不能作「钱」的修饰语。"}, {"text": "春天", "is_correct": false, "explanation": "语义：「春天的钱」没有实际所指，与博物馆陈列的情境不符。"}], "explanations": {"古代": "古代：过去很久远的时代，「博物馆里有很多古代的钱」指古代的钱币，符合句意。", "数学": "搭配：「数学」不能修饰「钱」，「数学的钱」无法成立。", "星期": "搭配：「星期」是时间单位，不能作「钱」的修饰语。", "春天": "语义：「春天的钱」没有实际所指，与博物馆陈列的情境不符。"}, "sentence_index": 6, "correct_answer": "古代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室的古代很大。", "explanation": "这里应该用〈空间〉。古代是时期名词，不能用来描述教室的大小。"}, {"text": "我的书包里有一个古代。", "explanation": "这里应该用〈铅笔〉。古代是时间概念，不能当作可以放进书包、用「个」计数的具体物品。"}, {"text": "他把古代放进了冰箱。", "explanation": "这里应该用〈牛奶〉。古代是时间概念，不是能放进冰箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
