INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86445, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "笑", "is_correct": true, "explanation": "“笑”与“哭”相反，指高兴时发出声音或露出笑容。"}, {"text": "说", "is_correct": false, "explanation": "与“哭”没有反义关系，“说”指用语言表达。"}, {"text": "跑", "is_correct": false, "explanation": "与“哭”没有反义关系，“跑”指快速移动。"}, {"text": "吃", "is_correct": false, "explanation": "与“哭”没有反义关系，“吃”指把食物咽下。"}], "correct_answer": "笑", "explanations": {"笑": "“笑”与“哭”相反，指高兴时发出声音或露出笑容。", "说": "与“哭”没有反义关系，“说”指用语言表达。", "跑": "与“哭”没有反义关系，“跑”指快速移动。", "吃": "与“哭”没有反义关系，“吃”指把食物咽下。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
