INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86445, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "哭是难过或疼的时候，眼睛流出眼泪。", "primary_collocate": null, "pronunciation": "kū", "ipa": "kʰu˥", "syllable_count": 1, "sentences": [{"text": "孩子摔倒了，疼得哭了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想妈妈，一直在哭。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了那封信，难过地哭了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别哭，我给你买糖。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不见了，弟弟哭了一晚上。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝一摔跤就会哭。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手很疼，忍不住哭起来。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着跑回了家。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想哭，可是眼泪流下来了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的玩具坏了，她哭得很伤心。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哭了", "label": "体标"}, {"form": "哭着", "label": "体标"}, {"form": "哭泣", "label": "复合"}, {"form": "大哭", "label": "复合"}], "register": "中性", "sense_fingerprint": "因难过或疼痛而流眼泪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86445, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哭", "is_correct": true, "explanation": "kū（第一声），动词，因难过或疼痛而流眼泪。"}, {"text": "苦", "is_correct": false, "explanation": "kǔ（第三声）与 kū（第一声）声调不同，意思是“苦”。"}, {"text": "姑", "is_correct": false, "explanation": "gū（第一声）与 kū 声母不同（g 与 k），意思是“姑姑”。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 kū 声母不同（h 与 k），意思是“呼喊”。"}], "explanations": {"哭": "kū（第一声），动词，因难过或疼痛而流眼泪。", "苦": "kǔ（第三声）与 kū（第一声）声调不同，意思是“苦”。", "姑": "gū（第一声）与 kū 声母不同（g 与 k），意思是“姑姑”。", "呼": "hū（第一声）与 kū 声母不同（h 与 k），意思是“呼喊”。"}, "sentence_index": null, "correct_answer": "哭"}, "level_3": {"options": [{"text": "哭", "is_correct": true, "explanation": "动词，表示疼痛时流眼泪，与“疼得”搭配，句意通顺。"}, {"text": "笑", "is_correct": false, "explanation": "语义：疼得厉害时不会“笑”，“疼得”与“笑”的状态矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示唱歌，与“疼得”所描述的状态不相符。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“疼得”后接的是痛苦的表现，“读”不能表示疼痛的表现。"}], "explanations": {"哭": "动词，表示疼痛时流眼泪，与“疼得”搭配，句意通顺。", "笑": "语义：疼得厉害时不会“笑”，“疼得”与“笑”的状态矛盾。", "唱": "语义：“唱”表示唱歌，与“疼得”所描述的状态不相符。", "读": "搭配：“疼得”后接的是痛苦的表现，“读”不能表示疼痛的表现。"}, "sentence_index": 0, "correct_answer": "哭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她哭了一个电话。", "explanation": "这里应该用〈打〉。“哭”不能带“电话”作宾语，表示打电话要说“打了一个电话”。"}, {"text": "他哭了一个苹果。", "explanation": "这里应该用〈吃〉。“哭”不能带“苹果”作宾语，表示吃东西要说“吃了一个苹果”。"}, {"text": "她哭了一顿饭。", "explanation": "这里应该用〈吃〉。“哭”不能与“饭”搭配，应说“吃了一顿饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86445, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哭", "is_correct": true, "explanation": "kū（第一声），动词，因难过或疼痛而流眼泪。"}, {"text": "裤", "is_correct": false, "explanation": "kù（第四声）与 kū 声调不同，意思是“裤子”。"}, {"text": "库", "is_correct": false, "explanation": "kù（第四声）与 kū 声调不同，意思是“仓库”。"}, {"text": "估", "is_correct": false, "explanation": "gū（第一声）与 kū 声母不同（g 与 k），意思是“估计”。"}], "explanations": {"哭": "kū（第一声），动词，因难过或疼痛而流眼泪。", "裤": "kù（第四声）与 kū 声调不同，意思是“裤子”。", "库": "kù（第四声）与 kū 声调不同，意思是“仓库”。", "估": "gū（第一声）与 kū 声母不同（g 与 k），意思是“估计”。"}, "sentence_index": null, "correct_answer": "哭"}, "level_3": {"options": [{"text": "哭", "is_correct": true, "explanation": "动词，表示疼痛时忍不住流眼泪，与“忍不住”搭配，句意通顺。"}, {"text": "玩", "is_correct": false, "explanation": "语义：手很疼的时候不会“玩起来”，与“很疼”的状态矛盾。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”需要水或游泳的场所，与“手很疼”没有搭配关系。"}, {"text": "写", "is_correct": false, "explanation": "语义：手很疼的时候“写”不合情理，与“忍不住”后面的动作矛盾。"}], "explanations": {"哭": "动词，表示疼痛时忍不住流眼泪，与“忍不住”搭配，句意通顺。", "玩": "语义：手很疼的时候不会“玩起来”，与“很疼”的状态矛盾。", "游": "搭配：“游”需要水或游泳的场所，与“手很疼”没有搭配关系。", "写": "语义：手很疼的时候“写”不合情理，与“忍不住”后面的动作矛盾。"}, "sentence_index": 6, "correct_answer": "哭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她哭了一口气。", "explanation": "这里应该用〈叹〉。“哭”不能带“气”作宾语，表示叹气要说“叹了一口气”。"}, {"text": "她在哭游戏。", "explanation": "这里应该用〈玩〉。“哭”不能带“游戏”作宾语，表示做游戏要说“玩游戏”。"}, {"text": "她哭了一句话。", "explanation": "这里应该用〈说〉。“哭”不能带“话”作宾语，表示开口讲话要说“说了一句话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她听到这个消息，哭很伤心。", "corrected_sentence": "她听到这个消息，哭得很伤心。", "error_description": "“哭”后面描述程度要用补语“得”，应说“哭得很伤心”；漏掉“得”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
