INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因悲伤或激动而流泪出声。", "primary_collocate": null, "pronunciation": "kū", "ipa": "kʰu˥", "syllable_count": 1, "sentences": [{"text": "听到好消息，她激动得哭了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的结尾让很多人哭了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看到我回家，高兴得哭了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人听到这个消息，大声哭起来。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭出了声，大家都安静了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业那天，同学们抱在一起哭。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了，队员们又哭又笑。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哭得说不出话来。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听了这首歌，忍不住哭了。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边哭，一边大声叫妈妈。", "target_word": "哭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哭了", "label": "体标"}, {"form": "哭着", "label": "体标"}, {"form": "哭泣", "label": "复合"}, {"form": "大哭", "label": "复合"}], "register": "中性", "sense_fingerprint": "因悲伤或激动而流泪并发出声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哭", "is_correct": true, "explanation": "kū（第一声），动词，因悲伤或激动而流泪并发出声音。"}, {"text": "苦", "is_correct": false, "explanation": "kǔ（第三声）与 kū（第一声）声调不同，意思是“苦”。"}, {"text": "估", "is_correct": false, "explanation": "gū（第一声）与 kū 声母不同（g 与 k），意思是“估计”。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 kū 声母不同（h 与 k），意思是“呼喊”。"}], "explanations": {"哭": "kū（第一声），动词，因悲伤或激动而流泪并发出声音。", "苦": "kǔ（第三声）与 kū（第一声）声调不同，意思是“苦”。", "估": "gū（第一声）与 kū 声母不同（g 与 k），意思是“估计”。", "呼": "hū（第一声）与 kū 声母不同（h 与 k），意思是“呼喊”。"}, "sentence_index": null, "correct_answer": "哭"}, "level_3": {"options": [{"text": "哭", "is_correct": true, "explanation": "动词，表示激动时流泪，与“激动得”搭配，句意通顺。"}, {"text": "考", "is_correct": false, "explanation": "搭配：“考”指考试，“激动得”后接的是情绪状态，不能说“激动得考了”。"}, {"text": "算", "is_correct": false, "explanation": "语义：“算”表示计算，与“激动”的情绪不相关，句子不通。"}, {"text": "扫", "is_correct": false, "explanation": "语义：“扫”表示打扫，与“激动”的情绪不相符，不能说“激动得扫了”。"}], "explanations": {"哭": "动词，表示激动时流泪，与“激动得”搭配，句意通顺。", "考": "搭配：“考”指考试，“激动得”后接的是情绪状态，不能说“激动得考了”。", "算": "语义：“算”表示计算，与“激动”的情绪不相关，句子不通。", "扫": "语义：“扫”表示打扫，与“激动”的情绪不相符，不能说“激动得扫了”。"}, "sentence_index": 0, "correct_answer": "哭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她哭了一首歌。", "explanation": "这里应该用〈唱〉。“哭”不能带“歌”作宾语，表示唱歌要说“唱了一首歌”。"}, {"text": "他哭了一杯水。", "explanation": "这里应该用〈喝〉。“哭”不能带“水”作宾语，表示喝水要说“喝了一杯水”。"}, {"text": "妈妈哭了一封信。", "explanation": "这里应该用〈写〉。“哭”不能带“信”作宾语，表示写信要说“写了一封信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哭", "is_correct": true, "explanation": "kū（第一声），动词，因悲伤或激动而流泪并发出声音。"}, {"text": "裤", "is_correct": false, "explanation": "kù（第四声）与 kū 声调不同，意思是“裤子”。"}, {"text": "库", "is_correct": false, "explanation": "kù（第四声）与 kū 声调不同，意思是“仓库”。"}, {"text": "姑", "is_correct": false, "explanation": "gū（第一声）与 kū 声母不同（g 与 k），意思是“姑姑”。"}], "explanations": {"哭": "kū（第一声），动词，因悲伤或激动而流泪并发出声音。", "裤": "kù（第四声）与 kū 声调不同，意思是“裤子”。", "库": "kù（第四声）与 kū 声调不同，意思是“仓库”。", "姑": "gū（第一声）与 kū 声母不同（g 与 k），意思是“姑姑”。"}, "sentence_index": null, "correct_answer": "哭"}, "level_3": {"options": [{"text": "哭", "is_correct": true, "explanation": "动词，表示比赛获胜后激动得流泪，与“又……又笑”搭配，句意通顺。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“又睡又笑”不符合“比赛赢了”的情景，两者不能并列。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”指修理，与“笑”并列表示情绪时，搭配不通。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”指购买东西，与“笑”并列不能表示“比赛赢了”时的激动情绪。"}], "explanations": {"哭": "动词，表示比赛获胜后激动得流泪，与“又……又笑”搭配，句意通顺。", "睡": "语义：“又睡又笑”不符合“比赛赢了”的情景，两者不能并列。", "修": "搭配：“修”指修理，与“笑”并列表示情绪时，搭配不通。", "买": "语义：“买”指购买东西，与“笑”并列不能表示“比赛赢了”时的激动情绪。"}, "sentence_index": 6, "correct_answer": "哭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她哭了一幅画。", "explanation": "这里应该用〈画〉。“哭”不能带“画”作宾语，表示画画要说“画了一幅画”。"}, {"text": "他哭了一件衣服。", "explanation": "这里应该用〈洗〉。“哭”不能带“衣服”作宾语，表示洗衣服要说“洗了一件衣服”。"}, {"text": "我哭了一本书。", "explanation": "这里应该用〈买〉。“哭”不能带“书”作宾语，表示买书要说“买了一本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她哭了着对我说了对不起。", "corrected_sentence": "她哭着对我说了对不起。", "error_description": "错误：“了”与“着”不能同时用在“哭”后；表示“哭”与“说”同时进行只用“着”。正确：应说“她哭着对我说了对不起。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子看见了妈妈，哭了来。", "corrected_sentence": "孩子看见了妈妈，哭了起来。", "error_description": "趋向补语“起来”不能只用“来”，应说“哭了起来”；漏掉“起”，“哭了来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
