INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86449, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "多次是做了很多次。", "primary_collocate": null, "pronunciation": "duō cì", "ipa": "tuɔ˥ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我多次去过那家饭馆。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他多次给我打电话。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师多次提醒我们要早睡。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我们多次讨论过。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈多次告诉我要小心。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她多次参加比赛，都得了奖。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我多次看过。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他多次帮助过邻居。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王多次迟到，老板很生气。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们多次见面，成了好朋友。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，放在动词前，表示动作重复了很多次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多次", "is_correct": true, "explanation": "“多次”读作 duō cì，意思是动作重复了很多次。"}, {"text": "毒刺", "is_correct": false, "explanation": "“毒刺”只改了第一个字的声调（dú 第二声，多 duō 第一声），意思是有毒的刺，与“多次”不同。"}, {"text": "多子", "is_correct": false, "explanation": "“子”（zǐ 第三声）与“次”声母和声调都不同，意思是孩子多。"}, {"text": "多吃", "is_correct": false, "explanation": "“吃”（chī 第一声）与“次”声母和声调都不同，意思是多吃东西。"}, {"text": "多日", "is_correct": false, "explanation": "“日”（rì）与“次”（cì）声母不同，声调相同，意思是很多天。"}, {"text": "多汁", "is_correct": false, "explanation": "“汁”（zhī 第一声）与“次”声母和声调都不同，意思是汁水多。"}], "explanations": {"多次": "“多次”读作 duō cì，意思是动作重复了很多次。", "毒刺": "“毒刺”只改了第一个字的声调（dú 第二声，多 duō 第一声），意思是有毒的刺，与“多次”不同。", "多子": "“子”（zǐ 第三声）与“次”声母和声调都不同，意思是孩子多。", "多吃": "“吃”（chī 第一声）与“次”声母和声调都不同，意思是多吃东西。", "多日": "“日”（rì）与“次”（cì）声母不同，声调相同，意思是很多天。", "多汁": "“汁”（zhī 第一声）与“次”声母和声调都不同，意思是汁水多。"}, "sentence_index": null, "correct_answer": "多次"}, "level_3": {"options": [{"text": "多次", "is_correct": true, "explanation": "“多次”表示动作重复了很多次，与“去过”的经历意思相合，正确。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰动词“去过”，句子不通。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情出乎意料地发生，与表示多次经历的“去过”意思冲突。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快就要发生，与表示过去经历的“去过”矛盾。"}], "explanations": {"多次": "“多次”表示动作重复了很多次，与“去过”的经历意思相合，正确。", "很": "语法：“很”是程度副词，不能直接修饰动词“去过”，句子不通。", "突然": "语义：“突然”表示事情出乎意料地发生，与表示多次经历的“去过”意思冲突。", "马上": "语义：“马上”表示很快就要发生，与表示过去经历的“去过”矛盾。"}, "sentence_index": 0, "correct_answer": "多次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我多次出生在北京。", "explanation": "“多次”表示同一动作反复发生，与〈一次〉相对。出生只能发生一次，不能用“多次”修饰。"}, {"text": "这是我第一次去北京，我已经多次去过北京了。", "explanation": "“多次”表示不止一次，与〈一次〉相对。前句说是第一次去，后句就不能再说“多次去过”，两者矛盾。"}, {"text": "这座塔多次落成于明朝。", "explanation": "“多次”表示反复发生，与〈一次〉相对。落成是一次性的事件，不能用“多次”修饰，应说“落成于明朝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多次", "is_correct": true, "explanation": "“多次”表示动作重复了很多次，与“看过”的经历意思相合，正确。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久不变，与“看过”这种过去的经历矛盾。"}, {"text": "赶快", "is_correct": false, "explanation": "搭配：“赶快”多用于催促尽快去做的动作，不能与“看过”这种已完成的经历搭配。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰动词“看过”，句子不通。"}], "explanations": {"多次": "“多次”表示动作重复了很多次，与“看过”的经历意思相合，正确。", "永远": "语义：“永远”表示长久不变，与“看过”这种过去的经历矛盾。", "赶快": "搭配：“赶快”多用于催促尽快去做的动作，不能与“看过”这种已完成的经历搭配。", "很": "语法：“很”是程度副词，不能直接修饰动词“看过”，句子不通。"}, "sentence_index": 6, "correct_answer": "多次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市多次位于山的东边。", "explanation": "“多次”表示反复发生，与〈一直〉相对。位于描述持续的位置状态，应说“一直位于山的东边”。"}, {"text": "他多次从未去过北京。", "explanation": "“多次”表示不止一次，与〈一次〉相对；“从未”表示一次也没有，两者互相矛盾，整句说不通。"}, {"text": "我多次认识了他。", "explanation": "“多次”表示反复发生，与〈一次〉相对。“认识”只发生一次，应说“认识了他”，不能用“多次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们多次数来我家做客。", "corrected_sentence": "他们多次来我家做客。", "error_description": "“次数”是名词，不能放在动词前作状语，副词应为“多次”。错误写法是“多次数来”，正确写法是“多次来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她多次了获得奖学金。", "corrected_sentence": "她多次获得奖学金。", "error_description": "“了”不能放在“多次”后面、动词前面。错误写法“多次了获得”，正确写法“多次获得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
