INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86450, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很多次；不止一次。", "primary_collocate": null, "pronunciation": "duō cì", "ipa": "tuɔ˥ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "医生多次说过，不能多吃糖。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家多次来过中国。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他多次想放弃，但是没有。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我多次问她，她都不说。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市多次下大雪。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们多次练习，终于唱好了。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理多次开会讨论这件事。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他多次拿到第一名。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我多次看见他在公园跑步。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟多次忘带钥匙。", "target_word": "多次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示次数不止一次，强调反复出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b96aba66-23c6-462e-9a51-8bc68210e6ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86450, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "多次", "is_correct": true, "explanation": "“多次”读作 duō cì，意思是很多次、不止一次。"}, {"text": "毒刺", "is_correct": false, "explanation": "“毒刺”只改了第一个字的声调（dú 第二声，多 duō 第一声），意思是有毒的刺，与“多次”不同。"}, {"text": "多子", "is_correct": false, "explanation": "“子”（zǐ 第三声）与“次”声母和声调都不同，意思是孩子多。"}, {"text": "多吃", "is_correct": false, "explanation": "“吃”（chī 第一声）与“次”声母和声调都不同，意思是多吃东西。"}, {"text": "多日", "is_correct": false, "explanation": "“日”（rì）与“次”（cì）声母不同，声调相同，意思是很多天。"}, {"text": "多汁", "is_correct": false, "explanation": "“汁”（zhī 第一声）与“次”声母和声调都不同，意思是汁水多。"}], "explanations": {"多次": "“多次”读作 duō cì，意思是很多次、不止一次。", "毒刺": "“毒刺”只改了第一个字的声调（dú 第二声，多 duō 第一声），意思是有毒的刺，与“多次”不同。", "多子": "“子”（zǐ 第三声）与“次”声母和声调都不同，意思是孩子多。", "多吃": "“吃”（chī 第一声）与“次”声母和声调都不同，意思是多吃东西。", "多日": "“日”（rì）与“次”（cì）声母不同，声调相同，意思是很多天。", "多汁": "“汁”（zhī 第一声）与“次”声母和声调都不同，意思是汁水多。"}, "sentence_index": null, "correct_answer": "多次"}, "level_3": {"options": [{"text": "多次", "is_correct": true, "explanation": "“多次”表示不止一次地说，与“说过”的反复经历相合，正确。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情出乎意料地发生，与“说过”的反复经历不符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示很快就要发生，与表示过去经历的“说过”矛盾。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与“不”“没”连用，这里不能直接说“根本说过”。"}], "explanations": {"多次": "“多次”表示不止一次地说，与“说过”的反复经历相合，正确。", "突然": "语义：“突然”表示事情出乎意料地发生，与“说过”的反复经历不符。", "马上": "语义：“马上”表示很快就要发生，与表示过去经历的“说过”矛盾。", "根本": "搭配：“根本”通常与“不”“没”连用，这里不能直接说“根本说过”。"}, "sentence_index": 0, "correct_answer": "多次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥多次建成于1990年。", "explanation": "“多次”表示反复发生，与〈一次〉相对。“建成”是一次性的事件，应说“1990年建成”。"}, {"text": "这是我第一次见他，我们已经多次见过面了。", "explanation": "“多次”表示不止一次，与〈一次〉相对。前句说是第一次见面，后句就不能说“多次见过面”，两者矛盾。"}, {"text": "这间屋子多次朝南。", "explanation": "“多次”表示反复发生，与〈一直〉相对。朝南是持续的状态，应说“一直朝南”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多次", "is_correct": true, "explanation": "“多次”表示开会讨论了很多次，与“开会讨论”的反复意思相合，正确。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰动词“开会”，句子不通。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰动词“开会”，句子不通。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示情况突然发生变化，与“多次开会”的反复意思不符。"}], "explanations": {"多次": "“多次”表示开会讨论了很多次，与“开会讨论”的反复意思相合，正确。", "很": "语法：“很”是程度副词，不能直接修饰动词“开会”，句子不通。", "非常": "语法：“非常”是程度副词，不能直接修饰动词“开会”，句子不通。", "顿时": "语义：“顿时”表示情况突然发生变化，与“多次开会”的反复意思不符。"}, "sentence_index": 6, "correct_answer": "多次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我多次从未迟到过。", "explanation": "“多次”表示不止一次，与〈一次〉相对；“从未”表示一次也没有，两者矛盾。"}, {"text": "这所学校多次创办于1950年。", "explanation": "“多次”表示反复发生，与〈一次〉相对。“创办”是一次性的事件，应说“1950年创办”。"}, {"text": "奶奶多次是我的老师。", "explanation": "“多次”表示反复发生，与〈一直〉相对。“是老师”描述持续的身份，应说“一直是我的老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他多次了迟到，被老师批评了。", "corrected_sentence": "他多次迟到，被老师批评了。", "error_description": "“了”不能加在“多次”后面。错误写法“多次了迟到”，正确写法“多次迟到”，句末的“了”保留在“批评”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们多次了举手发言。", "corrected_sentence": "学生们多次举手发言。", "error_description": "“了”不能放在“多次”和动词之间。错误写法是“多次了举手”，正确写法是“多次举手”，“多次”直接修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30ac55d2-4d21-4661-b38d-e692cdb432bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86451, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
