INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "“之一”是说很多个里面的一个。", "primary_collocate": null, "pronunciation": "zhī yī", "ipa": "ʈʂɻ̩˥ i˥", "syllable_count": 2, "sentences": [{"text": "北京是中国最大的城市之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城是世界上有名的景点之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸是我最尊敬的人之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语是我的爱好之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店是城里最老的饭店之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熊猫是中国最可爱的动物之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师是我们学校最好的老师之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前看书，是我的好习惯之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个队里最高的球员之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河是中国最长的河流之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在“最…的+名词”后面，表示其中之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86451, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。"}, {"text": "执意", "is_correct": false, "explanation": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是坚持己见。"}, {"text": "质疑", "is_correct": false, "explanation": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出疑问。"}, {"text": "致意", "is_correct": false, "explanation": "zhì yì（第四声、第四声）与 zhī yī（第一声、第一声）声调不同，意思是表示问候或敬意。"}], "explanations": {"之一": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。", "执意": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是坚持己见。", "质疑": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出疑问。", "致意": "zhì yì（第四声、第四声）与 zhī yī（第一声、第一声）声调不同，意思是表示问候或敬意。"}, "sentence_index": null, "correct_answer": "之一"}, "level_3": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确。之一表示许多当中的一个，与“北京是中国最大的城市”的范围相符。"}, {"text": "之外", "is_correct": false, "explanation": "语义：「之外」表示范围以外，说北京在“最大的城市”之外，与句子的归属义相反。"}, {"text": "之后", "is_correct": false, "explanation": "搭配：「之后」要接时间或事件（如“吃饭之后”），不能接“城市”来表示归属。"}, {"text": "之下", "is_correct": false, "explanation": "配价：「之下」要与“在”组成“在…之下”的结构，直接接“城市”不成立。"}], "explanations": {"之一": "正确。之一表示许多当中的一个，与“北京是中国最大的城市”的范围相符。", "之外": "语义：「之外」表示范围以外，说北京在“最大的城市”之外，与句子的归属义相反。", "之后": "搭配：「之后」要接时间或事件（如“吃饭之后”），不能接“城市”来表示归属。", "之下": "配价：「之下」要与“在”组成“在…之下”的结构，直接接“城市”不成立。"}, "sentence_index": 0, "correct_answer": "之一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店是我们城里唯一的饭店之一。", "explanation": "这里不能用〈之一〉。「之一」表示许多个中的一个，“唯一”表示只有一个，二者矛盾，应说“这家饭店是我们城里唯一的饭店”。"}, {"text": "他是我的一位朋友之一。", "explanation": "这里应去掉〈之一〉。“一位”已经表示数量，再加“之一”就重复了，应说“他是我的一位朋友”。"}, {"text": "这是我每天必喝的一杯水之一。", "explanation": "这里应去掉〈之一〉。“一杯”已经表示数量，再加“之一”就重复了，应说“这是我每天必喝的一杯水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86451, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。"}, {"text": "直译", "is_correct": false, "explanation": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是按字面译出。"}, {"text": "置疑", "is_correct": false, "explanation": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出怀疑。"}, {"text": "制衣", "is_correct": false, "explanation": "zhì yī（第四声、第一声）与 zhī yī 只有第一个音节声调不同，意思是缝制衣服。"}], "explanations": {"之一": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。", "直译": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是按字面译出。", "置疑": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出怀疑。", "制衣": "zhì yī（第四声、第一声）与 zhī yī 只有第一个音节声调不同，意思是缝制衣服。"}, "sentence_index": null, "correct_answer": "之一"}, "level_3": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确。之一表示许多当中的一个，与“最好的老师”的范围相符。"}, {"text": "之前", "is_correct": false, "explanation": "语义：「之前」指时间上的先后，与“最好的老师”这种范围义不合。"}, {"text": "之上", "is_correct": false, "explanation": "配价：「之上」要与“在”组成“在…之上”的结构，直接接“老师”不成立。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：「之间」要与“两者”或多个并列对象搭配，不能只接“老师”来表示范围。"}], "explanations": {"之一": "正确。之一表示许多当中的一个，与“最好的老师”的范围相符。", "之前": "语义：「之前」指时间上的先后，与“最好的老师”这种范围义不合。", "之上": "配价：「之上」要与“在”组成“在…之上”的结构，直接接“老师”不成立。", "之间": "搭配：「之间」要与“两者”或多个并列对象搭配，不能只接“老师”来表示范围。"}, "sentence_index": 6, "correct_answer": "之一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们班第一名之一。", "explanation": "这里应去掉〈之一〉。第一名在班里只有一个，「之一」表示许多个中的一个，二者矛盾。"}, {"text": "这是我买的一本书之一。", "explanation": "这里应去掉〈之一〉。“一本”已经表示数量，再加“之一”就重复了，应说“这是我买的一本书”。"}, {"text": "这是我每天都喝的唯一的茶之一。", "explanation": "这里不能用〈之一〉。“唯一”表示只有一个，「之一」表示许多个中的一个，二者矛盾，应说“这是我每天都喝的唯一的茶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说是他最有名的作品的之一。", "corrected_sentence": "这部小说是他最有名的作品之一。", "error_description": "错误在于“之一”前多加了“的”。“之一”应直接接在名词之后，应说“最有名的作品之一”，不能说“作品的之一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是这个城市最有名的画家的之一。", "corrected_sentence": "他是这个城市最有名的画家之一。", "error_description": "错误在于“之一”前多加了“的”。“之一”应直接接在名词之后，应说“最有名的画家之一”，不能说“画家的之一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
