INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "表示许多事物或许多人当中的一个。", "primary_collocate": null, "pronunciation": "zhī yī", "ipa": "ʈʂɻ̩˥ i˥", "syllable_count": 2, "sentences": [{"text": "他是我们班最聪明的学生之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国茶是世界上最受欢迎的饮料之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是今年最好的书之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车是我每天上班的方式之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是公司里最年轻的经理之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上海是我去过的城市之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果是我最爱吃的水果之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们要解决的问题之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个国家有名的歌手之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天是我最喜欢的季节之一。", "target_word": "之一", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "接在表示人或事物的名词后，指许多当中的一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86452, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。"}, {"text": "直译", "is_correct": false, "explanation": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是按字面译出。"}, {"text": "置疑", "is_correct": false, "explanation": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出怀疑。"}, {"text": "制衣", "is_correct": false, "explanation": "zhì yī（第四声、第一声）与 zhī yī 只有第一个音节声调不同，意思是缝制衣服。"}], "explanations": {"之一": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。", "直译": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是按字面译出。", "置疑": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出怀疑。", "制衣": "zhì yī（第四声、第一声）与 zhī yī 只有第一个音节声调不同，意思是缝制衣服。"}, "sentence_index": null, "correct_answer": "之一"}, "level_3": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确。之一表示许多当中的一个，与“班里最聪明的学生”的范围相符。"}, {"text": "之外", "is_correct": false, "explanation": "语义：「之外」表示范围以外，说他在“最聪明的学生”之外，与句子的归属义相反。"}, {"text": "之前", "is_correct": false, "explanation": "语义：「之前」指时间上的先后，与“最聪明的学生”这种身份义不合。"}, {"text": "之上", "is_correct": false, "explanation": "配价：「之上」要与“在”组成“在…之上”的结构，直接接“学生”不成立。"}], "explanations": {"之一": "正确。之一表示许多当中的一个，与“班里最聪明的学生”的范围相符。", "之外": "语义：「之外」表示范围以外，说他在“最聪明的学生”之外，与句子的归属义相反。", "之前": "语义：「之前」指时间上的先后，与“最聪明的学生”这种身份义不合。", "之上": "配价：「之上」要与“在”组成“在…之上”的结构，直接接“学生”不成立。"}, "sentence_index": 0, "correct_answer": "之一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈是我唯一的亲人之一。", "explanation": "这里应去掉〈之一〉。“唯一”表示只有一个，「之一」表示许多个中的一个，二者矛盾，应说“妈妈是我唯一的亲人”。"}, {"text": "他是我最好的一个朋友之一。", "explanation": "这里应去掉〈之一〉。“一个”已经表示数量，再加“之一”就重复了，应说“他是我最好的一个朋友”。"}, {"text": "这是我每天必吃的一碗米饭之一。", "explanation": "这里应去掉〈之一〉。“一碗”已经表示数量，再加“之一”就重复了，应说“这是我每天必吃的一碗米饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86452, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。"}, {"text": "执意", "is_correct": false, "explanation": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是坚持己见。"}, {"text": "质疑", "is_correct": false, "explanation": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出疑问。"}, {"text": "致意", "is_correct": false, "explanation": "zhì yì（第四声、第四声）与 zhī yī（第一声、第一声）声调不同，意思是表示问候或敬意。"}], "explanations": {"之一": "正确答案。之一读作 zhī yī（第一声、第一声），意思是许多当中的一个。", "执意": "zhí yì（第二声、第四声）与 zhī yī（第一声）声调不同，意思是坚持己见。", "质疑": "zhì yí（第四声、第二声）与 zhī yī（第一声）声调不同，意思是提出疑问。", "致意": "zhì yì（第四声、第四声）与 zhī yī（第一声、第一声）声调不同，意思是表示问候或敬意。"}, "sentence_index": null, "correct_answer": "之一"}, "level_3": {"options": [{"text": "之一", "is_correct": true, "explanation": "正确。之一表示许多当中的一个，与“最爱吃的水果”的范围相符。"}, {"text": "之后", "is_correct": false, "explanation": "语义：「之后」指时间上的先后，与“最爱吃的水果”这种归属义不合。"}, {"text": "之下", "is_correct": false, "explanation": "配价：「之下」要与“在”组成“在…之下”的结构，直接接“水果”不成立。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：「之间」要与“两者”或多个并列对象搭配，不能只接“水果”来表示范围。"}], "explanations": {"之一": "正确。之一表示许多当中的一个，与“最爱吃的水果”的范围相符。", "之后": "语义：「之后」指时间上的先后，与“最爱吃的水果”这种归属义不合。", "之下": "配价：「之下」要与“在”组成“在…之下”的结构，直接接“水果”不成立。", "之间": "搭配：「之间」要与“两者”或多个并列对象搭配，不能只接“水果”来表示范围。"}, "sentence_index": 6, "correct_answer": "之一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们班第一名之一。", "explanation": "这里应去掉〈之一〉。第一名在班里只有一个，「之一」表示许多个中的一个，二者矛盾。"}, {"text": "这是我买的一本书之一。", "explanation": "这里应去掉〈之一〉。“一本”已经表示数量，再加“之一”就重复了，应说“这是我买的一本书”。"}, {"text": "这是我每天都喝的唯一的茶之一。", "explanation": "这里不能用〈之一〉。“唯一”表示只有一个，「之一」表示许多个中的一个，二者矛盾，应说“这是我每天都喝的唯一的茶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司是这个城市最大的企业的之一。", "corrected_sentence": "这家公司是这个城市最大的企业之一。", "error_description": "错误在于“之一”前多加了“的”。“之一”应直接接在名词之后，应说“最大的企业之一”，不能说“企业的之一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们学校最受欢迎的活动的之一。", "corrected_sentence": "这是我们学校最受欢迎的活动之一。", "error_description": "错误在于“之一”前多加了“的”。“之一”应直接接在名词之后，应说“最受欢迎的活动之一”，不能说“活动的之一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
