INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86453, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "实力是你真正有的本事和力量。", "primary_collocate": null, "pronunciation": "shí lì", "ipa": "ʂʐ̩˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "想进大公司，你得有实力。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "实力不够，再努力也很难赢。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他隐藏了自己的实力。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试能看出你的实力。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠实力赢得了冠军。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人要多练习，增强实力。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对方的实力比我们强一些。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有实力，也有好运气。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个歌手的实力大家都听得出来。", "target_word": "实力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有提高实力，才有机会。", "target_word": "实力", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "实力：一个人真正有的本事，如有实力、增强实力、隐藏实力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指一个人真正有的本事，是正确答案。"}, {"text": "失利", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是失利（比赛或竞争中失败），不是本事。"}, {"text": "视力", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是视力（眼睛看东西的能力），与本事不同。"}, {"text": "事理", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）、lǐ（第三声）与 lì（第四声）声调都不同，意思是事情的道理。"}, {"text": "失礼", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是失礼。"}], "explanations": {"实力": "“实力”指一个人真正有的本事，是正确答案。", "失利": "shī（第一声）与 shí（第二声）声调不同，意思是失利（比赛或竞争中失败），不是本事。", "视力": "shì（第四声）与 shí（第二声）声调不同，意思是视力（眼睛看东西的能力），与本事不同。", "事理": "shì（第四声）与 shí（第二声）、lǐ（第三声）与 lì（第四声）声调都不同，意思是事情的道理。", "失礼": "shī（第一声）与 shí（第二声）声调不同，lǐ（第三声）与 lì（第四声）声调也不同，意思是失礼。"}, "sentence_index": null, "correct_answer": "实力"}, "level_3": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指一个人真正有的本事，与“得有”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是本事，“想进大公司”不需要“有颜色”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不是本事，与“想进大公司”的条件无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是本事，“你得有年龄”与句意不符。"}], "explanations": {"实力": "“实力”指一个人真正有的本事，与“得有”搭配，符合句意。", "颜色": "语义：“颜色”不是本事，“想进大公司”不需要“有颜色”。", "雨伞": "语义：“雨伞”是物品，不是本事，与“想进大公司”的条件无关。", "年龄": "语义：年龄不是本事，“你得有年龄”与句意不符。"}, "sentence_index": 0, "correct_answer": "实力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的实力很亮。", "explanation": "这里应该用〈颜色〉。“实力”指人的本事，不用来形容画的颜色。"}, {"text": "他的实力很暴躁，经常发火。", "explanation": "这里应该用〈脾气〉。“实力”指本事，不用来形容性情。"}, {"text": "这件衣服的实力很贵。", "explanation": "这里应该用〈价格〉。“实力”指本事，不能用来说商品的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') 