INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86453, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指一个人真正有的本事，是正确答案。"}, {"text": "势力", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是势力（权势或影响力），侧重权力。"}, {"text": "使力", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，意思是用力，指动作，不是本事。"}, {"text": "十里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是十里（距离），与本事无关。"}], "explanations": {"实力": "“实力”指一个人真正有的本事，是正确答案。", "势力": "shì（第四声）与 shí（第二声）声调不同，意思是势力（权势或影响力），侧重权力。", "使力": "shǐ（第三声）与 shí（第二声）声调不同，意思是用力，指动作，不是本事。", "十里": "lǐ（第三声）与 lì（第四声）声调不同，意思是十里（距离），与本事无关。"}, "sentence_index": null, "correct_answer": "实力"}, "level_3": {"options": [{"text": "实力", "is_correct": true, "explanation": "“实力”指对方真正有的本事，与“比我们强”搭配，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“强”用于能力或力量，不用来比较体重。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是本事，不能与“强”比较。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”与本事无关，不能比较强弱。"}], "explanations": {"实力": "“实力”指对方真正有的本事，与“比我们强”搭配，符合句意。", "体重": "搭配：“强”用于能力或力量，不用来比较体重。", "年龄": "语义：年龄不是本事，不能与“强”比较。", "电话": "语义：“电话”与本事无关，不能比较强弱。"}, "sentence_index": 6, "correct_answer": "实力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的实力很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“实力”指本事，不用来说天气好坏。"}, {"text": "这辆车的实力很快。", "explanation": "这里应该用〈速度〉。“实力”指本事，不用来形容车的快慢。"}, {"text": "这杯水的实力很烫。", "explanation": "这里应该用〈温度〉。“实力”指本事，不用来形容水的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这一行有一个实力。", "corrected_sentence": "他在这一行有一定的实力。", "error_description": "“实力”是抽象的本事，表示程度时应用“一定的”；直接用“一个”计数不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们实力的很强。", "corrected_sentence": "我们实力很强。", "error_description": "错误在于“实力”后多加了“的”，使“的”后接副词“很”，不通顺。应说“我们实力很强”，“很”直接修饰“强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
