INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86461, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指是伸出手指，对着一个地方或者一样东西。", "primary_collocate": null, "pronunciation": "zhǐ", "ipa": "ʈʂɻ̩˨˩˦", "syllable_count": 1, "sentences": [{"text": "他伸出手，指着前面的那座山。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩伸出手，指着天上的月亮。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她指了指桌子上的那本书。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着黑板说：看这里。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指着地图上的一个红点。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈指着门，让我出去。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你指一下厕所的方向。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指着对面的商店说：我家在那儿。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子指着蛋糕说：我要这个。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出手，往东边指了一下。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指着", "label": "体标"}, {"form": "指了", "label": "体标"}, {"form": "指过", "label": "体标"}], "register": "中性", "sense_fingerprint": "指：伸出手指，对着某个地方或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86461, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指", "is_correct": true, "explanation": "正确答案：指（zhǐ，第三声），意思是伸出手指对着某处。"}, {"text": "尺", "is_correct": false, "explanation": "尺（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是尺子。"}, {"text": "直", "is_correct": false, "explanation": "直（zhí，第二声）与 zhǐ 声调不同，意思是笔直。"}, {"text": "质", "is_correct": false, "explanation": "质（zhì，第四声）与 zhǐ 声调不同，意思是质量。"}, {"text": "使", "is_correct": false, "explanation": "使（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是使用、让。"}, {"text": "紫", "is_correct": false, "explanation": "紫（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是紫色。"}], "explanations": {"指": "正确答案：指（zhǐ，第三声），意思是伸出手指对着某处。", "尺": "尺（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是尺子。", "直": "直（zhí，第二声）与 zhǐ 声调不同，意思是笔直。", "质": "质（zhì，第四声）与 zhǐ 声调不同，意思是质量。", "使": "使（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是使用、让。", "紫": "紫（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是紫色。"}, "sentence_index": null, "correct_answer": "指"}, "level_3": {"options": [{"text": "指", "is_correct": true, "explanation": "正确：“指着”表示用手对着远处的山，与“伸出手”的动作相配。"}, {"text": "握", "is_correct": false, "explanation": "搭配：“握”要求对象能被手抓住，远处的大山无法握住。"}, {"text": "挥", "is_correct": false, "explanation": "语义：“挥”表示摆动手臂或物体，与句中指向远处山的动作不符。"}, {"text": "抱", "is_correct": false, "explanation": "配价：“抱”的对象是可以搂住的人或物，远处的大山不能抱。"}], "explanations": {"指": "正确：“指着”表示用手对着远处的山，与“伸出手”的动作相配。", "握": "搭配：“握”要求对象能被手抓住，远处的大山无法握住。", "挥": "语义：“挥”表示摆动手臂或物体，与句中指向远处山的动作不符。", "抱": "配价：“抱”的对象是可以搂住的人或物，远处的大山不能抱。"}, "sentence_index": 0, "correct_answer": "指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师指了我怎么写作文。", "explanation": "这里应该用〈指点〉。指点表示具体点拨写作方法，“指”单用时不能表示这个意思。"}, {"text": "他站在台上指了乐队的节奏，大家演奏得很整齐。", "explanation": "这里应该用〈指挥〉。指挥表示带领乐队演奏，“指”单用只表示用手或物体对着某处，不能表示这个意思。"}, {"text": "老师指了我做班长。", "explanation": "这里应该用〈指定〉。指定表示选定某人担任某个职务，“指”不能单独表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86461, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指", "is_correct": true, "explanation": "正确答案：指（zhǐ，第三声），意思是伸出手指对着某处。"}, {"text": "齿", "is_correct": false, "explanation": "齿（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是牙齿。"}, {"text": "织", "is_correct": false, "explanation": "织（zhī，第一声）与 zhǐ 声调不同，意思是编织。"}, {"text": "至", "is_correct": false, "explanation": "至（zhì，第四声）与 zhǐ 声调不同，意思是到达。"}, {"text": "子", "is_correct": false, "explanation": "子（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是儿子。"}, {"text": "始", "is_correct": false, "explanation": "始（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是开始。"}], "explanations": {"指": "正确答案：指（zhǐ，第三声），意思是伸出手指对着某处。", "齿": "齿（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是牙齿。", "织": "织（zhī，第一声）与 zhǐ 声调不同，意思是编织。", "至": "至（zhì，第四声）与 zhǐ 声调不同，意思是到达。", "子": "子（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是儿子。", "始": "始（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是开始。"}, "sentence_index": null, "correct_answer": "指"}, "level_3": {"options": [{"text": "指", "is_correct": true, "explanation": "正确：“指一下”表示用手指示方向，与“请你”的请求相配。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”表示用鼻子嗅，与句中问方向的请求不符。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“方向”是抽象的位置，不能被摸。"}, {"text": "推", "is_correct": false, "explanation": "配价：“推”需要可以被推动的对象，“厕所的方向”不能推。"}], "explanations": {"指": "正确：“指一下”表示用手指示方向，与“请你”的请求相配。", "闻": "语义：“闻”表示用鼻子嗅，与句中问方向的请求不符。", "摸": "搭配：“方向”是抽象的位置，不能被摸。", "推": "配价：“推”需要可以被推动的对象，“厕所的方向”不能推。"}, "sentence_index": 6, "correct_answer": "指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上级指了我们要加快进度。", "explanation": "这里应该用〈指示〉。指示表示上级对下级发出指导或命令，“指”单用时不能表示布置任务。"}, {"text": "他总是指了我一顿，让我很难过。", "explanation": "这里应该用〈指责〉。指责表示批评过错，“指”没有批评的意思，句中的批评含义应使用〈指责〉。"}, {"text": "这个路标指了游客的脚步，让他们很困惑。", "explanation": "这里应该用〈指引〉。指引表示引导别人前往某处，“指”只表示用手或物体对着某处，不能引导行进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他伸出手，指了着远处的一棵树。", "corrected_sentence": "他伸出手，指着远处的一棵树。", "error_description": "错误：“指了着”同时用了“了”和“着”两个动态助词，一个动词只能带一个。正确：“指着”，表示动作正在进行并保持状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你帮我指一个那条路。", "corrected_sentence": "请你帮我指一下那条路。", "error_description": "错误：动量补语用错，“一个”是量词短语，不能表示动作的次数。正确：“指一下”，表示动作简短地进行一次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
