INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指或物体对着某个方向、某个事物，使人注意。", "primary_collocate": null, "pronunciation": "zhǐ", "ipa": "ʈʂɻ̩˨˩˦", "syllable_count": 1, "sentences": [{"text": "老师用笔指着黑板上的字。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察指着路的左边说：请走这边。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着小棍子，指了指地图。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游举着小旗，指着前面的大楼。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用笔一个字一个字地指着，读给孩子听。", "target_word": "指", "complexity_tier": "T3", "furigana": "tā yòng bǐ yí gè zì yí gè zì de zhǐ zhe, dú gěi háizi tīng", "sentence_source": "generated"}, {"text": "导游用小旗指着山顶，大家都抬起了头。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着我，让我回答问题。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手电筒指着墙上的画，让大家看。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生指着照片上的一块阴影，让病人看。", "target_word": "指", "complexity_tier": "T3", "furigana": "yīshēng zhǐ zhe zhàopiàn shàng de yí kuài yīnyǐng, ràng bìngrén kàn", "sentence_source": "generated"}, {"text": "她指着路牌，对司机说：往这边走。", "target_word": "指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指着", "label": "体标"}, {"form": "指了", "label": "体标"}, {"form": "指过", "label": "体标"}], "register": "中性", "sense_fingerprint": "指：用手或物体对着某处，让别人注意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 导游 (Zipf 3.88), 山顶 (Zipf 3.95), 抬起 (Zipf 3.75)']::text[], 'f13c54b2-bfd1-40d4-9d74-4f23a080aae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指", "is_correct": true, "explanation": "正确答案：指（zhǐ，第三声），意思是用手或物体对着某处，使人注意。"}, {"text": "齿", "is_correct": false, "explanation": "齿（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是牙齿。"}, {"text": "织", "is_correct": false, "explanation": "织（zhī，第一声）与 zhǐ 声调不同，意思是编织。"}, {"text": "至", "is_correct": false, "explanation": "至（zhì，第四声）与 zhǐ 声调不同，意思是到达。"}, {"text": "紫", "is_correct": false, "explanation": "紫（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是紫色。"}, {"text": "值", "is_correct": false, "explanation": "值（zhí，第二声）与 zhǐ 声调不同，意思是价值。"}], "explanations": {"指": "正确答案：指（zhǐ，第三声），意思是用手或物体对着某处，使人注意。", "齿": "齿（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是牙齿。", "织": "织（zhī，第一声）与 zhǐ 声调不同，意思是编织。", "至": "至（zhì，第四声）与 zhǐ 声调不同，意思是到达。", "紫": "紫（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是紫色。", "值": "值（zhí，第二声）与 zhǐ 声调不同，意思是价值。"}, "sentence_index": null, "correct_answer": "指"}, "level_3": {"options": [{"text": "指", "is_correct": true, "explanation": "正确：“指着”表示用笔对着黑板上的字，让人注意，与“用笔”相配。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”表示把东西悬挂起来，与用笔对着黑板上的字的动作不符。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”表示用气流推动，与句中用笔指向字的动作不符。"}, {"text": "抱", "is_correct": false, "explanation": "配价：“抱”的对象是可以搂住的东西，黑板上的字不能抱。"}], "explanations": {"指": "正确：“指着”表示用笔对着黑板上的字，让人注意，与“用笔”相配。", "挂": "语义：“挂”表示把东西悬挂起来，与用笔对着黑板上的字的动作不符。", "吹": "语义：“吹”表示用气流推动，与句中用笔指向字的动作不符。", "抱": "配价：“抱”的对象是可以搂住的东西，黑板上的字不能抱。"}, "sentence_index": 0, "correct_answer": "指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导游在介绍中指了这座大楼的特点。", "explanation": "这里应该用〈指出〉。指出表示说明某处的特点，“指”只表示用手或物体对着某处。"}, {"text": "他指了我去做坏事，我很后悔。", "explanation": "这里应该用〈指使〉。指使表示支使别人去做某事，多指不好的事；“指”单用时不能表示这个意思。"}, {"text": "经理指了他负责这个项目。", "explanation": "这里应该用〈指定〉。指定表示选定某人担任某项职责，“指”不能单独表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86462, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指", "is_correct": true, "explanation": "正确答案：指（zhǐ，第三声），意思是用手或物体对着某处，使人注意。"}, {"text": "尺", "is_correct": false, "explanation": "尺（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是尺子。"}, {"text": "直", "is_correct": false, "explanation": "直（zhí，第二声）与 zhǐ 声调不同，意思是笔直。"}, {"text": "使", "is_correct": false, "explanation": "使（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是使用、让。"}, {"text": "子", "is_correct": false, "explanation": "子（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是儿子。"}, {"text": "始", "is_correct": false, "explanation": "始（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是开始。"}], "explanations": {"指": "正确答案：指（zhǐ，第三声），意思是用手或物体对着某处，使人注意。", "尺": "尺（chǐ，第三声）与 zhǐ 声母不同（ch 与 zh），意思是尺子。", "直": "直（zhí，第二声）与 zhǐ 声调不同，意思是笔直。", "使": "使（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是使用、让。", "子": "子（zǐ，第三声）与 zhǐ 声母不同（z 与 zh），意思是儿子。", "始": "始（shǐ，第三声）与 zhǐ 声母不同（sh 与 zh），意思是开始。"}, "sentence_index": null, "correct_answer": "指"}, "level_3": {"options": [{"text": "指", "is_correct": true, "explanation": "正确：“指着我”表示用手对着学生示意，请他回答问题，与句中意思相符。"}, {"text": "碰", "is_correct": false, "explanation": "语义：“碰”表示接触，不表示示意或点名，与“让我回答问题”不符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”表示用水清洁，老师不会“洗着我”让我回答问题。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”表示用牙齿夹住，与老师请我回答问题的意思不符。"}], "explanations": {"指": "正确：“指着我”表示用手对着学生示意，请他回答问题，与句中意思相符。", "碰": "语义：“碰”表示接触，不表示示意或点名，与“让我回答问题”不符。", "洗": "语义：“洗”表示用水清洁，老师不会“洗着我”让我回答问题。", "咬": "语义：“咬”表示用牙齿夹住，与老师请我回答问题的意思不符。"}, "sentence_index": 6, "correct_answer": "指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块路牌指了我们一路，我们没有迷路。", "explanation": "这里应该用〈指引〉。指引表示引导别人前往某处，“指”只表示用手或物体对着某处，不能表示一路引导。"}, {"text": "老师指了我写论文。", "explanation": "这里应该用〈指导〉。指导表示给予具体的指点和帮助，“指”不能单独表示这个意思。"}, {"text": "他当着大家的面指了我一顿，让我很不舒服。", "explanation": "这里应该用〈指责〉。指责表示批评别人的过错，“指”单用时没有批评的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师用粉笔指了着黑板上的日期，让大家看。", "corrected_sentence": "老师用粉笔指着黑板上的日期，让大家看。", "error_description": "错误：“指了着”同时用了“了”和“着”两个动态助词。正确：“指着”，表示动作正在进行并保持状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她指着一个窗外说：下雨了。", "corrected_sentence": "她指着窗外说：下雨了。", "error_description": "错误：“一个窗外”把数量短语用在处所词“窗外”前，不合语法。正确：“指着窗外”，处所词前不加数量短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01579256-9b09-4493-abe6-307987852e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭小", "is_correct": true, "explanation": "狭小：面积窄小，与「广大」意思相反。"}, {"text": "寒冷", "is_correct": false, "explanation": "寒冷指温度低，与「广大」没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃指态度认真、不随便，与「广大」无关。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软指不硬，与「广大」不构成反义。"}], "correct_answer": "狭小", "explanations": {"狭小": "狭小：面积窄小，与「广大」意思相反。", "寒冷": "寒冷指温度低，与「广大」没有反义关系。", "严肃": "严肃指态度认真、不随便，与「广大」无关。", "柔软": "柔软指不硬，与「广大」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
