INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "广大是又宽又大，或者人很多。", "primary_collocate": null, "pronunciation": "guǎng dà", "ipa": "kwɑŋ˨˩˦ ta˥˩", "syllable_count": 2, "sentences": [{"text": "山的那边是广大的平原。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有广大的土地。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大观众都在等他的新电影。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大的天空里一朵云也没有。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大职工都同意这个办法。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大青年都喜欢这个节目。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大的农民欢迎这个新政策。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里有广大的草原，一眼看不到头。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事得到了广大群众的帮助。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广大的世界里，有很多我们不知道的事。", "target_word": "广大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "廣大", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又宽又大，或者人很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd727e10f-1248-4124-9d4c-8b97d0ca17dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广大", "is_correct": true, "explanation": "广大：面积宽阔，正好形容平原。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：「锋利」形容刀刃等，不能用来形容平原。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：「甜美」形容声音、笑容或滋味，不能形容平原。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：「陡峭」指地势起伏很大，与平原平坦的特点相矛盾。"}], "explanations": {"广大": "广大：面积宽阔，正好形容平原。", "锋利": "搭配：「锋利」形容刀刃等，不能用来形容平原。", "甜美": "搭配：「甜美」形容声音、笑容或滋味，不能形容平原。", "陡峭": "语义：「陡峭」指地势起伏很大，与平原平坦的特点相矛盾。"}, "sentence_index": 0, "correct_answer": "广大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学成绩很广大。", "explanation": "这里应该用〈优秀〉。广大指面积宽阔或人数众多，成绩的好坏要用优秀。"}, {"text": "这个西瓜很广大。", "explanation": "这里应该用〈甜〉。广大用于空间或人数，不能形容味道。"}, {"text": "她唱得很广大。", "explanation": "这里应该用〈好〉。广大用于空间或人数，不能用来评价唱歌的水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广大", "is_correct": true, "explanation": "广大：人数众多，形容农民这一群体。"}, {"text": "透明", "is_correct": false, "explanation": "语义：「透明」指物体能让光透过，不能形容一群人。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：「滚烫」形容温度高的物体，不能修饰农民。"}, {"text": "碧绿", "is_correct": false, "explanation": "搭配：「碧绿」形容颜色，不能修饰农民。"}], "explanations": {"广大": "广大：人数众多，形容农民这一群体。", "透明": "语义：「透明」指物体能让光透过，不能形容一群人。", "滚烫": "搭配：「滚烫」形容温度高的物体，不能修饰农民。", "碧绿": "搭配：「碧绿」形容颜色，不能修饰农民。"}, "sentence_index": 6, "correct_answer": "广大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天很广大。", "explanation": "这里应该用〈寒冷〉。广大用于空间或人数，不能形容天气的冷暖。"}, {"text": "这次考试很广大。", "explanation": "这里应该用〈轻松〉。广大不能形容考试的难易，考试容易要用轻松。"}, {"text": "这台机器很广大。", "explanation": "这里应该用〈庞大〉。广大指面积宽阔或人数众多，形容机器的体积要用庞大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那片平原很非常广大。", "corrected_sentence": "那片平原非常广大。", "error_description": "程度副词「很」和「非常」不能同时修饰同一个形容词，应只用「非常」，说「非常广大」。这里多用了「很」，说成「很非常广大」，语法错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个广大的农民欢迎这个新政策。", "corrected_sentence": "广大的农民欢迎这个新政策。", "error_description": "「广大」表示人数众多，只能修饰一大群人，不能和「一个」这样表示单个的数量词一起用。这里说「一个广大的农民」，意思矛盾，应去掉「一个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4d207f-8c6f-4474-ac84-88f6335fce0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
