INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "是不是用来问一件事对不对。", "primary_collocate": null, "pronunciation": "shì bu shì", "ipa": "ʂʐ̩˥˩ pu ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "你说得对，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天去过超市，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天九点见面，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是你的哥哥，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天很冷，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都在家等你，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不想去，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路能到学校，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经吃过饭了，是不是？", "target_word": "是不是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在句末，向对方求证一件事对不对的附加问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e639b5d4-1009-41fd-8591-87027952efac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简直", "is_correct": false, "explanation": "搭配：“简直”修饰程度，不能用在句末作求证。"}, {"text": "究竟", "is_correct": false, "explanation": "语义：“究竟”用来追问到底，接在“你说得对”后面，与求证语气不合。"}, {"text": "是不是", "is_correct": true, "explanation": "“是不是”放在句末，向对方求证，正符合“你说得对”后面的语气。"}, {"text": "难道", "is_correct": false, "explanation": "语法：“难道”是反问副词，不能放在句末作附加求证。"}], "explanations": {"简直": "搭配：“简直”修饰程度，不能用在句末作求证。", "究竟": "语义：“究竟”用来追问到底，接在“你说得对”后面，与求证语气不合。", "是不是": "“是不是”放在句末，向对方求证，正符合“你说得对”后面的语气。", "难道": "语法：“难道”是反问副词，不能放在句末作附加求证。"}, "sentence_index": 0, "correct_answer": "是不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你把门关上，是不是？", "explanation": "这里应该用〈好吗〉。“是不是”求证一件事对不对，提出请求时要用“好吗”。"}, {"text": "我们一起去吃饭吧，是不是？", "explanation": "这里应该用〈好不好〉。“是不是”求证事实，提出建议征求同意要用“好不好”。"}, {"text": "你想喝茶还是喝咖啡，是不是？", "explanation": "这里应该用〈呢〉。选择问句不是求证一件事对不对，不能加“是不是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也许", "is_correct": false, "explanation": "语义：“也许”表示推测，与句末“是不是”的求证语气相矛盾。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示肯定，与句末的求证语气相冲突。"}, {"text": "是不是", "is_correct": true, "explanation": "“是不是”放在句末，向对方求证，正合此句“他们都在家等你”的语气。"}, {"text": "恐怕", "is_correct": false, "explanation": "语法：“恐怕”是表示推测的副词，不能单独放在句末作求证。"}], "explanations": {"也许": "语义：“也许”表示推测，与句末“是不是”的求证语气相矛盾。", "一定": "语义：“一定”表示肯定，与句末的求证语气相冲突。", "是不是": "“是不是”放在句末，向对方求证，正合此句“他们都在家等你”的语气。", "恐怕": "语法：“恐怕”是表示推测的副词，不能单独放在句末作求证。"}, "sentence_index": 6, "correct_answer": "是不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "帮我拿一下那本书，是不是？", "explanation": "这里应该用〈好吗〉。“是不是”求证事实，请别人帮忙要用“好吗”。"}, {"text": "时间不早了，我们走吧，是不是？", "explanation": "这里应该用〈好不好〉。提出建议征求同意要用“好不好”，不用“是不是”。"}, {"text": "你什么时候回来，是不是？", "explanation": "这里应该用〈呢〉。“什么时候”是特指问，不是求证对不对，不能加“是不是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天天气很好，是不是吗？", "corrected_sentence": "今天天气很好，是不是？", "error_description": "“是不是”已经是句末求证的说法，后面不能再加“吗”，应为“今天天气很好，是不是？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86465, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都喜欢这部电影，是是不是？", "corrected_sentence": "我们都喜欢这部电影，是不是？", "error_description": "“是不是”多写了一个“是”，应为句末求证的“是不是”，写成“是是不是”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9103980-5729-45f0-ac75-3c5c5a955ccf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
