INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86467, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "得很放在词后面，让意思变得更厉害。", "primary_collocate": null, "pronunciation": "de hěn", "ipa": "tɤ xən˨˩˦", "syllable_count": 2, "sentences": [{"text": "今天天气热得很。", "target_word": "得很", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房间安静得很。", "target_word": "得很", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他家的菜好吃得很。", "target_word": "得很", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我弟弟最近忙得很。", "target_word": "得很", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路远得很，你坐车去吧。", "target_word": "得很", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小孩聪明得很，一教就会。", "target_word": "得很", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的风景漂亮得很，你应该去看看。", "target_word": "得很", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在北京住过，所以对那里熟悉得很。", "target_word": "得很", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他年纪小，做事认真得很。", "target_word": "得很", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的会很长，大家都累得很。", "target_word": "得很", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在形容词后，加强程度，口语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43952535-ce3b-42ad-81d2-56414676474b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得很", "is_correct": true, "explanation": "得很放在形容词后，表示程度很深，是口语用法。“热得很”符合句意。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“热的”不能作句末补足成分，“天气热”后需要程度助词“得很”。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”用于修饰动词，不能直接接在形容词“热”后作补足。"}, {"text": "着", "is_correct": false, "explanation": "体貌：“着”表示状态持续，不能表示程度很深。"}], "explanations": {"得很": "得很放在形容词后，表示程度很深，是口语用法。“热得很”符合句意。", "的": "搭配：“热的”不能作句末补足成分，“天气热”后需要程度助词“得很”。", "地": "搭配：“地”用于修饰动词，不能直接接在形容词“热”后作补足。", "着": "体貌：“着”表示状态持续，不能表示程度很深。"}, "sentence_index": 0, "correct_answer": "得很"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟最近很忙得很。", "explanation": "“很”与“得很”重复，程度已由“得很”表示，不能同用。"}, {"text": "他这次比赛很辛苦得很。", "explanation": "“很”与“得很”重复，程度已由“得很”表示，不能同用。"}, {"text": "我们昨天很累得很，腿都不想动了。", "explanation": "“很”与“得很”重复，程度已由“得很”表示，不能同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得很", "is_correct": true, "explanation": "得很放在形容词后表示程度很深，“漂亮得很”与句中的推荐语气相合。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”后须接补语，句末单用“得”不成立，句子不完整。"}, {"text": "过", "is_correct": false, "explanation": "体貌：“过”表示曾经发生的经历，不表示程度，与“你应该去看看”的推荐语气不合。"}, {"text": "罢了", "is_correct": false, "explanation": "语义：“罢了”表示轻描淡写，与“你应该去看看”的推荐语气相矛盾。"}], "explanations": {"得很": "得很放在形容词后表示程度很深，“漂亮得很”与句中的推荐语气相合。", "得": "搭配：“得”后须接补语，句末单用“得”不成立，句子不完整。", "过": "体貌：“过”表示曾经发生的经历，不表示程度，与“你应该去看看”的推荐语气不合。", "罢了": "语义：“罢了”表示轻描淡写，与“你应该去看看”的推荐语气相矛盾。"}, "sentence_index": 6, "correct_answer": "得很"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的会很长，大家都很累得很。", "explanation": "“很”与“得很”重复，程度已由“得很”表示，不能同用。"}, {"text": "今天的会很长，大家都非常累得很。", "explanation": "“非常”与“得很”重复，程度已由“得很”表示，不能再加程度副词。"}, {"text": "今天的会很长，大家都很辛苦得很。", "explanation": "“很”与“得很”重复，程度已由“得很”表示，不能同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf5179b-e9a5-4c97-a8f9-af8ae5b88161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
