INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86469, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "怎么样是用来问事情是什么样子，或者好不好。", "primary_collocate": null, "pronunciation": "zěn me yàng", "ipa": "tsən˨˩ mə jɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "你妈妈最近怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个电影怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的新同学怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个手机用起来怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的面试怎么样了？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们学校怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的汤味道怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新搬的房子怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的汉语课怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那家宾馆的服务怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "怎么样：问人或事物的样子、好不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，句意问的是妈妈的近况，不是在哪里。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，妈妈的近况不是数目。"}, {"text": "怎么样", "is_correct": true, "explanation": "正确。用于询问妈妈最近的状况，符合句意。"}, {"text": "这么", "is_correct": false, "explanation": "配价：“这么”要修饰形容词，“妈妈最近这么”不能单独作谓语。"}], "explanations": {"哪儿": "语义：“哪儿”问地点，句意问的是妈妈的近况，不是在哪里。", "多少": "语义：“多少”问数量，妈妈的近况不是数目。", "怎么样": "正确。用于询问妈妈最近的状况，符合句意。", "这么": "配价：“这么”要修饰形容词，“妈妈最近这么”不能单独作谓语。"}, "sentence_index": 0, "correct_answer": "怎么样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的风景怎么样美啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}, {"text": "不管怎么样，我都支持你。", "explanation": "这是“无论如何”的用法，表示让步，并不是询问状况或征求意见。"}, {"text": "他怎么样高兴啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那样", "is_correct": false, "explanation": "语义：“那样”指代前文提到的情形，句中没有可指代的情形，句意不通。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”问具体是什么事物，此处问的是味道的好坏，不是具体内容。"}, {"text": "怎么样", "is_correct": true, "explanation": "正确。用于询问今天汤的味道如何，符合句意。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，汤的味道不是人，句意不通。"}], "explanations": {"那样": "语义：“那样”指代前文提到的情形，句中没有可指代的情形，句意不通。", "什么": "语义：“什么”问具体是什么事物，此处问的是味道的好坏，不是具体内容。", "怎么样": "正确。用于询问今天汤的味道如何，符合句意。", "谁": "语义：“谁”问人，汤的味道不是人，句意不通。"}, "sentence_index": 6, "correct_answer": "怎么样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子怎么样可爱啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}, {"text": "这家店的菜怎么样好吃啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}, {"text": "无论怎么样，我都不同意。", "explanation": "这是“无论如何”的用法，表示让步，并不是询问服务的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们周末去郊游，怎么样了？", "corrected_sentence": "我们周末去郊游，怎么样？", "error_description": "错误：征求对未来周末安排的意见时加了“了”。“了”表示已经发生或完成，不能用于尚未发生的郊游。正确应为“我们周末去郊游，怎么样？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家饭店的菜很怎么样？", "corrected_sentence": "那家饭店的菜怎么样？", "error_description": "错误：“很”加在了“怎么样”前面。“怎么样”不是形容词，不能受“很”修饰。正确应为“那家饭店的菜怎么样？”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
