INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86470, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问性质或状况，也用于征求意见。", "primary_collocate": null, "pronunciation": "zěn me yàng", "ipa": "tsən˨˩ mə jɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "你今天身体怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家饭馆的菜怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你昨天的考试怎么样了？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们明天去爬山，怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的新工作怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末一起看电影，怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的天气怎么样？", "target_word": "怎么样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你觉得这件衣服怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你家附近的环境怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语说得怎么样？", "target_word": "怎么样", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "怎么样：疑问代词，问状况、性质或征求意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这样", "is_correct": false, "explanation": "语义：“这样”指示眼前或前文的情形，不能用来询问今天的身体状况。"}, {"text": "怎么样", "is_correct": true, "explanation": "正确。用于询问对方今天的身体状况，符合句意。"}, {"text": "哪样", "is_correct": false, "explanation": "语义：“哪样”表示在几种之中选哪一种，句中没有可供选择的项。"}, {"text": "这么", "is_correct": false, "explanation": "配价：“这么”要修饰形容词，“身体这么”后须接形容词，不能单独作谓语。"}], "explanations": {"这样": "语义：“这样”指示眼前或前文的情形，不能用来询问今天的身体状况。", "怎么样": "正确。用于询问对方今天的身体状况，符合句意。", "哪样": "语义：“哪样”表示在几种之中选哪一种，句中没有可供选择的项。", "这么": "配价：“这么”要修饰形容词，“身体这么”后须接形容词，不能单独作谓语。"}, "sentence_index": 0, "correct_answer": "怎么样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌怎么样好听啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}, {"text": "不管怎么样，我都支持你。", "explanation": "这是“无论如何”的用法，表示让步，并不是询问状况或征求意见。"}, {"text": "今天的天气怎么样热啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，天气不是可以计数的事物，句意不通。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，句中问的是天气，不是地点。"}, {"text": "怎么样", "is_correct": true, "explanation": "正确。用于询问北京天气的状况，符合句意。"}, {"text": "怎么", "is_correct": false, "explanation": "配价：“怎么”后需接动词或形容词，“北京的天气怎么”不能单独作谓语。"}], "explanations": {"多少": "语义：“多少”问数量，天气不是可以计数的事物，句意不通。", "哪儿": "语义：“哪儿”问地点，句中问的是天气，不是地点。", "怎么样": "正确。用于询问北京天气的状况，符合句意。", "怎么": "配价：“怎么”后需接动词或形容词，“北京的天气怎么”不能单独作谓语。"}, "sentence_index": 6, "correct_answer": "怎么样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子怎么样聪明啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}, {"text": "这件衣服怎么样漂亮啊！", "explanation": "这里应该用〈多么〉。表示感叹程度要用“多么”，“怎么样”不能表示程度。"}, {"text": "无论怎么样，他都要去。", "explanation": "这是“无论如何”的用法，表示让步，并不是询问状况或征求意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们晚上吃火锅，很怎么样？", "corrected_sentence": "我们晚上吃火锅，怎么样？", "error_description": "错误：“怎么样”前多加了“很”。“怎么样”是疑问代词，不能受“很”修饰，应去掉“很”。正确应为“我们晚上吃火锅，怎么样？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个周末去看展览，怎么样了？", "corrected_sentence": "这个周末去看展览，怎么样？", "error_description": "错误：“怎么样”问的是计划或安排，句末加“了”表示已经发生或完成，不能用于尚未发生的周末活动。正确应去掉“了”，即“这个周末去看展览，怎么样？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
