INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86471, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "采访是向别人提问，听对方讲述自己的经历或看法。", "primary_collocate": null, "pronunciation": "cǎi fǎng", "ipa": "tsʰaɪ˨˩˦ faŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "记者问了很多问题，采访了一个小时。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们想采访自己的老师，写一篇文章。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我采访了奶奶，听她讲小时候的事。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者采访他的时候，他讲了自己的故事。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者采访他的时候，他有点儿紧张。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王采访了邻居，问他们住得怎么样。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边采访，一边在本子上记下来。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想采访那个孩子，听他说说看法。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们采访了几位老人，听他们讲过去。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节目里，记者正在采访路上的行人。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采访了", "label": "体标"}, {"form": "采访过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向别人提问并听他讲经历或看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86471, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采访", "is_correct": true, "explanation": "正确。采访表示向别人提问并听对方讲述，与“问了很多问题”前后呼应。"}, {"text": "采购", "is_correct": false, "explanation": "语义：「采购」指买东西，与前句“问了很多问题”的内容不合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的对象是物品或机器，不能用来表示持续一个小时的问答活动。"}, {"text": "观看", "is_correct": false, "explanation": "语义：「观看」指看影像或表演，与“问了很多问题”的听讲活动不合。"}], "explanations": {"采访": "正确。采访表示向别人提问并听对方讲述，与“问了很多问题”前后呼应。", "采购": "语义：「采购」指买东西，与前句“问了很多问题”的内容不合。", "修理": "搭配：「修理」的对象是物品或机器，不能用来表示持续一个小时的问答活动。", "观看": "语义：「观看」指看影像或表演，与“问了很多问题”的听讲活动不合。"}, "sentence_index": 0, "correct_answer": "采访"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向医生采访了这种病。", "explanation": "这里应该用〈询问〉。采访的宾语是人或事件，不能说“采访这种病”，向医生了解情况应说“询问”。"}, {"text": "我昨天去采访了那座古城。", "explanation": "这里“采访”取了“参观”的意思，但它只表示记者向人了解情况，不能用于地点，去古城应说“参观”。"}, {"text": "我采访了那道数学题。", "explanation": "这里应该用〈解答〉。采访的对象是人，不能用于题目；解题应说“解答”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86471, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "采访", "is_correct": true, "explanation": "正确。采访表示一边提问、听取，一边记录，与“在本子上记下来”相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：「跳舞」与“在本子上记下来”的动作冲突，语境不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：「睡觉」不能与“一边…一边在本子上记”同时进行，搭配不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：「洗澡」与在本子上写字同时进行不合常理，语境不合。"}], "explanations": {"采访": "正确。采访表示一边提问、听取，一边记录，与“在本子上记下来”相符。", "跳舞": "语义：「跳舞」与“在本子上记下来”的动作冲突，语境不合。", "睡觉": "搭配：「睡觉」不能与“一边…一边在本子上记”同时进行，搭配不通。", "洗澡": "语义：「洗澡」与在本子上写字同时进行不合常理，语境不合。"}, "sentence_index": 6, "correct_answer": "采访"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想采访一下车站的开车时间。", "explanation": "这里应该用〈询问〉。采访的对象是人，“开车时间”不能被采访；向车站了解时间应说“询问”。"}, {"text": "科学家采访了蚂蚁。", "explanation": "这里应该用〈观察〉。采访是向人了解情况，蚂蚁不能被采访，研究动物应说“观察”。"}, {"text": "我们去山上采访了蘑菇。", "explanation": "这里“采访”取了“采集”的意思，但它只表示记者向人了解情况，不能用于蘑菇等植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86471, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位记者正在采访了一位退休的工人。", "corrected_sentence": "那位记者采访了一位退休的工人。", "error_description": "错误在于“正在”与“了”同用。“正在”表示进行中，“了”表示已完成，两者不能同时出现，应去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86471, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她明天采访过一位老工人。", "corrected_sentence": "她明天采访一位老工人。", "error_description": "错误在于“过”。“过”表示已经发生的经历，不能与将来的“明天”同用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
