INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86472, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "记者向有关人员了解情况并收集材料。", "primary_collocate": null, "pronunciation": "cǎi fǎng", "ipa": "tsʰaɪ˨˩˦ faŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "记者今天要去采访那位老教授。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台的记者采访了很多市民。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在会议后采访了市长。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者正在采访获奖的运动员。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天上午采访一位医生。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位记者采访过很多名人。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者到火灾现场采访了消防员。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想采访那家公司的经理。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社派两个记者去采访这次事故的当事人。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者采访完以后，马上写了新闻。", "target_word": "采访", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采访了", "label": "体标"}, {"form": "采访过", "label": "体标"}], "register": "中性", "sense_fingerprint": "记者为写新闻而向人或在现场了解情况、收集材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采访", "is_correct": true, "explanation": "正确。采访表示记者向人了解情况，与“那位老教授”搭配自然。"}, {"text": "采购", "is_correct": false, "explanation": "语义：「采购」指买东西或物资，不能用来指向人了解情况，与“那位老教授”不合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」多用于机器或物品，不能接“老教授”这样的人。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是房间、地方，不能接“老教授”这样的人。"}], "explanations": {"采访": "正确。采访表示记者向人了解情况，与“那位老教授”搭配自然。", "采购": "语义：「采购」指买东西或物资，不能用来指向人了解情况，与“那位老教授”不合。", "修理": "搭配：「修理」多用于机器或物品，不能接“老教授”这样的人。", "打扫": "搭配：「打扫」的对象是房间、地方，不能接“老教授”这样的人。"}, "sentence_index": 0, "correct_answer": "采访"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去采访博物馆了。", "explanation": "这里应该用〈参观〉。采访是向人了解情况，不能用于场所，去博物馆应说“参观”。"}, {"text": "我向老师采访了一个问题。", "explanation": "这里应该用〈询问〉。采访的对象是人或事件，不能说“采访一个问题”，向老师提问应说“询问”。"}, {"text": "我们去山上采访野花。", "explanation": "这里“采访”取了“采集”的意思，但它只表示记者向人了解情况，不能用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "采访", "is_correct": true, "explanation": "正确。采访表示记者为报道而了解情况，与“到火灾现场”的语境相符。"}, {"text": "扑灭", "is_correct": false, "explanation": "语义：「扑灭」指把火弄灭，宾语应是火，不能接“消防员”。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：「熄灭」多接火、灯等，不能接“消防员”这样的人。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」的对象是机器或物品，不能接“消防员”这样的人。"}], "explanations": {"采访": "正确。采访表示记者为报道而了解情况，与“到火灾现场”的语境相符。", "扑灭": "语义：「扑灭」指把火弄灭，宾语应是火，不能接“消防员”。", "熄灭": "搭配：「熄灭」多接火、灯等，不能接“消防员”这样的人。", "修理": "搭配：「修理」的对象是机器或物品，不能接“消防员”这样的人。"}, "sentence_index": 6, "correct_answer": "采访"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察采访了这起案件。", "explanation": "这里应该用〈调查〉。采访是记者为报道而向人了解情况，警察查案应说“调查”，案件也不能被采访。"}, {"text": "周末我们去采访了朋友家。", "explanation": "这里“采访”取了“拜访”的意思，但它只表示记者为新闻而向人了解情况。"}, {"text": "市场部采访了顾客的需求。", "explanation": "这里应该用〈调查〉。采访的对象是人，问的是人的情况；“需求”是抽象内容，不能被采访，了解需求应说“调查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "记者正在采访了那位工程师。", "corrected_sentence": "记者正在采访那位工程师。", "error_description": "错误在于“正在”与“了”同用。“正在”表示动作进行中，“了”表示已完成，不能同时出现，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "记者明天要采访过那位演员。", "corrected_sentence": "记者明天要采访那位演员。", "error_description": "错误在于“过”。“过”表示已经发生的经历，不能与将来的“明天”和“要”同用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
