INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86473, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "期是一段时间。", "primary_collocate": null, "pronunciation": "qī", "ipa": "tɕʰi˥", "syllable_count": 1, "sentences": [{"text": "这个汉语班我报了第一期。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第二期课程下个月开始。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她参加了培训班的第三期。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一期的学习很轻松。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "第一期工程已经完成了。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下一期什么时候开始报名？", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想再上一期口语课。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上一期我学得不太好。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这期培训让我进步很快。", "target_word": "期", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "第四期的同学今天到了。", "target_word": "期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "期：课程、培训、工程等分阶段进行时的某一段时间，如第一期、下一期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f194862d-1b99-4c2d-b020-1ea5545cf18a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86473, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "期", "is_correct": true, "explanation": "期 qī（第一声）指课程、培训等分阶段进行时的一段时间，即本题目标词。"}, {"text": "棋", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是棋。"}, {"text": "机", "is_correct": false, "explanation": "jī 与 qī 声母不同（j 与 q），意思是机器。"}, {"text": "青", "is_correct": false, "explanation": "qīng 比 qī 多一个韵尾 ng，意思是青色。"}, {"text": "气", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是空气。"}], "explanations": {"期": "期 qī（第一声）指课程、培训等分阶段进行时的一段时间，即本题目标词。", "棋": "qí（第二声）与 qī（第一声）声调不同，意思是棋。", "机": "jī 与 qī 声母不同（j 与 q），意思是机器。", "青": "qīng 比 qī 多一个韵尾 ng，意思是青色。", "气": "qì（第四声）与 qī（第一声）声调不同，意思是空气。"}, "sentence_index": null, "correct_answer": "期"}, "level_3": {"options": [{"text": "期", "is_correct": true, "explanation": "“第一期”指课程分期后的第一个班次，可以报名，符合“报了”。"}, {"text": "章", "is_correct": false, "explanation": "语义：“第一章”指书籍的章节，不能报名参加。"}, {"text": "页", "is_correct": false, "explanation": "搭配：“报了”不能接“第一页”，页不是可以报名的单位。"}, {"text": "集", "is_correct": false, "explanation": "语义：“集”指电视节目的一集，不是报名的单位。"}], "explanations": {"期": "“第一期”指课程分期后的第一个班次，可以报名，符合“报了”。", "章": "语义：“第一章”指书籍的章节，不能报名参加。", "页": "搭配：“报了”不能接“第一页”，页不是可以报名的单位。", "集": "语义：“集”指电视节目的一集，不是报名的单位。"}, "sentence_index": 0, "correct_answer": "期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这期车很贵。", "explanation": "这里应该用〈辆〉。车按辆计算，“期”指一段时间或分期的一批，不能用来修饰车。"}, {"text": "这期椅子很舒服。", "explanation": "这里应该用〈把〉。椅子按把计算，“期”指一段时间或分期的一批，不能用来修饰椅子。"}, {"text": "这期衣服很好看。", "explanation": "这里应该用〈件〉。衣服按件计算，“期”指一段时间或分期的一批，不能用来修饰衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86473, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "期", "is_correct": true, "explanation": "期 qī（第一声）指分阶段进行的一段时间，即本题目标词。"}, {"text": "起", "is_correct": false, "explanation": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来。"}, {"text": "去", "is_correct": false, "explanation": "qù（第四声）与 qī（第一声）声调不同，意思是去往。"}, {"text": "骑", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是骑（马、车）。"}], "explanations": {"期": "期 qī（第一声）指分阶段进行的一段时间，即本题目标词。", "起": "qǐ（第三声）与 qī（第一声）声调不同，意思是起来。", "去": "qù（第四声）与 qī（第一声）声调不同，意思是去往。", "骑": "qí（第二声）与 qī（第一声）声调不同，意思是骑（马、车）。"}, "sentence_index": null, "correct_answer": "期"}, "level_3": {"options": [{"text": "期", "is_correct": true, "explanation": "“上一期”指一个分期的课程班次，符合“想再上”。"}, {"text": "篇", "is_correct": false, "explanation": "搭配：“篇”用于文章，不能说“上一篇口语课”。"}, {"text": "幕", "is_correct": false, "explanation": "语义：“幕”指戏剧的段落，与口语课不搭。"}, {"text": "卷", "is_correct": false, "explanation": "语义：“卷”指书册或试卷，不能用来计算一次课程。"}], "explanations": {"期": "“上一期”指一个分期的课程班次，符合“想再上”。", "篇": "搭配：“篇”用于文章，不能说“上一篇口语课”。", "幕": "语义：“幕”指戏剧的段落，与口语课不搭。", "卷": "语义：“卷”指书册或试卷，不能用来计算一次课程。"}, "sentence_index": 6, "correct_answer": "期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这期冰箱很大。", "explanation": "这里应该用〈台〉。冰箱按台计算，“期”指一段时间或分期的一批，不能用来修饰冰箱。"}, {"text": "我们打了三期篮球。", "explanation": "这里应该用〈场〉。比赛按场计算，“期”指一段时间或分期的一批，不能用来计算比赛场次。"}, {"text": "这期画很漂亮。", "explanation": "这里应该用〈幅〉。画按幅计算，“期”指一段时间或分期的一批，不能用来修饰画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86473, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下个月想报名第二个期英语班。", "corrected_sentence": "我下个月想报名第二期英语班。", "error_description": "“第二期”是固定说法，“期”前不能再加“个”。应说“第二期”，不能说“第二个期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86473, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他参加了五第期英语培训。", "corrected_sentence": "他参加了第五期英语培训。", "error_description": "“第”应放在数词前，应说“第五期”，不能说“五第期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25df815a-9bf2-482a-8165-8451f0040811') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
